INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56614656621', 'Microfone sem fio de estilo de vida 2.4G para saxofone, trompa francesa, trombone e flauta', 'Experimente um som de qualidade de estúdio com o transmissor e receptor sem fio de 2,4 GHz para saxofone. Desfrute de áudio em alta definição, baixa latência e tecnologia anti-interferência para uma estabilidade de alcance de 30 metros. Capture perfeitamente as nuances do saxofone com captação unidirecional, ângulo de microfone ajustável e filtragem de ruído ambiente. Personalize o seu volume e toque por mais tempo com uma duração de bateria de 15 horas.', 135.0, 134.5, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134253-82583-mqy47c23fx1j79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F56614656621', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46352631998', 'Lakerain Corretivo para Pernas Maquiagem Corporal Impermeável, Cobre Tatuagens, Tom Uniforme 30ml', 'Informações do produto: Nome: MAKEUP PARA PERNAS Marca: lakerain Prazo de validade: 3 anos Peso bruto: 30ml Características: Corretivo, hidratante, à prova d''água e transferente, maquiagem de longa duração, uniformiza a pele Como usar: 1. Esprema a loção e aplique uniformemente na pele das pernas, e espere por 5-10 minutos; 2. Após secar, dê leves batidinhas na área aplicada com uma toalha de papel ou esponja de maquiagem para absorver o excesso de produto e dê leves batidinhas para permitir que a emulsão se misture melhor à pele e crie uma condição de pele natural e bonita.', 19.32, 11.92, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-822zp-mhzq3fc4tngl68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F46352631998', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
