INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27832918729', 'Umidificador de Ar 2L Aromatizador Luz LED Colorida Oásis OIH-6509', 'Com capacidade de 2 litros e uma taxa de umidificação de até 380ml/h, ele é ideal para manter o ambiente mais agradável, ajudando a reduzir os efeitos do ar seco e proporcionando uma atmosfera mais saudável. Além de funcionar como umidificador, também permite o uso de essências aromáticas, criando um ambiente perfumado e relaxante. Possui luz colorida suave, que adiciona um toque decorativo ao ambiente e pode ser usada como luz noturna. O desligamento automático garante segurança, desligando o aparelho quando a água atinge níveis baixos. Seu design moderno e compacto se adapta facilmente a qualquer ambiente, tornando-o uma excelente opção para uso em quartos, escritórios ou salas. ESPECIFICAÇÕES: - Modelo: OIH-6509 - Capacidade do reservatório: 2L - Taxa de umidificação: ≥ 380ml/h - Voltagem: 110V–220V - Potência: 25W (50Hz–60Hz) - Dimensões: 165x165x325mm - Luz colorida / Desligamento automático - Duração: 7 horas CONTEÚDO: 1 Umidificador de Ar e Aromatizador', 166.22, 125.0, NULL, 'Home Appliances > Small Household Appliances > Air Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7reor-m8f4cs1tisuv96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F27832918729', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
