INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18199168998', 'Cadeira Infantil de Praia Alta Cores Dobrável Alumínio Mor', 'Cadeira De Praia Alta Infantil Cores Dobrável Alumínio Mor No tamanho ideal para os pequenos, a Cadeira Alta Infantil é produzida pela Mor com materiais de excelente qualidade para garantir conforto e segurança. Sua estrutura é feita em tubo de alumínio, as peças plásticas são de polipropileno e sua tela é 100 % polietileno, suportando até 30Kg. Dobrável e fácil de carregar para onde quiserem, as crianças vão adorar ter uma cadeira para o tamanho delas. São ideais para praia, camping, brincadeiras ao ar livre e também podem compor a decoração do quartinho de meninos e meninas. Descrição do produto Marca: Mor Capacidade: 30 kg Material: Alumínio Peso: 680 gramas Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 141.92, 93.9, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdv3ped5r9xc06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F18199168998', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598370266', 'Soprador De Folhas ISV1846B Com 2 Baterias e Carregador Duplo Rápido Vonder', 'Soprador De Folhas ISV1846B Com 2 Baterias e Carregador Duplo Rápido Vonder O Kit Soprador a Bateria Vonder ISV1846B é a solução perfeita para quem busca praticidade, potência e autonomia na limpeza de áreas externas. Com motor Brushless de alto desempenho, painel com 4 velocidades + função TURBO e design ergonômico com alça tiracolo, você garante mais eficiência e conforto no uso. Acompanha 2 baterias 18V de 4,0 Ah e carregador duplo bivolt, ideal para manter o trabalho fluindo sem interrupções. Perfeito para soprar folhas, grama cortada, serragem e outros resíduos leves, além de secar superfícies lisas com facilidade. Itens que acompanham o produto 1 Soprador ISV1846B com alça tiracolo 2 Baterias 18V 4Ah IBV1804 1 Carregador Duplo ICBV 1841 Detalhes técnicos do soprador Modelo: ISV 1846B Motor Brushless (sem escovas) Painel com 4 velocidades + função TURBO Velocidade do ar: até 208 km/h Volume de saída de ar: até 828 m³/h Rotação máxima: 23.000 rpm Nível de ruído: 102 dB(A) Peso aproximado: 2,1 kg Detalhes técnicos da bateria Modelo: IBV 1804 Tensão: 18 V Capacidade: 4,0 Ah Tecnologia: Íons de lítio Indicador de carga Peso aproximado: 0,71 kg Detalhes técnicos do carregador Modelo: ICBV 1841 Bivolt automático (100V~ a 240V~) Frequência: 50/60 Hz Corrente de saída: 2,3 A Tempo de carga (4Ah): 120 min Peso aproximado: 0,78 kg Por que escolher este kit? Produto novo e original Pronta entrega e envio em até 24 horas Compra 100% segura', 1549.9, 1549.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rens-m83ex7zu1hux5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F22598370266', NULL, N