INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098928279', 'Esguicho Jardim Vonder 7 Tipos de Jato Engate Rápido 1/2 Uso Doméstico Limpeza e Irrigação', 'Esguicho Plástico para Jardim – Vonder 💧 Ideal para jardinagem, lavagem de veículos e limpeza em geral, o esguicho Vonder oferece 7 tipos de jato ajustáveis, garantindo versatilidade e eficiência. Conta com empunhadura ergonômica emborrachada, proporcionando maior conforto e controle durante o uso. 📦 Itens Inclusos: 📌 1 Esguicho para jardim ⚙️ Especificações Técnicas: 🔧 Material: Plástico ABS com empunhadura em borracha termoplástica 🔧 Conector: Engate rápido 1/2" 🔧 Tipos de jato: 7 funções ajustáveis 🔧 Tipo de jato: Múltiplo 🚀 Benefícios do Produto: ✅ Versatilidade com 7 tipos de jato para diversas aplicações ✅ Conforto no uso com empunhadura ergonômica emborrachada ✅ Fácil conexão com engate rápido padrão 1/2" ✅ Ideal para uso doméstico com excelente custo-benefício', 37.9, 37.9, NULL, 'Home & Living > Gardening > Irrigation Systems', 'https://cf.shopee.com.br/file/br-11134207-820mb-mmals15b162s80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F23098928279', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
