INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19298331165', 'Piscina Retangular 2500 Litros Estruturada Premium Mor', 'Piscina Retangular 2500 Litros Estruturada Premium Mor A Piscina Premium 2.500 litros Mor vai ser a principal diversão da família durante a época mais quente do ano. Com seu design moderno e inovador, é a melhor opção para quem curte ao máximo refrescar-se na água! Confeccionada em lona PVC monocromática, é dividida em duas lâminas e uma trama de poliéster entre elas. Possui ainda estrutura com acabamento em pintura epóxi à pó branca, garantindo maior durabilidade do produto. Acompanha duas válvulas de deságue e entrada para filtro, o que ajuda na conservação da água, tornando-a muito prática e funcional. Deixe os momentos de diversão muito mais animados com a Piscina Premium 2.500 litros Mor! Atenção! Nunca deixe crianças sozinhas perto da água sem supervisão de um adulto. Descrição do produto: Marca: Mor Material da estrutura: Aço pintado Material da piscina: Lona PVC Formato: Retangular Cor: Azul Capacidade: 2.500 Litros Medida da piscina com escoras: 2,71m x 2,24m x 60cm Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 886.78, 601.49, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Others', 'https://cf.shopee.com.br/file/sg-11134201-82598-mfydhgm2g0el47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F19298331165', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
