INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5570006136', 'Par De Lampadas H7 Super Branca Efeito Xenon 8500k', 'Descrição Par Lampadas Super Brancas H7 8500k Efeito Xenon Automotiva: Iluminação é tudo em um carro, pois ninguém merece dirigir por uma via mal iluminada e não conseguir enxergar obstáculos ou sinalizações, colocando a integridade do carro e a sua segurança em risco. Com este Par de Lâmpadas Super Brancas você deixa seu possante pronto para encarar qualquer uma dessas situações, proporcionando até o dobro de luminosidade. Além disso, ela ainda opera com 55W de potência, economiza muito da sua bateria e sua vida útil chega a ser até 3 vezes maior. Seu encaixe no padrão H4 garante instalação precisa no seu farol, proporcionando segurança total em seu uso e com tonalidade em temperatura de 8500K de cor branca você confere um visual altamente esportivo para o seu veículo. Especificação Técnica: - Lâmpada Super Branca - Tonalidade em 8500K - Efeito Xênon - Encaixe no Padrão H7 - 55W de Potência - Menor Consumo de Bateria - Vidros de Quartzo com Tecnologia UV-Block que Garante a Segurança das Lentes Plásticas dos Faróis - Vida Útil até 3 Vezes maior que Lâmpadas Comuns - Luminosidade com Até o Dobro de Alcance - Facilita a Visualização de Placas de Sinalização - Dispensa o Uso de Reator ou Relê', 40.31, 24.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbb60dk9kpe768', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357432948%2F5570006136', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
