INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24673313628', 'Colar Pingente Em Forma De Coração Vnox Round Bead Pendant , 18k Gold Big Choker Aço Inoxidável Para Acessórios De Moda Feminina', 'O Vnox da joia fala com joias Aço inoxidável de grau 316L (Seguro na pele e nas crianças, hipoalergênico e sem desbotamento) Tamanho: 43+8 cm ✈️Processamento e envio de processamento de envio✈️ Tempo de chumbo do chumbo: 1 A 3 dias Envio em cerca de 7 dias Faqs FAQS O mesmo se desvanece? (O Banhado a ouro é difícil de desbotar. Manterá em boas condições dentro de 1-3 anos se você se importa com isso. Antes de enviarmos, cada um de nosso produto passa por testes QC. Se você tiver algum problema de qualidade após o recebimento do pacote, sinta-se à vontade para entrar em contato conosco a qualquer momento.) Ocasião de usar? Desgaste diário/festa/presente/engajamento/aniversário/casamento é adequado, deixe as joias VNox transmitirem seu amor)', 41.26, 41.26, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/sg-11134201-7rccp-ltxmtr0dtcspbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F239158067%2F24673313628', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204529062', 'Jogo Perfil 8', 'Se você gosta de desafios, interação e boas risadas, o Perfil 8 é o jogo perfeito para reunir a família e os amigos! Com uma proposta envolvente e dinâmica, ele testa seus conhecimentos, sua intuição e, claro, sua habilidade de adivinhar com poucas dicas. Afinal… de quantas dicas você precisa? Perfil é um dos jogos mais populares da Grow, e acaba de ganhar sua tão aguardada nova edição: o Perfil 8! O desafio continua o mesmo: adivinhar com o menor número possível de dicas quem é a pessoa, qual é o lugar, o ano, o objeto ou o elemento do mundo digital, antes que os outros jogadores descubram! A grande novidade desta versão é que, dentre 350 cartas, 40 delas foram criadas pelos fãs, escolhidas entre diversas sugestões enviadas nós. Como jogar Perfil? Os participantes recebem uma lista de pistas sobre uma pessoa, lugar, objeto, ano ou tema digital. A cada dica revelada, o desafio fica mais fácil — mas quanto menos dicas você usar para acertar a resposta, mais pontos você ganha! É uma competição leve, estratégica e extremamente divertida. Por que você vai amar ter o Perfil 8 em casa? Porque ele é aquele tipo de jogo que une todo mundo: jovens, adultos, famílias, casais e amigos. É ideal para festas, encontros de fim de semana, viagens, confraternizações ou até para animar um dia comum. Cada rodada é imprevisível, surpreendente e cheia de revelações — sempre rendendo boas histórias e muita diversão. Ótimo também para presentear! O Perfil 8 é uma excelente opção de presente criativo para quem ama jogos de raciocínio, quem gosta de curiosidades ou quem simplesmente adora se divertir de maneira saudável e inteligente. Garanta já o seu e descubra quem da sua turma realmente precisa de menos dicas para adivinhar tudo! Transforme suas reuniões em momentos especiais com o jogo que conquista qualquer mesa. Compre agora e tenha o jogo favorito das noites de diversão! Idade: A partir de 12 anos Participantes: 2 ou mais Tempo estimado de jogo: 45 minutos', 149.99, 149.99, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-8262r-mk8ka035g26b3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545750185%2F58204529062', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
