INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793143710', 'Livro Patrulha Canina - Brincando com o alfabeto', 'Usando as letras do alfabeto, que são compostas por vogais e consoantes, podemos fazer várias combinações de sílabas, formando inúmeras palavras. Mas o que são vogais? E consoantes? E sílabas? Com as atividades propostas aqui e as letras em EVA que acompanham este livro, você aprenderá o alfabeto e formará muitas palavras. Vamos lá?_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2024_x000D_ Autor: Paloma Blanca Alves Barbieri_x000D_ Idioma: Português_x000D_ Páginas: 8_x000D_ Dimensões: L 20.00 x A 27.00 x E 1.09_x000D_ ISBN: 9786526110737_x000D_ Coleção: Alfabeto móvel_x000D_ Linha Editorial: Ciranda Cultural - Licenças_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Alfabeto, Conceitos, Brinquedo, Patrulha Canina_x000D_ BISAC: Não Ficção Infantil / Mídia Tie-in_x000D_ Linha de Produto: Alfabeto EVA_x000D_ Encadernação: Grampeado_x000D_ Acabamento: Verniz de máquina_x000D_ Material: Papel', 19.9, 19.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdya-lxmzp6xfw1rdd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F22793143710', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
