INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21099556997', 'PNEU 195/40 R17 TL 81W SPORT+ XBRI', 'Pneu Aro 17 Xbri 195/40 R17 TL 81W Sport + Sobre o Pneu: Pneu com alto desempenho, combinando controle em pista seca e molhada e uma baixa resistência ao rolamento. Os quatro sulcos oferecem uma excelente performance e um baixo nível de ruído. Sobre a marca A XBRI Pneus é uma marca privada que pertence à Sunset Tires Corporation, empresa que atua desde 1988 com foco em importação, exportação e distribuição de pneus, sendo a maior destes segmentos na América Latina. A Sunset decidiu introduzir produtos de marca própria desenvolvidos por uma equipe de engenheiros da empresa, sendo produzidos em fábricas de primeira linha no Vietnã, Malásia, Tailândia e China. Durante o processo de fabricação são efetuados controles de qualidade rigorosos e os pneus são projetados pensando em aspectos como nosso clima, estradas e rodovias para os segmentos de veículos comerciais leves, SUV, agrícola, industrial e de carga Informações Adicionais: - Marca: Xbri - Modelo: Sport + - Medida: 195/40 R17 - Largura: 195mm - Perfil: 40% - Aro: 17 - Índice de peso: 81 (462 Kg) - Índice de velocidade: W (270 KM/H) - RFT = RunFlat: NÃO - Tipo de construção: RADIAL - Sidewall: BSW - Letras pretas - Tipo de terreno: HT - Extra Load: Sim - Montagem: Sem Câmara - Desenho: Assimétrico - Garantia: 5 anos de Fábrica “POR FAVOR, VERIFIQUE SEMPRE NO VEÍCULO QUAL É A MEDIDA EXATA DO SEU PNEU”', 404.19, 404.19, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7req0-m2cjixn74n24dc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F882691919%2F21099556997', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994209218', 'Teclado para Notebook Dell Inspiron 14-3443', 'Teclado compatível com Dell Inspiron 14-3443 O teclado compatível com Dell Inspiron 14-3443 foi aprovado em rigorosos testes de qualidade e atende todas as exigências do seu equipamento, apresenta encaixe perfeito com o notebook, possui a mesma fixação da peça original. Além de 12 meses de garantia contra defeitos de fabricação. Atenção! Esse é um teclado bringIT, portanto não é um produto original da fabricante Dell. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Marca: bringIT Modelo: 14-3443 Moldura: Com Moldura Idioma/Layout: ABNT2 Backlight: Sem Iluminação Pointing Stick: Sem Pointingstick Cor: Preto Referência: TC625-DE-0023 Atenção: Para que esse teclado seja compatível com seu notebook, deverá ter as mesmas especificações de encaixe, layout e moldura. Esse produto é compatível com os notebooks: 14-3442, 14-5458, V147125AR1, 14-5458-B40, 14-3442-D30, 3480, 3450 3460 3470, PK1313P1A32, 14-3442-A10, 14-3000, 14-5447, PK1313P2A32, 14-3443, 0JNX71, 14-5468-A10P, 14-5000, 14-5458-D08P, 14-3467-M10M, 14-5457, 14–3468 Ficou na dúvida da compatibilidade ou precisa de mais informações? Deixe sua pergunta que nosso time técnico especializado está preparado para auxiliar! A bringIT é líder de mercado com o maior mix de produtos e peças para notebook: Baterias, telas, teclados e carregadores compatíveis com notebooks Dell, Lenovo, Acer, HP, Asus e muito mais!', 73.68, 41.05, NULL, 'Computers & Accessories > Peripherals & Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-825bc-mqsqqrfrble6f6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1097013207%2F23994209218', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
