INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260225180', 'Tênis Anabela Feminino Via Marte 046-019-01', 'O Tênis Feminino Via Marte é o aliado ideal para quem busca ganhar alguns centímetros de altura sem abrir mão da praticidade do calçado casual. Com um design moderno e versátil, este modelo Anabela é confeccionado em material sintético de alta resistência, garantindo durabilidade e um visual sempre impecável. Seu fechamento em cadarço permite um ajuste firme e seguro, enquanto a palmilha em EVA proporciona o amortecimento necessário para o uso prolongado. Com um salto de 6cm, ele eleva sua silhueta de forma discreta e elegante, sendo a escolha certa para compor looks que vão do jeans básico aos vestidos fluidos. Ref: 046-019-01', 449.99, 360.0, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-820ne-mnx8jsyuywp081', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1668934902%2F58260225180', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
