INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19097691086', 'Pneu Bridgestone Aro 17 Turanza T005 205/50R17 89V', 'Lançamento da BRIDGESTONE no segmento de alta performance, o pneu TURANZA T005 foi desenvolvido para entregar ao motorista maior controle do veículo e melhor frenagem, seja qual for a condição de direção, especialmente em pista molhada, proporcionando segurança e conforto ao dirigir. O desenho de sua banda de rodagem mantém um ótimo desempenho no piso molhado, mesmo com o desgaste progressivo do pneu. Seus sulcos longitudinais na banda de rodagem e transversais no ombros dos pneus, melhoram a tração no piso molhado e aumentam a estabilidade, além de contribuir para aumentar a resistência a aquaplanagem em curvas. Seus blocos com superfície arredondada melhoram o contato do pneu com o solo, garantindo assim, uma melhor frenagem. O novo formato do talão em "O", sem emendas, proporciona um perfeito assentamento do pneu na roda. O novo composto de borracha desenvolvido a base de uma nova geração de sílica, aumenta a aderência do pneu e reduz a resistência ao rolamento, proporcionando assim, economia de combustível. Sobre a marca Bridgestone Nascida em 1931 no Japão, a Bridgestone tem se dedicado a criar pneus que oferecem uma experiência única ao volante. Marcada por inovação, desempenho e compromisso com a segurança, os pneus Bridgestone proporcionam confiança em cada curva. Líder global no mercado de pneumáticos, a Bridgestone também estabeleceu sua marca com pneus de alta durabilidade e resistentes ao desgaste. Com forte investimento em pesquisa e desenvolvimento, a marca japonesa utiliza tecnologia avançada para garantir que cada pneu seja sinônimo de excelência.', 1025.87, 1025.87, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Agriculture Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd50-lvn95x70xzz947', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F19097691086', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
