INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493337137', 'Chicote Completo Farol De Milha Clio Todos H11', 'PRODUTO NOVO E DE ÓTIMA QUALIDADE! Kit Contém: 1 Chicote Completo 1 Botão Tic Tac (Brinde) 1 Relé (Brinde) Projetado para oferecer uma solução universal, este produto inclui chicote, relé e botão, facilitando a instalação dos faróis de milha. Recursos: • Chicote Completo: Inclui todos os cabos necessários para a instalação de ambos lados dos faróis de milha. • Relé e Botão Inclusos: Facilita o controle dos faróis de milha, proporcionando uma operação conveniente. Benefícios: • Facilidade de Instalação: Simplifica o processo de instalação dos faróis de milha em seu veículo. Testamos todos nossos produtos antes de enviarmos aos nossos clientes, temos garantia de até 90 dias. Obs.: Visando melhorar o nosso atendimento e compromisso com nossos clientes, solicitamos que qualquer duvida ou problema entre em contato conosco, nosso atendimento aos canais da Shopee são das 08:00 a.m as 18:00 p.m.', 78.9, 78.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/br-11134207-820lo-mojx6pv4g9hi46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1331941281%2F22493337137', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
