INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21997976123', 'Guarda Roupa Solteiro com Pés 4 Portas 2 Gavetas NT 6010 Notável Móveis', 'O Guarda Roupa Solteiro com Pés 4 Portas 2 Gavetas NT 6010 Notável Móveis, a escolha ideal para quem procura organização em espaços compactos. Com um design inteligente, este guarda-roupa oferece o espaço perfeito para arrumar suas roupas e acessórios. Equipado com um cabideiro interno, suas roupas permanecerão organizadas e livres de amassados. Além disso, suas duas gavetas com corrediças metálicas proporcionam fácil acesso e armazenamento conveniente para diversos itens. Características: 2 Gavetas 4 Portas 2 Prateleiras Cabideiro interno Corrediças metálicas Estrutura em MDP de 12mm Nicho Pés Dimensões: Altura: 187 cm Largura: 92,8 cm Profundidade: 39,7 cm Peso: 43,97 kg Garantia do fornecedor de 3 meses.', 539.9, 449.9, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md671xkyztwy81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F21997976123', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
