INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21797009964', 'Trena Métrica 3 Metros Em ABS - 3m X 16mm (709031) - Onsite', 'A Trena Métrica 3 Metros Em ABS - 3m X 16mm (709031) - Onsite, é o produto ideal para quem busca precisão e praticidade em suas medições. Com uma fita de 3 metros de comprimento e 16mm de largura, essa trena é ideal para uso em diferentes projetos, desde pequenas tarefas domésticas até trabalhos profissionais. Seu botão de trava garante que a fita permaneça fixa no local desejado, facilitando a leitura das medidas. Além disso, sua estrutura em ABS proporciona resistência e durabilidade, tornando-a uma ferramenta confiável para uso contínuo. Características: - Modelo: Trena 3 Metros e 16 Milímetros. - Comprimento da fita: 3M. - Com botão de trava. - Estrutura em ABS. Código: 709031. Marca: Onsite. Tamanho: 3m (10 ft) X 16mm. Ean: 6942629233541.', 10.5, 10.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qvfb-lhnf4t375fpp3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F21797009964', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
