INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493145719', 'Perfume Feminino LE VISITEUR Primacial', 'Sobre a fragrância Le Visiteur Le Visiteur é uma fragrância Oriental Amadeirada que transcende os limites da elegância feminina, redefinindo o conceito de sofisticação. Um elixir capaz de desvendar-se como um enigma pessoal, uma experiência inigualável. Sua jornada olfativa celebra a singularidade sofisticada do Jasmim com a profundidade quente de notas amadeiradas. Esta criação- personifica a confiança e a feminilidade com graciosidade e sofisticação. Le Visiteur é destinado à mulher que desafia o convencional, redefine a elegância e mantém um ar de mistério. É uma expressão máxima da elegância feminina e do mistério envolvente. Seu uso transforma momentos especiais em experiências memoráveis, deixando todos cativados e inspirados por sua singularidade. Deixe uma impressão inconfundível, revele sua verdadeira essência e exale confiança com Le Visiteur: a fragrância que une a elegância e o mistério. 🔴 Fixação: Longa, até 12 horas. 🔴 Projeção: Marcante, aproximadamente 2 metros. 🔴 Família olfativa: Oriental Amadeirado Pirâmide olfativa do Le Visiteur 🔺 Topo: Jasmim 🔺 Coração: Notas Amadeiradas 🔺 Fundo: Âmbar O que você sentirá no Le Visiteur Suas notas de topo celebram o jasmim, uma flor de singular beleza e fragrância encantadora. Em seu coração, as notas amadeiradas adicionam profundidade e complexidade à fragrância, como a intrigante madeira em uma floresta misteriosa. Nas notas de base, o âmbar traz um calor duradouro e uma marca inesquecível, como o pôr do sol em uma noite de elegância. Ocasiões para usar o Le Visiteur Le Visiteur é ideal para noites de inverno, acrescentando um toque de elegância e mistério a eventos sofisticados. Seu uso também combina muito bem com encontros românticos em climas mais frios. 🤫 Cupom Secreto: use o código PRIMACIAL e ganhe 5% de desconto. 🤫', 179.0, 164.0, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134201-820mb-mqxprht4qubp9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295467768%2F22493145719', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
