INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206658508', 'Ar Condicionado Janela Philco 7500 BTU/h Frio Eletrônico PAJ7FH - 220 Volts', 'Ar Condicionado Janela Philco 7500 BTU/h Frio Eletrônico PAJ7FH - 220 Volts O Ar Condicionado Janela Philco 7500 BTU/h Frio Eletrônico PAJ7FH possui capacidade ideal para climatizar ambientes menores com eficiênciaClassificação Energética A - Garante baixo consumo de energia com ótimo desempenho.Gás refrigerante R32 - Sustentável, eficiente e com menor impacto ambiental.Filtro lavável antipó e antibacteriano - Contribui para um ar mais puro e saudável.Serpentina em cobre - Maior resistência e durabilidade, sem oxidação pelo tempo.Pintura anticorrosiva - Proteção extra contra desgaste das partes metálicas.Diversas funções - Versatilidade para diferentes necessidades com as funções: Resfriar, Ventilar, Desumidificar e Turbo.Modos de operação - Praticidade e conforto ajustados ao seu estilo de vida com os modos: Dormir, Oscilar e Automático. Imagens meramente ilustrativas.', 2098.0, 2098.0, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-82599-mqz3dctjdclhea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1323031590%2F58206658508', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
