INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21598023169', 'Spray Rust-Oleum Stone Acabamento Pedra', 'Nome : Spray Rust-Oleum Stone Acabamento Pedra Marca: Rust-Oleum Pedra - Acabamento em Pedra Rust-Oleum® Stone é uma tinta spray que cria um acabamento decorativo texturizado semelhante à pedra e transforma objetos comuns em projetos únicos que imitam a aparência da textura da pedra. Adicione à maioria das superfícies e crie um acabamento durável em superfícies em áreas internas. Pode ser aplicado em madeira e metal Para projetos em áreas externas é necessário aplicar alguma proteção transparente Ultra Cover® 2X Após usar o spray é necessário limpar a válvula. Pode ser aplicada sobre madeira e metal Depois que usar o aerossol, lembre-se de limpar a válvula.', 75.2, 59.9, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdun0zvs1xa1ec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717380864%2F21598023169', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
