INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14432351147', 'Rockbros Lanterna Farol Bike Sensor Inteligente 1500mA Ciclismo Frente Luz Bicicleta MTB Road Bike', 'Descrição: Marca: ROCKBROS Modelo: QD-250LM Nome: Luz de bicicleta inteligente Material: Plástico ABS Lúmen: 250 lúmens Bateria: 1.250 lumens no modo de alto brilho podem durar 3 horas; 2.100 lúmens no modo de baixo brilho podem durar por 6,5 horas; 3.O modo Flash pode durar por 5 horas. Capacidade: 1500 mAH Faixa de Luz: 150 m Modos de luz: 4 modos (Sensor inteligente / alto / baixo / Flash) Carregamento: Carregamento USB Tamanho: Cerca de 102*34*30 mm Peso: Cerca de 85,5 g Características 1. Luz frontal de destaque de indução inteligente (com modo sensível à luz ligado, as luzes se ajustam automaticamente ao ambiente ajusta automaticamente o brilho das luzes dependendo do nível de luz ambiente) 2. Proteção diária da chuva não é um problema 3. Grande Design de holofotes 3. Pequeno, conveniente e fácil de transportar 4. Revestimento Skin-Like Para Maior Conforto 5. 250 Lumens Alto Brilho 6. Espelho altamente translúcido sem brilho 7. Clique conveniente para trocar 8. Interruptor de quatro modos livremente 9. Método de carregamento USB', 137.0, 93.84, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/246efbc24152ccbaccd7e793ae093815', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F236693054%2F14432351147', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
