INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23797978911', 'Kit Body Bebê Pop Cute Suedine Liso Manga Longa - 03 Peças', 'Kit Body Manga Longa Bebê Pop Cute Suedine Liso - 3 Peças O Kit Body Pop Cute é composto por três peças essenciais para o guarda-roupa do bebê de 0 a 12 meses. Confeccionados em suedine liso, estes bodies oferecem maciez e conforto para a pele sensível do bebê. As mangas longas são ideais para manter o bebê aquecido em dias mais frios, enquanto os botões de pressão na parte inferior facilitam as trocas de fraldas. Disponíveis em cores suaves, estes bodies são perfeitos para diversas combinações. Este kit é uma escolha prática e estilosa para o dia a dia do seu bebê. Os bodies podem ser usados sozinhos ou combinados com calças, jardineiras e macacões, criando looks variados e confortáveis. Além disso, a qualidade do tecido garante durabilidade e facilidade de manutenção, resistindo bem às lavagens frequentes. Ideal para presentear ou para completar o enxoval do seu bebê, o kit body é uma opção versátil e indispensável. Informações Adicionais: Tamanho: RN ao G Referência: 13901 Marca: Pop Cute', 79.9, 79.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Bodysuits & Jumpsuits', 'https://cf.shopee.com.br/file/sg-11134201-7rdx2-m1ms838c5ttp43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F23797978911', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
