INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698908344', 'Bola de Futevôlei Poker Vulcanizada Rio Oficial PU Branco Vermelho e Preto - Único', 'Controle e precisão para elevar seu jogo na areia! Bola de Futevôlei Poker Vulcanizada Rio Oficial PU Branco Vermelho e Preto - ÚnicoParte superior do formulário Ficha Técnica: Marca: Poker Gênero: Unissex Cor: Branco com detalhes em vermelho e preto Material: 100% Poliuretano (PU) impermeável com nylon laminado Tamanho: 5 Calibragem: 2 - 5 Libras Válvula: Removível Superfície de jogo: Futebol de praia Ano de lançamento: 2020 Tipo de costura: Colada Câmara: Borracha Detalhes: Formas triangulares em vermelho e preto e logo Poker Desempenho elevado exige equipamentos à altura. A Bola de Futevôlei Poker Vulcanizada Rio Oficial é ideal para quem joga com intensidade e busca toque suave e durabilidade em todas as partidas na areia. Porque investir: Fabricada em PU impermeável com tecnologia de laminação em nylon, ela garante ótima resistência à água e estabilidade nos passes. Seu design moderno em branco vermelho e preto completa o visual profissional. Conteúdo da embalagem: 1 Bola de Futevôlei Poker Vulcanizada Rio Oficial PU Branco Vermelho e Preto - ÚnicoParte superior do formulário', 219.99, 189.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Volleyball', 'https://cf.shopee.com.br/file/sg-11134201-824ib-meiuiwmwshkzcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1614877278%2F22698908344', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
