INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23196911571', 'Macaco Hidráulico Tipo Garrafa 5 Toneladas Vonder', 'Possui válvula de segurança para evitar elevação superior à sua capacidade, cabo dividido em 2 partes que facilita seu armazenamento e fuso de elevação com rosca que proporciona maior elevação e facilita o ajuste no momento da aplicação. Indicado para elevação de veículos ou cargas de acordo com sua capacidade. Usar, armazenar e transportar somente na posição vertical para evitar vazamento de óleo. Quantidade total de óleo hidráulico: 130,0 ml. Atenção: o operador jamais deve ficar embaixo de um veículo elevado/suspenso por macaco hidráulico, sem o posicionamento de cavaletes de apoio. Risco iminente de acidente grave. Capacidade de carga do macaco:5 toneladas (5 tf) Altura mínima do macaco:216,0 mm Altura máxima do macaco:413,0 mm Curso do pistão do macaco:127,0 mm Curso do fuso do macaco:70,0 mm Nº de estágios:1 Estágio hidráulico + fuso de ajuste Dimensões da base do macaco:115 mm x 114 mm Possui alça para movimentação:Não Massa aproximada (peso):4.33 kg Garantia legal: 180 dias concedida pela fabricante', 249.0, 156.84, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbk5-llup23r5uqfudc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F951290141%2F23196911571', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
