INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19998298195', 'Kit Cinto De Segurança Gm Corsa Classic Traseiros Retráteis', 'A Vai de Peças veio para se tornar líder nacional em vendas, atendimento e estoque em cinto de segurança, preparou o kit cintos de segurança para bancos traseiros, com várias cores disponíveis para você escolher, com o melhor preço do mercado e mais kit Parafusos de brinde para você dar uma renovada no seu carro. O kit é composto por: 02 unidades: Cinto retrátil 3 pontos com fêmea. 01 unidade: Cinto abdominal (macho e fêmea). 01 kit: parafusos de fixação. Características: Materiais dos componentes: Poliéster, Aço carbono temperado e ABS. 1 anos de garantia. Materiais dos componentes: Poliéster, Aço carbono temperado e ABS. 2 anos de garantia. Medidas: Retrátil: 3,20 metros Abdominal: Macho com 1,20 metros e Fêmea fita com 50 cm Obs. Poderá escolher a cor do kit em “Opções de cores”. Preto, Cinza, Vermelho e Bege. Montado com marcas consolidadas no mercado por sua qualidade e segurança. Acidente de Trânsito é uma das maiores causas de morte no país. São dados tristes, mas que é importante saber para entender a razão do cinto de segurança ser fundamental. A. Benefícios do uso do cinto de segurança: Reduz o risco de ferimentos graves em acidentes de trânsito. Mantém o corpo estabilizado, evitando o impacto contra o volante ou painel. Garante segurança e conforto durante a condução. Atende às normas de segurança veicular exigidas por lei. Evita multas e pontuação na CNH por uso incorreto. Indicado para todos os veículos: carros, caminhonetes e utilitários. Fácil instalação e reposição, ideal para manutenção preventiva. Custo-benefício alto, sendo essencial para a segurança automotiva. Recomendações: - Instalar com apoio de profissional qualificado. - Garantia de 6 meses.', 238.53, 238.53, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gk-mel06ycva58me0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1604698269%2F19998298195', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
