INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14919540432', 'Jogo escova de latão com haste 6 mm 3 peças 744869 - MTX', 'Produto: Jogo escova de latão com haste 6 mm 3 peças - 744869 Marca: MTX Descrição: O Jogo Escova de Latão com Haste 6 mm 3 Peças 744869 MTX" é ideal para limpeza, remoção de ferrugem, tinta antiga e preparação de superfícies. Indicado para manutenção, reparos e trabalhos profissionais, oferece excelente desempenho em metais, madeira e plástico, sendo uma solução prática para oficinas, indústrias e uso doméstico. O kit é composto por 3 escovas com cerdas de latão: 1 escova plana de 50 mm e 2 escovas tipo copo de 25 mm e 50 mm, permitindo trabalhar tanto em áreas amplas quanto em cantos e locais de difícil acesso. A haste de 6 mm destas Escovas de latão MTX" garante encaixe seguro em ferramentas compatíveis, proporcionando mais praticidade durante o uso. Características: • Rotação de até 4500 rpm para uma limpeza rápida e eficiente, removendo sujeira e camadas antigas sem danificar o material base • Construção resistente, desenvolvida para suportar o uso frequente e oferecer maior durabilidade • Cerdas de latão e acabamento zincado que aumentam a resistência Ã corrosão e prolongam a vida útil das escovas Se você procura um jogo de escovas com hastes resistente e funcional, o MTX 744869 é uma excelente opção. Especificações: Tipo: Jogo de escovas aço circular Material do fio: Aço de alta qualidade Acabamento: Zincado (corpo) e cerdas de latão (proteção anticorrosiva) Diâmetro da haste: 6 mm Velocidade máxima suportada: 4500 RPM Quantidade de peças: 3. Itens Inclusos: 1 Escova de aço plana 50 mm 1 Escova de aço tipo copo 25 mm 1 Escova de aço tipo copo 50 mm. Peso: 0.23 Kg', 30.75, 30.75, NULL, 'Home & Living > Home Care Supplies > Cleaning Brushes', 'https://cf.shopee.com.br/file/sg-11134201-8259k-mr4cjx