INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209718720', 'Limpador Multiuso Veja Power Fusion Limão', 'Veja Power Fusion é a eficiência de Veja Multiuso, com a poderosa mistura de extrato de limão, bicarbonato e álcool. Máximo poder de limpeza nas sujeiras mais difíceis, restaura o brilho e seca rápido. O melhor multiuso de todos os tempos. Aplique o produto nas superfícies a serem limpas e, em seguida, passe um pano ou esponja macia. Para as sujeiras mais difíceis, deixar o produto agir por alguns instantes. Para superfícies verticais, recomenda-se aplicar o produto diretamente no pano. Atenção: para painéis de fogões: limpar com a superfície fria. Não usar em superfícies de madeira natural. Para superfícies de alumínio, mármore e superfícies pintadas/esmaltadas e com serigrafia, limpar imediatamente após a aplicação. Recomendação: Testar em uma pequena área escondida antes de usar.', 12.79, 12.79, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8259f-mqnel007hdzfca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555116%2F58209718720', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
