INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21259970897', 'Filtro Ar Fiat Strada 1.8 8v 2004 A 2017 Wega', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação STRADA ADV/ADV TRYON 1.8 MPI FLEX 8V CE 2005 até 2008 STRADA ADVENTURE 1.8 MPI 8V 103CV CE 2004 STRADA ADVENTURE 1.8/ 1.8 LOCKER FLEX CE 2009 até 2017 STRADA ADVENTURE1.8/ 1.8 LOCKER FLEX CD 2010 até 2017 STRADA TREKKING 1.8 MPI FLEX 8V CE 2005 até 2010 STRADA TREKKING 1.8 MPI FLEX 8V CS 2004 até 2012 STRADA WORKING 1.8 MPI 8V 103CV CE 2004 STRADA WORKING 1.8 MPI 8V 103CV CS 2004 Conteúdo Da Embalagem 1 Filtro de Ar Tipo de Veículo para Carros Marca A Wega é uma empresa que pensa em primeiro lugar em seus clientes, tem como missão satisfazer plenamente as necessidades do mercado brasileiro, fornecendo peças automotivas de alta qualidade. A visão da Wega é ser uma empresa reconhecida no mercado, com base na ética e no crescimento sustentável e inovador. O Produto O filtro de ar é de extrema importância, por que ele elimina as impurezas que existem no ar do carro, para a mistura ar/combustível gerar uma combustão perfeita. Se o seu filtro estiver sujo e velho seu carro não passa na inspeção veicular, sem contar que se você rodar com o filtro de ar sujo seu consumo de combustível vai ser bem mais alto. Importante > Recomendamos que os produtos sejam instalados por profissionais especializados e não se responsabiliza pelo mal uso ou instalação indevida, causando a perda da garantia.Tempo de garantia: 3 Meses Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078Imagem meramente ilustrativaValor unitário EAN 7798001692388 Código do Fabricante FAP2831_WEG >', 21.2, 21.2, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rblf-llts5zr4rr450