INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18961902595', 'Filtro Óleo Chery S18 1.3 16v 2012 Tecfil', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação S-18 1.3 16V FLEX MEC. 5P 2012 Conteúdo Da Embalagem 1 Filtro de Óleo Tipo de Veículo para Carros Marca A Tecfil, fundada em 1953, é especialista no segmento de Filtros Automotivos e atualmente é a maior fábrica de filtros da América Latina. Além de ser a líder e maior referência do mercado no segmento de reposição automotiva, a empresa possui todas as certificações exigidas no mercado, o que lhe confere diferenciais de qualidade. O Produto Com a finalidade de remover os resíduos indesejáveis que podem estar contidos no óleo do motor, o f iltro de óleo é feito com um papel especial, que está contido dentro da carcaça do filtro. O óleo sujo pode causar entupimento do motor podendo causar até a fundição do mesmo. Importante • Tempo de garantia - 3 meses • Imagem meramente ilustrativa • Valor unitário • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 7891342000673 Código do Fabricante PSL145 >', 15.46, 15.46, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbkv-llv05putjak9ba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F18961902595', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
