INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398113446', 'Conjunto Marmita Térmica 5 Unidades Cinza Tekcor Soprano', 'Conjunto Marmita Térmica 5 Unidades Cinza Tekcor Soprano 09003.1333.12 A mais tradicional e popular marmita do mercado, atendendo suas necessidades na medida certa. Muito utilizado em ambientes corporativos, construção civil, agricultura ou até mesmo no dia-a-dia para buscar comida em restaurantes. Conserva os alimentos em temperatura ideal para consumo. Possui presilhas para fechamento e alça robusta para transporte. Pode ser utilizado no microondas (sem a tampa). Disponível sem divisão interna, com divisão interna dupla e divisão interna tripla. Também disponível em conjuntos com até 5 unidades. Capacidade 1,5 litros; isolamento térmico em EPS. Livre de Bisfenol (BPA Free). Eficiência Térmica: Quente - 4 horas Frio - 4 horas Principais características: Presilhas para fechamento Alça robusta para transporte Pode ser utilizado no micro-ondas (sem a tampa) Isolamento térmico em EPS Livre de BPA. Outras características: Capacidade: Cinco compartimentos de 1,5 litros cada Dimensões do produto: 22,1 x 20,3 x 48,5cm Peso: 1,2550kg Material: Polipropileno (PP) e Poliestireno Expandido (EPS) Conteúdo da embalagem: 3 marmitas sem divisão, 1 marmita com divisão dupla, 1 marmita com divisão tripla. Garantia: 90 dias contra defeitos de fabricação', 94.9, 91.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7rfhd-m48z6e37od3553', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844004880%2F22398113446', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
