INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14740553376', 'Meia Cano Longo Oggi Branco/Preto', 'Meia Cano Longo Oggi Branco/Preto As meias Oggi são fabricadas em material de alta qualidade, proporcionando conforto, durabilidade e melhor desempenho para você. A composição garante a transpiração e evaporação de suor adequada para a prática de esportes, evitando que a meia fique encharcada causando grande desconforto. A modelagem é anatômica, ajusta-se ao pé, sem que a malha ceda e fique folgada. Esta resistência também se aplica aos inúmeros designs disponíveis, os quais não perdem cor ou forma. O conforto é uma condição imprescindível para a realização de qualquer atividade, e é exatamente isso o que você terá ao adquirir a meia da Oggi. Seja utilizando a sua meia para corrida, ciclismo, ou, na prática de qualquer esporte, as meias Oggi garantem o conforto necessário para o seu melhor desempenho. Especificações da Meia Cano Longo Oggi Branco/Preto - Tamanho único - veste do tamanho 36 ao 42; - Composição: 97% Poliamida e 3% Elastano. - Estilo meia canela.', 19.31, 19.31, NULL, 'Women Clothes > Socks & Stockings > Socks', 'https://cf.shopee.com.br/file/570b7bcbed0a3599578eb51629c9e7c7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F14740553376', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
