INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21397996714', 'Chuteira Society Topper Maestro Club V Leve Confortável Original Resistente', 'Chuteira Society Maestro Club V Topper Fut 7 Unissex Confortável Original Topper Eleve o seu futebol a outro nível com a Chuteira Society Topper Maestro Club V. Desenvolvida para jogadores que valorizam controle, velocidade e estabilidade, ela reúne tecnologias exclusivas e materiais de qualidade para proporcionar máxima performance nos gramados sintéticos. Destaques do Produto: - Tecnologia T-Control - Mais controle e sensibilidade no contato com a bola para jogadas mais precisas. - Tecnologia T-Support - Maior estabilidade e agilidade para dribles e movimentações rápidas. - Solado Society em Borracha - Excelente aderência e tração em gramados sintéticos. - Leveza e Conforto - Peso aproximado de 300g, proporcionando mobilidade sem abrir mão da resistência. - Design Moderno - Visual esportivo que combina estilo e desempenho dentro das quatro linhas. Benefícios: - Melhor controle de bola durante o jogo. - Mais estabilidade em arrancadas e mudanças de direção. - Excelente aderência para gramados sintéticos. - Conforto para partidas e treinos prolongados. - Estrutura resistente para acompanhar sua rotina esportiva. Indicação de Uso: Ideal para partidas e treinamentos em campos de grama sintética (society), oferecendo desempenho, conforto e segurança para jogadores de todos os níveis. Produto Original Topper: Seja para uma partida decisiva, um campeonato ou aquele tradicional jogo com os amigos, a Chuteira Society Topper Maestro Club V é a escolha certa para quem busca qualidade, conforto e performance em cada lance. Disponível na Usee Brasil! Chuteira Society Topper Maestro Club V: mais controle, estabilidade e agilidade para você dominar o jogo do início ao fim.', 399.99, 209.99, NULL, 'Sports & Outdoors > Sports Footwear > Soccer Shoes', 'https://cf.shopee.com.br/file/br-11134207-820m2-mpjtljwd5hc07e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349198275%2F21397996714', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
