INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48250758879', 'Mangueira Para Irrigação Rolo Com 100m Modelo II VONDER', '***PRODUTO A PRONTA ENTREGA COM ENVIO IMEDIATO*** PRODUTO ORIGINAL COM NOTA FISCAL 1 Rolo com 100 m. Possui um raio de alcance de 2 m e altura de aspersão de 0,5 m. A mangueira é plana e perfurada a raio laser, proporcionando maior precisão e uniformidade dos emissores, assim como a eficiência na aplicação da água. Indicada para irrigações. Irriga somente caule e raiz, para plantas que não podem receber água nas folhas. Cor da mangueira: Preto Material da mangueira: Polietileno Comprimento da mangueira:100,00 m Diâmetro interno:1.1/8"- 28,5mm Espessura da parede:0,2 mm Posição dos furos da mangueira para irrigação: Lateral Espaçamento entre furos da mangueira para irrigação:15,0 cm Altura do jato da mangueira para irrigação:0,50 m Raio de alcance:2,00 m Pressão máxima de trabalho:2,84 lbf/pol² a 11,38 lbf/pol² Massa aproximada (peso):2.5 kg', 128.9, 109.9, NULL, 'Home & Living > Gardening > Irrigation Systems', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi0ixqzlkdtt30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F48250758879', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
