INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19197763194', 'Paçoquita Rolha Embalada Caixa 150G (10 Unidades) Santa Helena', 'Tradicional produto brasileiro à base de amendoim, a Paçoquita é líder nacional no seu segmento e conquista consumidores e clientes a cada dia. Graças ao seu diferenciado sabor e um rigoroso controle de qualidade e de matéria-prima, é um produto apreciado por consumidores de todas as idades há mais de 25 anos. Contém 10 unidades INGREDIENTES:amendoim torrado e moído, açúcar e sal. ALÉRGICOS: CONTÉM AMENDOIM. NÃO CONTÉM GLÚTEN. Produto isento de registro sanitário, conforme resolução RDC nº 27/2010 ANVISA Guardar em local fresco e seco.', 49.7, 49.7, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/sg-11134201-7rdw4-lyds1nb03790b6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F19197763194', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18610047503', 'FAROL GOL 2005 G4 MASCARA NEGRA POWER LADO DIREITO', 'O farol é uma peça essencial para sinalização e visibilidade em vias noturnas e para maior segurança eles devem estar sempre em bom estado.Este item possui material de alta qualidade e resistência, composto com sua lente em acrílico lisa, encaixe da lâmpada H4 que suporta até 55W e um design que deixa seu carro com aspecto diferenciado de todos os outros.Compatível com: Volkswagen- Gol G4 2005- Gol G4 2006- Gol G4 2007- Gol G4 2008- Gol G4 2009Especificações Técnicas:- Máscara Negra- Foco Simples- Encaixe da Lâmpada H4- Lente Lisa- Material da Lente em Acrílico- Material da Carcaça em Plástico- Suporta Lâmpadas de até 55WConteúdo da Embalagem:- 1 Farol Dianteiro Máscara Negra PowerImportante:A Like Parts recomenda que a instalação seja feita por profissional especializado e não se responsabiliza pelo mau uso do produto.', 220.9, 220.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rbls-lq3cv4h4vqzk35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379659661%2F18610047503', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492410110', 'Chaleira Bule De Vidro Com Infusor De Inox Direto Ao Fogo Resistente Ao Calor 750ml', 'SOBRE O PRODUTO Os amantes de um bom chá vão adorar essa novidade. Os bules para chá com infusor proporcionam uma ótima experiência de degustação e podem ser levados para todos os lugares. O bule é feito em vidro com acessório em aço inox. As peças são muito fáceis de usar e de limpar, garantindo um bom chá em qualquer hora do dia. ESPECIFICAÇÕES TÉCNICAS Altura: 12cm Capacidade: 750ml Material: Tampa e Filtro em Aço inoxidável, Vidro Borossilicato Resistente a Micro-Ondas e Lava-Louças: Sim Tipo de embalagem: Papel Pardo Decoração: Lisa Cor: Transparente', 84.9, 49.9, NULL, 'Home & Living > Kitchenware > Tea, Coffee & Bartending Equipments', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mdvvrnq94xkybb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455103761%2F23492410110', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798359270', 'Vedador Partida Frio Gol G5 G6 G7 Voyage Saveiro', 'VEDADOR SUPERIOR DO RESERVATORIO DE PARTIDA A FRIO USADO NO GOL G5 G6 G7 VOYAGE SAVEIRO FOX COMPRAS EFETIVADAS ATÉ AS 10:00H, SERÃO ENVIADAS NO MESMO DIA! PARA AVERIGUAÇÃO DE COMPATIBILIDADE, É NECESSÁRIO A NUMERAÇÃO COMPLETA DO CHASSI. PRODUTO NOVO, ORIGINAL! SOMOS CONCESSIONÁRIA VOLKSWAGEN. TIRE TODAS AS DÚVIDAS PELO CAMPO DE PERGUNTAS ANTES DE EFETUAR A COMPRA. VERIFIQUE SEU ENDEREÇO DE ENTREGA. SERÁ COBRADO UM NOVO FRETE CASO O PRODUTO RETORNE. FIQUE ATENTO AS SUAS MENSAGENS. GARANTIA: PEÇAS ORIGINAIS COMPRADA NA REDE VW TEM GARANTIA NACIONAL, SENDO QUE, SE A PEÇA FOR INSTALADA EM UMA CONCESSIONÁRIA TERÁ GARANTIA DE 1 ANO, INSTALAÇÃO FEITA EM OUTRA OFICINA TERÁ GARANTIA DE APENAS 90 DIAS! “AS PEÇAS ORIGINAIS VOLKSWAGEN REPRESENTAM SEMPRE A MELHOR ESCOLHA. UMA LINHA COMPLETA DE PEÇAS PROJETADAS, TESTADAS E PRODUZIDAS COM ALTO RIGOR TECNOLÓGICO PARA PROPORCIONAR O MÁXIMO EM DESEMPENHO COM CONFIABILIDADE E A MESMA SEGURANÇA DAS PEÇAS UTILIZADAS EM UM VEÍCULO ZERO QUILOMETRO”. CORREAUTO VW VOCÊ MERECE UM ATENDIMENTO 5 ESTRELAS!', 14.9, 14.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rd4s-m7v3ctuhk3on7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1182059565%2F22798359270', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097035174', 'Filtro Ar Cabine Gm Corsa 2007 a 2012 - 187341 - AKX35159', 'Filtro Ar Cabine Gm Corsa 2007 a 2012 187341 AKX35159 (Hatch / Premium / Maxx ) - Motor 1.4 8v Econo Flex - (Mecãnico) - (Sem carvão) (Abas laterais) Os filtros do ar para cabine são produzidos com fibras carregadas eletrostaticamente. Este filtros possuem camadas protegidas de um lado por um pré-filtro para reter partículas maiores. Do lado oposto possui uma camada de proteção a danos ao filtro.A função do meio filtrante é remover a maior quantidade possível de contaminantes do sistema do ar, oferecendo o mínimo de restrição ao fluxo de ar.', 31.66, 31.66, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rasz-maop3trzwjf5d8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22097035174', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51260378882', 'TÊNIS EVERLAST FREEPORT MASCULINO', 'O tênis Everlast Freeport une estilo e conforto para o dia a dia. Seu cabedal em mesh laminado proporciona leveza e respirabilidade, enquanto a entressola em EVA garante um caminhar confortável e amortecido. O solado de borracha oferece aderência e durabilidade, ideal para diversas atividades urbanas. A tecnologia E-shield adiciona uma camada extra de proteção contra impactos e desgaste. Detalhes na lateral, com a escrita e o logo da Everlast, conferem um toque moderno e autêntico ao design. Perfeito para quem busca um visual casual e sofisticado. Tecnologia: E-Shield: Tecido tecnológico que ajuda a evitar odores nos pés. Principais características: Tipo de amarração: Cadarço Tipo de pisada: Neutra Altura do cano: Baixo Indicação: Casual Conteúdo da embalagem: 1 par Garantia do fabricante: Contra defeito de fabricação Material / Composição: Cabedal: Mesh / Laminado Entressola: EVA Solado: Borracha Limpeza e conservação: Limpar com pano umedecido. Cuidados com o produto: Para ajudar na remoção de odores, deixar o produto em local seco e arejado por aproximadamente 12 horas. Informações básicas: Referência: SEMA277 Nome: Tênis Everlast Freeport Marca: Everlast Gênero: Masculino Faixa etária: Adulto Grupo / Sub-grupo: Calçados / Tênis Origem: Nacional', 219.99, 176.0, NULL, 'Sports & Outdoors > Sports Footwear > Training Shoes', 'https://cf.shopee.com.br/file/sg-11134201-822z1-mo5q5mx2tibp82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F628754867%2F51260378882', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594418246', 'Película de Vidro Esr pra iPhone 16 Pro Max Transparente', 'Película de Vidro Temperado ESR para iPhone 16 Pro Max, Transparente, Proteção e Ajuste Perfeito 1. Proteção Avançada contra Arranhões e Impactos: A Película de Vidro Temperado ESR para iPhone 16 Pro Max oferece uma proteção robusta contra arranhões, quedas e impactos, garantindo que a tela do seu dispositivo permaneça segura e sem danos durante o uso diário. 2. Ajuste Perfeito para iPhone 16 Pro Max: Desenvolvida com precisão para o iPhone 16 Pro Max, esta película proporciona um encaixe perfeito, cobrindo toda a tela sem comprometer o design original do dispositivo ou sua funcionalidade. 3. Transparência Cristalina: A película mantém a clareza da tela do iPhone 16 Pro Max, permitindo uma exibição nítida e vibrante. Sua transparência não interfere na qualidade das imagens ou vídeos, garantindo uma experiência visual impecável. 4. Alta Sensibilidade ao Toque: A película de vidro temperado proporciona uma resposta sensível e precisa ao toque, preservando a funcionalidade da tela sensível ao toque sem comprometer a experiência de uso. 5. Instalação Fácil e Sem Bolhas: Com tecnologia de aplicação avançada, a instalação é rápida e sem bolhas, garantindo um processo sem complicações. A remoção também é simples, sem deixar resíduos ou danificar a tela do dispositivo. Garantia 90 dias.', 50.31, 50.31, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/br-11134275-81z1k-meu0e09g9e6933', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163359442%2F23594418246', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497029672', 'Filtro Ar Ford Fiesta 2002 a 2006 - 121821 - FAP9008', 'Filtro Ar Ford Fiesta 2002 a 2006 121821 FAP9008 (Supercharger) - Motor 1.0 8v - Gasolina - _x000D_ (Mecânico) Após passar pelo filtro, o ar é aspirado pelo motor através de seus êmbolos (pistões). Durante este processo, sensores do sistema de injeção eletrônica enviam sinais para o Módulo da Injeção Eletrônica do Veículo, informando a temperatura do ar que está sendo admitido. O filtro do ar é construído para que as impurezas em suspensão no ar sejam separadas, ficando as mais pesadas depositadas no fundo da caixa de filtração e as mais leves sendo retidas pelo elemento filtrante.', 47.74, 47.74, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbnb-lmt6drxnzrmx16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22497029672', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693894648', 'Cabo Freio Mão Fiat Palio 1997 a 2015 - 100440 - 3212', 'Cabo Freio Mão Fiat Palio 1997 a 2015 100440 3212 WEEKEND DIREITO (1465mm - EXCETO ADVENTURE) O cabo de freio de mão é um cabo de aço que ao ser "puxado" pressiona as lonas do freio traseiro contra as rodas, mantendo-as travadas.', 62.53, 62.53, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7renr-m8gg94vllp5j02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23693894648', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
