INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198022740', 'Mochila Playset Batalha de Praia - Pokémon', 'Descrição: Se divirta, batalhe e pegue um sol no novo playset de batalha de Pokémon na praia! Esse novo playset vai te transportar diretamente para uma arena de batalha na praia, com acessórios ricos em detalhes para deixar a sua brincadeira única, o conjunto também leva uma figura do Pikachu! Apresentando detalhes autênticos, parecem ter saído diretamente da série animada. Se divirta e torne-se o maior treinador Pokémon do mundo, mostre suas habilidades e vença qualquer desafio! Características: Marca: Sunny Brinquedos Referência: 3487 Idade recomendada: A partir de 3 anos Pilhas Inclusas? Tipo de Pilha/Bateria Não necessita de pilhas Possui Luzes: Não Possui Sons: Não Dimensões aproximadas da embalagem: 27,5 x 18 x 15,3cm (A x L x C) Garantia: 3 meses a contar da emissão da Nota Fiscal Embalagem: Conteúdo da embalagem: 1 Playset e 1 Boneco Certificado Inmetro: REGISTRO 004078/2021 Produtos de decoração não inclusos. Imagens meramente ilustrativas. As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 549.99, 516.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7reoj-m2k1tgeraz7k93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F23198022740', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
