INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597896382', 'Coxim Amortecedor Suspensao Dianteira Focus 2009 A 2019', 'GRUPO AMAZONAS - SUA CONCESSIONARIA VIRTUAL Ford Studio CODIGO PECA: BV613K155C2B APLICACAO Aplicacao universal ou nao informada, se tiver duvida, nos faca uma pergunta. OBSERVACOES E CONDICOES DA LOJA Antes de efetuar a compra tire todas suas duvidas no campo perguntas; Para pecas mecanicas tecnicas confirme a aplicacao com seu mecanico; Nao use enderecos de caixa postal, transportadoras nao entregam; Nao nos solicite dados de contato, o nao permite esta troca de informacoes; Efetue a compra com CPF, pois no CNPJ o imposto sera maior; Mantenha seus dados e enderecos atualizados no site do ; Se a Shopee Express nao entregar o produto, lhe devolvera o pagamento; Temos carrinho de compras, adicione varios produtos e economize no Frete; Todos os nossos produtos sao novos com garantia de 3 meses e acompanham nota fiscal. Todos os produtos anunciados estao disponiveis em nosso estoque. Para devolucao de produtos, somente com embalagem original e Nota Fiscal. SUPORTE E HORARIOS DE ATENDIMENTO: - Temos Equipe de Atendimento e Suporte Tecnico Especializado a sua disposicao. - Atendimento de Seg. a Sex. das 8h00 as 18h00. - Fechamos para almoco das 12h00 as 13h15.', 362.92, 362.92, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Stickers and Emblems', 'https://cf.shopee.com.br/file/sg-11134201-7rdxb-m0stde2wkbycf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1368280282%2F23597896382', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8972995694', 'Central Multimídia Usb Mp5 Player 7 Pol 1 Din Fiat Palio', 'Central Multimídia MP5 1din com Bluetooth, Porta USB, SD e Espelhamento Via Cabo Itens inclusos: - Central Mp5 1din 7 polegadas - Câmera de Ré Características: • Tela 7 Polegadas • Conectividade • Rádio FM • Entrada para Cabo Auxiliar • Suporte para Câmera de Ré • Visor com Data/Hora Digital • Entrada SD (Até 32 GB) • Entrada USB • Led Botões Coloridos Especificações: • MP5 • USB/SD • FM • Bluetooth • Entrada de Câmera Traseira • Entrada Aux • Tamanho da tela: 7 polegadas • Resolução da tela: 800*480 Pixels • Idiomas do menu OSD: Inglês, Chinês, Espanhol, Português, Russo • Formato de vídeo: RMVB/RM/FLV/3GP/MPEG/DIVX/XVID/DAT/VOB/AVI/ MP4 • Formato de áudio: MP3/WMA/OGG/APE/AAC/FLAC/WAV • Formato de imagem: JPG • Amplificador de potência de saída/canal qtde. : 45 w * 4 • Interface: USB/TF/AUX EM • Tensão de entrada: 12V • Bluetooth versão: V3.0 • Senha de Logo inicial: 8888 • Tamanho: 180mm * 103mm (7.08 de polegada * 4.06 polegada) Observações: Recomendamos que a instalação seja feita por um profissional qualificado. Não nos responsabilizamos por defeitos causados por mau uso ou instalação incorreta!', 374.57, 333.07, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > GPS Navigators', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lu54gynab2ao95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F8972995694', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9468458787', 'Kit 2 Auto Falante 6 Pioneer Ts-1760br 200w 3 Vias 100w Rms', 'ALTO FALANTE PIONEER TS-1760BR 200W 50W RMS IMPEDÂNCIA 4OHMS - PAR O TS-1760BR é o alto-falante de 6 polegadas para quem busca durabilidade e performance. Seu cone de polipropileno injetado garante a qualidade de reprodução com baixo nível de distorção, contando ainda com um tweeter piezoeléctrico para intensificar os sons agudos e completar seu conjunto automotivo. Com profundidade de instalação reduzida, é também uma excelente opção de design, facilitando ainda a sua adequação a uma grande variedade de veículos ESPEFICICAÇÕES TÉCNICAS Midrange com cone de filme de Ø30 mm Woofer com cone de IMPP (Polipropileno moldado por injeção) Bobina de voz resistente ao calor Tremeter piezoeléctrico de Ø11 mm em PET Suspensão boleada Potência máxima - 200 W Potência de entrada nominal RMS - 50 W Resposta em frequência - 40 Hz a 20.000 Hz Sensibilidade (1 W / 1 m) - 86 dB Impedância - 4 ohms Profundidade de instalação – 46 mm Dimensões do alto-falante - Ø165 mm x 61 mm Dimensões para corte - Ø144 mm IMPORTANTE Produto compatível com carros que tenham espaço para alto falantes de 6” polegadas CONTEÚDO DA EMBALAGEM 1 par de alto-falantes 8 parafusos Certificado de garantia Lista de postos de assistência técnica ATENÇÃO! Compatibilidade: - Uso universal (Dianteiro e/ou Traseiro (Obs.: Desde que veículo tenha espaço para instalação Alto Falante 6 polegadas). - Alguns veículos podem requerer algumas pequenas adaptações que somente devem ser feitas por um técnico ou profissional do ramo. Toda e qualquer e adaptação e´ de responsabilidade do proprietário do veículo. A instalação deve ser realizada por um profissional especializado. "Ouvir música com potência acima de 85 decibéis pode causar danos ao sistema auditivo" (Lei Federal n°11.291/06). OESTESOM A MELHOR LOJA DE PRODUTOS AUTOMOTIVOS NA INTERNET!', 180.16, 157.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/263a3f5584e4b52f1f377fa6984ccc65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F9468458787', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
