INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259455754', '3 Corações Extraforte Café Torrado e Moído', 'O clássico café extraforte 3 Corações, perfeito para quem busca um sabor marcante e intenso. Produzido com um blend especial de grãos do Sul de Minas, ele garante um café encorpado e com aroma intenso. Preparo: 1. Para cada litro de água, use de 4 a 5 colheres (sopa) de café 3 Corações extraforte. 2. Não deixe a água ferver. Ao primeiro sinal de borbulhas, despeje lentamente a água sobre o pó de café no centro do filtro ou coador, molhando todo o pó. Para preservar o aroma e o sabor, guarde o pacote em um recipiente fechado dentro da geladeira.', 34.99, 25.99, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/sg-11134201-825ah-mqnem3o44uma85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554958%2F58259455754', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
