INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398133509', 'Kit 2 Calcinha Tanga Cós Alto Pós Parto Maternidade Sem Costura Zee Rucci', 'PRODUTO ORIGINAL, ENVIADO COM NOTA FISCAL! A Calcinha Tanga Maternity cintura alta pós-parto sem costura foi produzida para garantir compressão leve na área abdominal, por isso conta com cós mais largo e duplo, proporcionando maior conforto e seguranças para o período pós-parto. Além do período pós-parto, esta calcinha também é super indicada para ser usada com peças de cintura alta. Permite o uso em diversas ocasiões. Peça indispensável para o seu enxoval de gestante. Destaque: *Este produto é confeccionado com a tecnologia seamless (sem costura). Diferente da confecção tradicional, esta tecnologia produz as peças inteiras em teares. A peça sai praticamente pronta, por isso descarta a costura para montar diferentes partes das peças, utilizando estas interferências apenas em pequenos acabamentos, proporcionando máximo conforto, maior durabilidade e menos descartes têxteis na produção. Esta tecnologia evita que a peça marque o corpo durante o uso. Composição: 92% POLIAMIDA 8% ELASTANO', 59.9, 49.9, NULL, 'Women Clothes > Lingerie & Underwear > Panties', 'https://cf.shopee.com.br/file/3996f77607bdcc00df48ac330e476765', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303874852%2F22398133509', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
