INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23896866661', 'Kit Fluido Radiador Motul Motocool Expert 37c C/ 2 Litros', 'KIT Motocool Expert - 2 Litros Aplicação: FLUIDOS DE ARREFECIMENTO-ANTICONGELANTES Relação de produtos: GAMA MOTO Aprovação OEM: ASTM D3306/D4656. BS 6580. AFNOR NFR 15-601. SAE J 1034. JIS K2234. KSM 2142 Embalagens: 1 L CAN, 20 L DRUM, 60 L DRUM Article Number: 103291 DESEMPENHOS ASTM D3306 / D4656, BS 6580, AFNOR NFR 15-601, SAE J 1034, JIS K2234, KSM 2142 Protege o sistema de arrefecimento contra congelamento (-37°C / -35°F) e as peças metálicas contra a corrosão. Proporciona excelente troca térmica para melhoria da eficiência do sistema de arrefecimento. Evita o superaquecimento do motor com seu alto ponto de ebulição de: 135°C / 275°F (a +1.5 bar). Excepcionais propriedades anti-corrosão que permanecem mesmo com o envelhecimento do produto. Não ataca vedações, mangueiras de borracha e peças de plástico. Propriedades anti-espumante. Contém amargante para evitar ingestão: fluidos de arrefecimento e anti-congelantes têm sabor adocicado mas são nocivos à saúde. Fluido de arrefecimento pronto para uso (não diluir) desenvolvido para todos os tipos de motocicletas: road, off road, quads,... Livre de nitratos, aminas e fosfatos.', 120.47, 108.43, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134201-7r98r-llgecuc5r3ukcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1068060049%2F23896866661', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
