INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49802978932', 'Macaco Jacaré Hidráulico 2T Com Maleta de Transporte (LPK-2J) - Lapek', 'O Macaco Hidráulico Tipo Jacaré 2T (LPK-2J) - Lapek, é a solução ideal para elevar veículos e objetos pesados com segurança. Fabricado em aço de alta resistência, este macaco suporta cargas de até 2.000 kg, oferecendo durabilidade, leveza e mobilidade para uso em oficinas, garagens ou em deslocações profissionais. Descrição do Produto: • Capacidade: 2.000 kg • Material: Aço • Peso líquido: 6,2 kg • Altura mínima: 125 mm • Altura máxima: 300 mm • Elevação: 175 mm • Medidas (A x L x C): 450 x 225 x 145 mm • Portátil e compacto para maior mobilidade. Referência: LPK-2J. Cód. de Fábrica: LPK-2J. Marca: Lapek.', 209.9, 209.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Lift', 'https://cf.shopee.com.br/file/sg-11134201-822yt-mi4ydflh0xs282', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F49802978932', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
