INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14392931557', 'Diga Sim | Rick Renner| RHEMA PUBLICAÇÕES', '“Diga Sim!” do autor Rick Renner te fará pensar no que Deus lhe disse para Fazer! Deus falou ao seu Coração? Você ficou questionando e dizendo que deveria ser sua imaginação, porque Deus certamente não escolheria algém como você? Você deixou o diabo convencê-lo a abrir mão da sua missão porque ela parecia grande e gloriosa demais para uma pessoa "comum" como você? Você pode ter certeza de que Deus está falando ao seu coração hoje, chamando-o para fazer algo... Maior que seus talentos naturais... Maior que seus dons naturais... Maior que sua experiência passada. Se você tem hesitado em dar um passo de fé para obedecer ao que o senhor está lhe dizendo para fazer, é hora de simplesmente dizer "SIM". Esse "Sim" vai escancarar a porta para uma vida repleta de aventura como você jamais conheceu. Esqueça o tédio! Sua vida terá um novo brilho. Ela será tão plena e profunda que você jamais irá querer voltar atrás! 16X23CM 276 Páginas', 55.9, 54.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/3ff9618e3a795c4b412788b1217d4cbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F14392931557', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
