INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48609457426', 'Morfador com 5 Moedas do Poder Power Rangers com Luz e Som - Sunny Brinquedos', 'Com o Power Morpher dos Mighty Morphin Power Rangers, cada Ranger desperta o poder do seu Dinozord. Ao encaixar uma das cinco Moedas de Poder, sons e falas exclusivas dão vida à transformação, enquanto luzes iluminam o cinturão e o punho de energia. Com mais de 40 efeitos sonoros, este Morpher une força, velocidade e resistência em uma experiência envolvente, trazendo a emoção do universo Re-Ignition para momentos de imaginação e aventura. Cada Ranger encontra sua energia única, pronta para criar histórias cheias de amizade, coragem e trabalho em equipe. CARACTERÍSTICAS: - Marca: Sunny Brinquedos - Material: Plástico Resistente - Idade recomendada: +4 anos - Com Luz e Som - Mais de 40 efeitos sonoros - Suporte de pegada - Gancho para pendurar na cintura - Alimentação: 3 baterias tipo botão AG13 (LR44) de 1,5 V (Inclusas) - Dimensões da Embalagem (L x C x A): 7cm x 18cm x 23cm - Conteúdo da embalagem: 1 Morfador + 5 Moedas do Poder - INMETRO: 000185/2026', 149.0, 149.0, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/br-11134207-820lj-mnfrd4sp2lttbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406894684%2F48609457426', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250011360', 'Pequeninos | Orações Preciosas | Estrela Guia | Capa Dura Almofadada', 'As orações apresentadas neste livro serão um ótimo guia para os pequeninos que desejam falar com Deus. 12,8x15,5 cm 20 páginas', 24.9, 22.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8259q-mg883ydk7bwub8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F58250011360', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19998100197', 'O Nome | Saiba Por que o Nome de Jesus Provoca Admiração e Animosidade | Franklin Graham', '"Porque é que quando algumas pessoas blasfemam o Seu Nome raramente alguém protesta? Mas, se eu prego sobre Ele com respeito ou oro em Seu Nome, algumas pessoas criticam?" Pergunta Franklin Graham. Neste livro, o autor responde a essas questões e traça a origem, o papel histórico, o avanço por todo o mundo, o impacto nos povos e o futuro reservado à Igreja fundada por aquele a quem o apóstolo Paulo chamou de "o nome que está acima de todo nome". 14x21cm', 32.9, 32.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rena-m83wckpk1o5t53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F19998100197', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23691866595', 'Teologia Pentecostal | N. T. Wright', 'Em Teologia pentecostal em diálogo com N. T. Wright, gentilmente prefaciado por ninguém menos que Amos Yong, vários especialistas pentecostais em Bíblia e teologia se debruçam sobre a obra e a visão teológica de Wright, um dos mais importantes estudiosos de Novo Testamento, e debatem a contribuição desse legado para a teologia pentecostal. A obra se encerra com uma resposta do próprio Wright a cada um dos autores, afirmando suas análises ou corrigindo percepções, fazendo-o sempre de modo caridoso e cortês, o que nos proporciona um diálogo construtivo com seus parceiros pentecostais. Com certeza, uma obra a ser lida por pentecostais e radicionais, não somente para um conhecimento mais aprofundado da teologia de Wright, mas também para nos ajudar a emular o tipo de encontro saudável que devemos buscar em meio à vasta diversidade de perspectivas da igreja. 224 Páginas', 46.9, 42.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7qvdz-ljjsgj0r2lfic4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23691866595', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250271978', 'Vinte Mil Léguas Submarinas | Júlio Verne', 'Nesta aventura, Verne constrói um submarino ultramoderno para a época (1866), o Náutilus. Nele, o capitão Nemo e sua tripulação cortam relações com a humidade e partem para uma aventura marítima, já que para a sobrevivência precisam apenas da eletricidade obtida na imensidade do mar.368 páginas15,9x23 cm', 20.9, 19.1, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821ey-mglp4ejj8fm783', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F58250271978', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15448171729', 'Assuma Sua Missão | Bethany Hicks', 'Mulheres chamadas para formar a geração que transformará o mundo Cada mulher, não importa a cultura, etnia, idade ou estação de vida, é convocada para assumir o chamado da maternidade daqueles que vão transformar o mundo. A comunidade cristã tem sido equipada com livros e treinamentos poderosos que apoiam o chamado dos pais espirituais, mas ainda existe uma peça fundamental que se encontra ausente na família do Reino - o chamado à maternidade, especialmente à mães espirituais continua vago e indefinido. Este livro poderoso vai equipar mulheres a: QUEBRAR mutos atuais conceitos errados sobre maternidade DESCOBRIR os segredos para criar transformadores de mundo AJUDAR a identificar aqueles a quem você é chamada para liberar a voz de uma mãe. DESTRAVAR para desprender e acelerar o seu destino. EXPLORAR o contraste e a sinergia entre pais mães espirituais Agora é a hora para que a voz das mães do Reino se levante e tome o seu lugar na família de Deus. Agora , assuma sua missão', 41.9, 41.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/99af7a3232617c5c893cbef549b34a39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F15448171729', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
