INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194654867', 'VODKA BURLONE TRADICIONAL 950ML', 'Burlone é uma vodka excepcional que se destaca pela sua qualidade incomparável e alto nível de pureza, proporcionando uma suavidade inigualável em cada gole. Produzida no Brasil, esta vodka mantém a tradição do Leste Europeu, utilizando grãos de alta qualidade que garantem um sabor genuíno e autêntico. Com uma graduação alcoólica de 40%, é perfeita para diversas ocasiões, seja em festas ou momentos de descontração. Sua embalagem em garrafa é elegante e prática, ideal para presentear ou servir em eventos. Além disso, é um produto novo, frágil e contém líquido, sem validade definida, o que a torna uma escolha versátil e confiável. Experimente a Vodka Burlone Spirits 950ml e surpreenda-se com sua excelência!', 61.99, 39.59, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-821f6-mgidn690tp1pc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F23194654867', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23292593779', 'Ibramed - Dermosteam LED Vapor de Ozonio + Hf Alta Frequencia', 'DERMOSTEAM LED - VAPOR DE OZÔNIO FUNÇÃO LED - IBRAMED Registro Anvisa: 10360319017 O Novo DERMOSTEAM LED IBRAMED é um equipamento de vapor de ozônio, destinado a auxiliar nos tratamentos de pele e capilares, atuando na emoliência da pele, tratamentos bactericidas e melhora de acnes, além de proporcionar força e brilho em cabelos e barbas. Com propriedades bactericidas o novo Dermosteam Led, permite realizar nutrição, hidratação e limpeza da pele. Além de associar aromaterapia, agora, o novo DERMOSTEAM LED conta com o grande diferencial que é a possibilidade da utilização do Aplicador Probe 450Nm Ibramed - Mini para Dermosteam Led Azul. O vapor liberado pelo Dermosteam IBRAMED, quando em contato com a pele, provoca uma sudorese que facilita a eliminação de toxinas e a hidratação e eminência da capa córnea, facilitando desta maneira a extração de comedões e a penetração de produtos. Este equipamento consta basicamente de um reservatório destinado a realizar a evaporação da água através de uma resistência calefatora responsável pela ebolição e um circuito gerador de ozônio (O3). O ozônio produzido pelo Novo Dermosteam da IBRAMED pode ser liberado juntamente com o vapor de água, sendo assim, o DERMOSTEAM LED permite ao usuário escolher liberação de somente vapor ou vapor ozonizado. DERMOSTEAM LED - Indicações - Tratamento de acne e comedões - Emoliencia e umectação em tratamentos faciais, capilares e podologia - Hidratação facial e corporal - Iluminação facial e limpeza de pele - Ação Bactericida e Fungicida - Tratamento para Rejuvenescimento - Tratamento de Aromaterapia - Antissepsia - Foliculite - Hemostasia - Calo infectado - Dermatite seborreica - Drenagem de abcessos - Fissuras plantares - Onicrocriptose infectada - Polimerização do leito ungueal - Tínea interdigital CARACTERÍSTICAS TÉCNICAS: - Marca: Ibramed - Modelo: D93 e D94 - Voltagem: 110V ou 220V *Não é bivolt, confira a voltagem antes da compra. - Potência de entrada: 550 Va; - Uso em modo contínuo de operação; - Emite vapor com ou sem ozônio; - Capacidade do reservatório de água: aproximadamente 1 litro; - O equipamento não é protegido contra gotejamento de água; - Não é adequado para uso na presença de anestésicos inflamáveis; - Produto: - Dimensões: 30.5 cm x 30.0 cm x 28.5 cm (C x L x A) - Peso: 3.65 kg - Embalagem: - Dimensões: 32.5 cm x 32.0 cm x 30.5 cm (C x L x A) - Peso: 3.85 kg __________________________________ HF - ALTA FREQUÊNCIA IBRAMED: Atenção: Eletrodos enviados com espuma de proteção. Verifique antes de descartar as embalagens. INDICAÇÕES: - Limpeza de pele; - Acne; - Poros abertos; - Depilação; - Tratamentos faciais, capilares e podologia; ELETRODOS: - Esférico Maior: Utilizado em faiscamento direto ou fluxação. Antes de encostar o eletrodo esférico no paciente, colocar o dedo na extremidade e retirá-lo somente depois do contato. - Pente: Utilizado para couro cabeludo. Lavar sempre o cabelo antes da aplicação. Pentear o cabelo em todos os sentidos. Tratamento de alopecias. CARACTERÍSITCAS TÉCNICAS: - Produto: Dimensões: 19.0 cm x 4.0 cm x 4.0 cm (C x L x A); Peso: 0.5 kg - Embalagem: Dimensões: 24.1 cm x 14.1 cm x 13.7 cm (C x L x A); Peso: 1.15 kg ITENS INCLUSOS NO KIT: 01 Dermosteam LED - Vapor de Ozônio função LED - IBRAMED** 01 Cabo de força destacável 01 Manual de operação digital Ibramed 01 Fusível de proteção sobressalente 01 Aparelho HF - Alta Frequência 01 Eletrodo aplicador de vidro tipo esférico maior 01 Eletrodo aplicador de vidro tipo pente 01 Acesso ao Manual de instruções digital 01 Bolsa para transporte Atenção: Eletrodos enviados com espuma de proteção. Verifique antes de descartar as embalagens. *NÃO ACOMPANHA MINI PROBE LED. Adquira separadamente. O uso de cabos, eletrodos e outros acessórios diferentes dos especificados acima, podem resultar em aumento das emissões ou diminuição da imunidade do equipamento.', 2249.0, 2249.0, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lnx672r2oq0908', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F468608244%2F23292593779', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
