INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798512971', 'Toque e Sinta Conhecendo os Dinossauros', 'Tenho certeza que seu bebê vai adorar essa coleção toque e sinta. Com histórias muito divertidas, eles aprendam os sons e conseguem sentir as texturas de cada página, que darão uma ideia de como é a pele de seus animais favoritos na realidade. Idade recomendada: 0 a 3 anos 15 x 20 cm 8 páginas', 14.9, 11.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rfic-m9upjfewa5qn46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22798512971', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10897524414', 'Comunidade Cativante | Mark Dever e Jamie Dunlop', 'COMO É UMA COMUNIDADE QUE REALMENTE TESTIFICA O PODER DE DEUS? O povo de Deus é chamado para vivenciar uma unidade e assumir o compromisso de cuidados mútuos que vão bem além das convenções naturais - sejam elas de natureza étnica, geracional ou econômica. A vida em comunidade só pode ser realidade quando se confia plenamente no poder de Deus no evangelho. Em A Comunidade Cativante, os pastores Mark Dever e Jamie Dunlop propõem uma visão ousada e cativante de uma comunhão autêntica na igreja local. Repleto de ensinamentos bíblicos e conselhos práticos, este livro ajuda pastores e suas congregações a caminharem rumo ao tipo de comunidade que glorifica a Deus, edifica o povo e atrai o perdido. 14X21CM 304 Páginas', 54.9, 54.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/355bea6e95a40f30298808bb7338372c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F10897524414', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
