INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29633867519', 'Grade de Cama para Proteção Infantil Idosos Bebê Articulável 1,5m 1,8m 2m', 'Grade de Cama Proteção Infantil Idosos Bebê Formato em D Vem conhecer essa novidade aqui na Pluggei! Essa grade de cama é a escolha perfeita para garantir a segurança do seu filho durante o sono, ela é colocada embaixo do colchão, garantindo a fixação do produto e proporcionando uma barreira segura contra quedas. A estrutura é dobrável e possui uma montagem fácil, facilitando o transporte e armazenamento. Com essa grade, você nunca mais vai perder uma noite de sono se preocupando com a queda do seu filhote, não perca tempo e garanta já a sua! Características do produto: - Projetado para garantir a segurança de bebês, crianças e até idosos! - Estrutura feita de aço tubular, com pintura epóxi branca: segura, durável e resistente. - Tela revestida 100% em Poliéster. - Adequado para colchões de 10 a 25 cm. - Fácil de limpar, não ocupa espaço, instalação simples. Dimensões do produto: - Comprimento do produto: 200cm, 180cm, 150cm. Depende da variação que o cliente escolher. - Altura apenas da grade: 62cm. - Altura contando com a base embaixo do colchão: 94cm. - Largura apenas da grade: 2cm. - Largura apenas da base: 25cm. - Altura máxima que a base alcança: 35cm. Inclui: - 1 Grade de cama (atende somente um lado). - 1 manual de uso. - 1 kit parafusos para montagem. Imagens ilustrativas. As tonalidades das cores podem variar. Os produtos são medidos manualmente, podendo haver pequenas variações nas medidas. Dependendo do lote, o revestimento de plástico do produto pode vir ou não com pequenas marcações.', 300.0, 212.9, NULL, 'Mom & Baby > Baby Safety > Bumpers, Rails & Guards', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8p33wndpswh9a', 'https://shope.ee/an_redir?origin_link=https%3A%2