INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251630244', 'Conjunto Camiseta Dinos Bermuda Up Baby', 'Conjunto para menino que une conforto e praticidade. A camiseta de algodão apresenta gola arredondada, mangas curtas e estampa colorida divertida. A bermuda, em moletom sem felpa de algodão e poliéster, oferece flexibilidade, com cós elástico, cadarço regulável, bolso funcional e detalhe de etiqueta personalizada. Uma escolha perfeita para os dias quentes.Tecido: Camiseta: Meia Malha (Algodão) | Bermuda: Moletom Sem Felpa (Algodão e Poliéster)Composição: BERMUDA: 50%algodão 50%poliéster,CAMISETA: 100%algodãoModelagem: AmplaComprimento Mangas: CurtaComprimento: CurtoForro: NãoCintura: MédiaDecote/Gola: RedondoFechamento: Cadarço', 199.9, 199.9, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-82301-mi0awp30972d1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337974126%2F58251630244', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
