INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498888440', 'Correia De Acessórios Multi V - Contitech - 5PK1770RNH', 'A correia de acessórios da CONTITECH é uma peça essencial no sistema de transmissão de veículos, responsável por acionar diversos componentes auxiliares, como alternador, bomba d''água, compressor de ar condicionado e direção assistida. Fabricada com materiais de alta qualidade, como borracha reforçada com fibra de vidro ou polímeros avançados, a correia oferece resistência à abrasão, ao calor e ao desgaste, garantindo um funcionamento confiável e duradouro. Com um design preciso e uma construção robusta, a correia de acessórios da CONTITECH proporciona uma transmissão eficiente de energia, contribuindo para o desempenho adequado dos sistemas auxiliares do veículo. Além disso, a CONTITECH oferece uma variedade de correias de acessórios com diferentes tamanhos e configurações para atender às necessidades específicas de cada veículo. Especificações: - Marca; CONTITECH - Garantia; 3 Meses - Comprimento; 1770 mm - Função; ALTERNADOR / AR CONDICIONADO / DIREÇÃO HIDRÁULICA - Largura; 18 mm - Modelo; MULTI V - Quantidade de lamelas (lâminas); 5 Aplicação: Chevrolet Cobalt GRAPHITE 2011 - 2016 Chevrolet Cobalt GRAPHITE 1.8 2011 - 2016 Chevrolet Cobalt LT 2011 - 2016 Chevrolet Cobalt LTZ 2011 - 2016', 97.91, 73.44, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rdyh-mbpqf6bzgnf182', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1452490205%2F23498888440', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
