INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398573807', 'Maquina Aplicador De Tubo Cola Pu Silicone Uso Profissional', 'Pistola Aplicador De Silicone Alta Pressão Principais caraterísticas: - A pistola aplicador de silicone da é a ferramenta ideal para profissionais que buscam eficiência e precisão em seus trabalhos; - Com um design ergonômico e dimensões pensadas para o conforto do usuário, esta pistola possui uma altura total de 18 cm e um comprimento total de 32 cm, facilitando o manuseio e permitindo uma aplicação mais controlada; - A robustez deste produto reforçado garante uma alta qualidade e durabilidade, tornando-o um investimento inteligente para longo prazo; - É perfeita para a aplicação de silicone, PU, veda calha e uma variedade de outros produtos em bisnaga, proporcionando resultados profissionais com uma ferramenta confiável e de alto desempenho; Dicas de Uso: - Mantenha a ferramenta sempre limpa; - Armazene em local limpo e seco;', 26.9, 26.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rauj-maljw7s1tjkhdf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F509931028%2F22398573807', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997501476', 'Cueca Slip Algodão Lisa 074.58', 'A Cueca Slip Algodão Lisa Mash combina conforto, praticidade e qualidade para o uso diário. Confeccionada em algodão, possui tecido respirável, fresco e extremamente macio ao toque, proporcionando bem-estar durante todo o dia. O modelo conta com elástico embutido e discreto, que oferece maior conforto, além de laterais levemente mais largas e um corte moderno, garantindo excelente ajuste ao corpo e total liberdade de movimentos. Sua composição em algodão também contribui para reduzir as chances de alergias na pele, tornando esta cueca uma excelente opção para quem busca conforto e praticidade no dia a dia. Disponível em diversas cores básicas para combinar com todos os estilos. Características do Produto Modelo: Slip Ocasião de uso: Dia a dia Linha: Basic Material: Algodão Tecido: Respirável, macio e confortável Elástico: Embutido e discreto Modelagem: Laterais levemente mais largas para maior conforto Ref.:074.58 Composição Cinza Mescla Claro: 88% Algodão, 12% Poliéster Cinza Mescla Escuro: 50% Algodão, 50% Poliéster Cuidados com a Peça Lavar em temperatura máxima de 40°C. Não utilizar alvejante. Não secar em tambor. Secar em varal, à sombra. Passar a ferro em temperatura máxima de 110°C. Não lavar a seco. Limpeza úmida em processo muito suave. Sobre a Mash Há mais de 50 anos presente no dia a dia do homem brasileiro, a Mash é referência em moda íntima masculina. A marca combina tradição, qualidade e design diferenciado, investindo constantemente em inovação, tecnologia têxtil e desenvolvimento de produtos que proporcionam conforto, durabilidade e estilo para todas as ocasiões. Demais cores: 100% Algodão', 30.69, 30.69, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/sg-11134201-7rd3l-luywmosaf4z7b1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F764761342%2F18997501476', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197041967', 'Filtro Combustível TUCSON 2.7 GL GLS2006 2007 2008 2009 2010 - 3500 - JFCH181', 'Filtro Combustível TUCSON 2.7 GL GLS2006 2007 2008 2009 2010 HYUNDAI - Tucson 2.7 24V - (GLS) - Gasolina - Automático G6BA - 175cv - 2006>2010. O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 148.18, 148.18, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbk7-lltos4xkcoxle8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22197041967', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698365466', 'Porta filtro para Cafeteira Espresso Mondial Dolce Crema 20 Bar C-20-EC Mondial Preto/Inox CPC-NP', 'Com o Porta Cápsula Dolce Crema CPC-NP, a conveniência está ao seu alcance! Basta inserir sua cápsula Nespresso® favorita na Cafeteira Espresso Dolce Crema 20 Bar ou Cafeteira Espresso Dolce Latte C-28-ECL e desfrutar de uma xícara de café perfeitamente extraída, preservando todos os aromas e sabores intensos que tornam o café Nespresso® tão especial. Saiba mais sobre o CPC-NP da Mondial: PORTA FILTRO ADAPTADOR DE CÁPSULAS NESPRESSO® Prepare café e outras bebidas deliciosas na cafeteira espresso com a facilidades das cápsulas! O porta filtro adaptador NESPRESSO®, da Nestlé*, permite que você use cápsulas de café, capuccino, achocolatado e muito mais! *Compatível com cápsula NESPRESSO®. **Marca de titularidade da SOCIETE DES PRODUITS NESTLE S/A., não relacionado à MK BR S.A. COMPATÍVEL COM A CAFETEIRA ESPRESSO C-20-EC e C-28-ECL O adaptador* de cápsulas NESPRESSO® é compatível com os seguintes modelos: Cafeteira Espresso Dolce Crema 20 Bar, C-20-EC, Cafeteira Espresso Dolce Latte C-28-ECL da Mondial. Desfrute de um café premium com a praticidade da cafeteira espresso na sua casa! *Os modelos de porta cápsula são vendidos separadamente online. PREPARE BEBIDAS COMO UM BARISTA! A cafeteira Dolce Crema permite que você prepare bebidas como um barista e explore uma variedade de sabores. Você pode fazer espressos de maneira superprática, com cápsulas, e preparar espuma de leite cremosas para criar diversas bebidas, como cappuccino, mocha, macchiato, frappuccino e muito mais. Crie suas receitas de Lattes favoritas! UM ANO DE GARANTIA MONDIAL A Mondial é a escolha de milhões de consumidores. Mondial, a escolha inteligente!', 119.0, 93.9, NULL, 'Home & Living > Kitchenware > Tea, Coffee & Bartending Equipments', 'https://cf.shopee.com.br/file/sg-11134201-820l5-mnz0be0prls1b4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1062544851%2F23698365466', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
