INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21407987536', 'Kit 6 pares brincos em prata 925 - redondo e coração - 12 unidades - menor preço segundo e terceiro furo - feminino infantil anti alergico', 'Kit com 6 pares de brincos (12 unidades) - 3 pares de brincos redondos + 3 pares de brinco coração O trio de brincos de de zircônia está sempre em alta devido à sua versatilidade para combinar com qualquer roupa e o seu preço sempre acessível! É possível usar separadamente e para quem tem 3 furos, usar um em cada furo!! E o mais incrível desse kit é que são 2 modelos de brincos, redondo e de coração, podendo usar alternadamente, ou da forma que você mais gostar. Cada um saindo por aproximadamente R$17.5, e com frete grátis para você!! Nesse conjunto vão 3 pares de brincos redondos (3/4/5mm) e 3 pares de brincos de coração (3/4/5mm), todos com pedras de zircônia brilhantes e transparentes, feitos totalmente em prata 925 (não são folheados). Todas as nossas peças acompanham um certificado de garantia permanente do teor da prata Garantia: Não cobrimos oxidação, ou quebra do produto. Cobrimos apenas a prata 925. Como evitar o escurecimento da prata: 1. Evite utilizar a joia ao mexer com produtos químicos 2. Ao dormir, tire-a e enrole num papel higiênico 3. Armazene sua joia em um local seco e arejado 4. Não deixe a joia entrar em contato com cosméticos (perfumes, cremes, produtos ou procedimentos químicos do salão de beleza)', 54.9, 42.9, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/3467418859e54a4dc9225b98a7c9e32d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316436073%2F21407987536', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
