INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42755350016', 'Mop Com Centrifuga de Microfibra e Cabo Rotação 360° 13 Litros', 'Esfregão Mop Limpeza Prática Limpar a casa vai se tornar uma tarefa simples com o Esfregão Mop Limpeza Prática. Com ele você economiza no tempo e ganha na praticidade! Fácil de manusear, mantém suas mãos longe dos produtos químicos, água e sujeira. O balde possui sistema para facilitar a remoção do excesso de água e lavagem do esfregão, é eficiente e muito higiênico, proporcionando maior agilidade na hora de desempenhar esta tarefa, além de contar com capacidade para até 13 litros e alça para facilitar seu transporte. O cabo do Mop pode ser articulado em até 180°C e permite alcançar até as superficiais mais difíceis, limpando a sujeira acumulada nos cantos e embaixo dos móveis, evitando que você precise se abaixar para deixar sua casa sempre brilhando. Especificações: Material Polipropileno Cor Predominante Turquesa Capacidade 13 litros Medidas: Baldes - 46cm x 25,5cm x 21cm Esfregão ajuste 1 - Ø16,5cm x 94,5cm Esfregão ajuste 2 - Ø16,5cm x 1,21m Refil - Ø16cm MOR', 120.67, 77.23, NULL, 'Home & Living > Home Care Supplies > Mops', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mb89un1g7kb3dd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800925303%2F42755350016', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
