INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21897198490', 'Livro Literatura infantil O menino e o muro', 'Ele queria desenhar, mas o papel era pequeno para tantas ideias. Então, ele passou a pintar a parede de sua casa, o muro da rua e ganhou o mundo. Katya Manira e Kobra de maneira lúdica e sensível, dão, neste livro, a importância que a arte de rua realmente tem._x000D_ _x000D_ Editora: Ciranda na Escola_x000D_ Edição: 1, 2023_x000D_ Autor: Katya Manira_x000D_ Ilustrador: Eduardo Kobra_x000D_ Idioma: Português_x000D_ Páginas: 32_x000D_ Dimensões: L 24.00 x A 24.00 x E 0.36_x000D_ ISBN: 9786526102428_x000D_ Coleção: Não se aplica_x000D_ Linha Editorial: Ciranda na escola - Literatura infantojuvenil_x000D_ Faixa Etária: + 6 anos_x000D_ Assuntos (tags): Artes, Arte de rua, Grafite, Diversão, Aprendizado, Eduardo Kobra, Kobra, História, Emoções, Imaginação_x000D_ BISAC: Literatura Infantil / Artes Cênicas_x000D_ Linha de Produto: Literatura infantil_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação fosca_x000D_ Material: Papel', 49.9, 49.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7qvdh-ljo5cf5ctxqqcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F21897198490', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
