INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26280446755', 'Livro Capa dura Pierre - O detetive dos labirintos - O mistério da', 'O Senhor X está de volta com um plano terrível: Ele quer roubar o Cubo Mágico da Torre Imperial Labirinto e deixar Labirintópolis na escuridão. Pierre, o detetive dos labirintos, e sua amiga Carmem são chamados, junto a outros excelentes detetives, para proteger esse tesouro. Percorra os labirintos, encontre os itens escondidos, resolva os desafios e ajude a deter o Senhor X. _x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2025_x000D_ Autor: Chihiro Maruyama_x000D_ Idioma: Português_x000D_ Páginas: 36_x000D_ Dimensões: L 26.80 x A 35.40 x E 1.20_x000D_ ISBN: 9786526116050_x000D_ Coleção: Pierre_x000D_ Linha Editorial: Ciranda Cultural - Coedição_x000D_ Faixa Etária: + 9 anos_x000D_ Assuntos (tags): Labirinto, Passatempos, Aventura_x000D_ BISAC: Não Ficção Juvenil / Jogos e Atividades_x000D_ Linha de Produto: Capa dura_x000D_ Encadernação: Capa dura_x000D_ Acabamento: Laminação fosca e verniz localizado_x000D_ Material: Papel', 69.9, 48.93, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd4w-m7mmdpzcy2bx1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F26280446755', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9070335397', 'Livro - O Picapau Amarelo - Capa comum - Ciranda Cultural', 'A alegria e as boas maneiras estão sempre presentes no dia a dia da turma do parque. Aprenda com eles sobre lindas atitudes e torne a convivência com sua família e seus amigos ainda mais especial! Editora: Ciranda Cultural Edição: 1, 2019 Autor: Ciranda Cultural Idioma: Português Páginas: 10 Dimensões: L 12.50 x A 15.50 x E 1.60 ISBN: 9788538087328', 24.9, 24.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/9ee9ff4ebac4c3c3def4f92681a96476', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F9070335397', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
