INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899857517', 'Rádio 1030BT DSP 4x60W Com Suporte E App Multicolor', 'O Rádio 1030BT DSP é a solução perfeita para quem busca som automotivo de qualidade e conectividade. Com potência de 4x60W RMS e 6 saídas pré-amplificadas, entrega áudio de alto desempenho. Conta com saída para subwoofer com controle de ganho, LCD de 2 linhas com iluminação multicolor, suporte para celular e carregamento por indução. A função DSP garante ajustes precisos de som, enquanto o aplicativo dedicado oferece controle completo direto pelo smartphone. Detalhes do produto: Potência: 4x60W RMS DSP com equalização avançada 6 saídas RCA pré-amplificadas Saída para subwoofer com controle de ganho Tela LCD com 2 linhas e luz multicolor Suporte para celular integrado Carregamento por indução Controle via aplicativo Modo de uso: Instale o aparelho no painel 1-DIN do veículo, conecte as saídas de áudio conforme necessidade e utilize o suporte para posicionar o celular. Para carregar por indução, basta apoiar o aparelho compatível no local indicado. Resumo final: Tecnologia, potência e praticidade reunidas em um rádio completo para som automotivo profissional.', 299.9, 209.93, NULL, 'Audio > Media Players > Radio & Cassette Players', 'https://cf.shopee.com.br/file/sg-11134201-824hm-mfmtmjltkky7fa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1572467546%2F18899857517', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793343385', 'Sandália Chinelo Kenner Rakka Especial Original Lançamento', '🩴 Sandália Chinelo Kenner Rakka Especial Masculino ✨ O Chinelo Kenner Rakka Especial combina design moderno, conforto absoluto e durabilidade para o dia a dia. Produzido com materiais de alta qualidade, oferece uma experiência única a cada passo, garantindo firmeza e estilo em qualquer ocasião. ✔️ Diferenciais que fazem a diferença: Conforto anatômico: palmilha macia que se adapta ao formato dos pés. Resistência garantida: materiais de alta performance para maior durabilidade. Segurança ao caminhar: solado emborrachado com excelente aderência. Versatilidade: ideal para passeio, lazer ou uso diário. Temos também esse modelo disponível em outras cores, acesse o link para conferir: https://shopee.com.br/product/324536294/23593543280/ 🧾 Ficha Técnica Cabedal: Sintético de alta performance Forro Interno: Macio e resistente Solado: Borracha antiderrapante Palmilha: Anatômica e confortável Fechamento: Sem fecho (chinelo) Indicado para: Passeio, lazer, uso diário 🧽 Dicas de Limpeza ✨ Limpe com pano úmido e sabão neutro ✨ Evite deixar de molho ou usar solventes ✨ Para sujeira persistente, utilize escova de cerdas macias ✨ Seque sempre à sombra 🌤️ 📏 Tamanhos Disponíveis 37 – 24,3 cm 38 – 25,0 cm 39 – 25,8 cm 40 – 26,5 cm 41 – 27,3 cm 42 – 28,0 cm 43 – 28,8 cm 44 – 29,5 cm', 309.9, 229.9, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0lx9e3l12tdaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F324536294%2F23793343385', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
