INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251869396', 'Sandália Babuche Infantil Grendene Kids Guerreiras do K-POP Huntrix', 'A Babuche Infantil Guerreiras do K-POP Huntrix Grendene Kids combina conforto e muito estilo em um modelo leve e cheio de brilho. Com material metalizado e efeitos degradê na cartela de cores, o visual remete ao universo das Guerreiras Mira, Zoey e Rumi, que aparecem em versões estilizadas e facilmente identificáveis pelas fãs. A babuche é prática para o dia a dia, fácil de calçar e perfeita para acompanhar as crianças em todas as aventuras, trazendo a energia do K-POP para cada passo.', 89.99, 89.99, NULL, 'Baby & Kids Fashion > Girl Shoes > Sandals', 'https://cf.shopee.com.br/file/sg-11134201-822zn-mi69ci6omfig09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1012616199%2F58251869396', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
