INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13667827857', 'kit Pó Descolorante Ametista Ultra Blonde 300g Probelle + Agua oxigenada cremosa 30 vol 900ML Probelle probelle', 'Pó Descolorante 300g Probelle Pó descolorante profissional de alta performance para descolorir, produzir mechas e balayagens. Formulado especialmente para ser usado em todos os processos de descoloração, mechas, reflexos, ballayages e clareamento, com altíssima performance, efeito de longa duração e efeito anti-amarelo. Desenvolvido com matérias primas de altíssima tecnologia, possui incrível textura que minimiza os efeitos do ressecamento, protegendo dos danos, com método simples e rápido. Proporciona até 10 níveis de clareamento PH 4,5 Modo de Usar: A Massa descolorante deve ser aplicada no cabelo não lavado. O tempo de exposição dependerá das condições de saúde da fibra e do resultado desejado. Verifique o nível de clareamento a cada 5 minutos. Não deve ultrapassar 30 minutos. Caso ocorra alguma irritação como coceira, ardência ou vermelhidão, interrompa o uso imediatamente e enxágue com água morna. Se necessário procure orientação Médica. + Agua oxigenada cremosa 30 vol 900ML Probelle Para que serve? A Água OX 30 Vol Probelle 900ml é uma emulsão reveladora estabilizada de alta performance , compatível com todos os descolorantes e coloração. A Água OX 30 Vol Probelle 900ml é uma emulsão reveladora estabilizada de alta performance , compatível com todos os descolorantes e coloração , promove clareamento uniforme sem manchas , possui textura cremosa de fácil aplicação, elimina o efeito oxidado dos cabelos loiros. Ação platinadora de mechas. Uniformiza os loiros. Formulado especialmente para ser usado na preparação de coloração capilar e descolorantes, conforme instrução definido pelo fabricante', 43.9, 39.9, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-824jg-mps20mt7ynt87f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648982173%2F13667827857', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26211139568', 'Haylou Mori Pro Fone Bluetooth Sem Fio | ANC 43dB + 6 Microfones HD Call | IPX4 Fone De Ouvido', '-43dB AI ANC │Cancelamento de ruído de 6 microfones Cancelamento de ruído de chamada AI│Ruído antivento Classificação à prova d''água IPX4│Três modos de cancelamento de ruído│Bluetooth 5.4 mais recente.│Duração da bateria de 35 horas. 【Cancelamento ativo híbrido adaptativo do ruído】- O fone de ouvido HAYLOU Mori Pro vem equipado com cancelamento de ruído ativo adaptativo (ANC) que se adapta inteligentemente ao ambiente, garantindo que o ruído ambiente seja efetivamente eliminado. O design também incorpora 6 microfones e resistência ao ruído do vento, tornando-os ideais para atividades ao ar livre e aventuras em movimento. 【Cancelamento do ruído 6-mic】- Os auriculares possuem seis microfones (três por auricular) para eliminar o ruído circundante durante as chamadas, possibilitando uma comunicação clara em todos os cenários. 【-43dB ANC Profundidade do cancelamento do ruído】- Com uma profundidade de redução de ruído de até 43dB *, o Mori Pro pode efetivamente reduzir o ruído em uma cantina lotada, uma cabine de avião ou no metrô. 【3 modos cancelamento ruído ANC】- Existem 3 modos de cancelamento de ruído para diferentes ambientes e três níveis ajustáveis para cada modo para sua escolha. 【Bateria Bluetooth 5.4 e 35 Horas】- A mais recente tecnologia Bluetooth 5.4 garante transmissão rápida e conexão estável para manter sua música indo. O driver embutido de 12mm cria um campo sonoro aberto e oferece excelente análise. Mori Pro tem uma bateria de 35 horas para aliviar a ansiedade de energia.', 229.0, 229.0, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/cn-11134207-820l4-mnb88ka2l6vaf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F250735991%2F26211139568', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
