INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41280147226', 'Boneco Articulado Montável Blokees Jurassic World Terraventure Wave 02 Colecionável Model Kit', 'JURASSIC WORLD TERRAVENTURE SURPRISE WAVE 02 | MODEL KIT DETALHES - Produto Oficialmente Licenciado - Formato Caixa Surpresa - Montagem Sem Ferramentas - Coleção Jurassic World Terraventure Explore o mundo dos dinossauros com Jurassic World Terraventure Surprise Wave 02. Esta coleção de model kits surpresa traz personagens icônicos da franquia Jurassic World em formato de caixa cega, oferecendo uma experiência de colecionismo emocionante. Cada caixa contém um model kit surpresa para montar, permitindo que você construa sua própria coleção de dinossauros. A montagem não requer ferramentas, tornando a experiência acessível e divertida para colecionadores. CONTEÚDO DA EMBALAGEM - Model Kit x 1 - Manual de Instruções x 1 ESPECIFICAÇÕES - Tipo: Brinquedos de personagens para montar - Série: Jurassic World Terraventure Surprise Wave 02 - Material: Plástico ABS ecologicamente correto - Formato: Caixa surpresa Distribuído por Polibrinq As imagens são meramente ilustrativas. As cores, dimensões e detalhes do produto podem variar, devendo prevalecer a descrição e as especificações técnicas disponibilizadas ao consumidor.', 42.98, 34.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-81zvm-mn5v34ehllag50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1537682554%2F41280147226', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
