INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10254935525', 'Película Nano Traseira para iPhone 11 Pro Max - Gshield', 'DESCRIÇÃO Proteja a traseira do seu smartphone com a película Nano Traseira da Gshield! A Película Nano Traseira, protege seu aparelho contra riscos e arranhões na parte de trás. Ideal para os adeptos ao uso do aparelho sem uso de capa, mas para uma maior proteção, as películas traseiras também podem ser usadas em conjunto com as capas da Gshield, evitando o acúmulo de detritos no interior do acessório e eventuais arranhões no celular. ESPECIFICAÇÕES Material: Hidro nano pet Marca: Gshield - ( Gorila Shield ) Espessura: 0,10mm Proteção: Contra pequenos impactos e riscos à traseira Grau de transparência: 98% High Definition Certificações: US Military Dimensões: Cobre as dimensões da traseira do aparelho, podendo haver pequenos recuos para melhor aderência', 14.27, 14.27, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/0137bbd9980988cb04ac03f3cc8b08b0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F10254935525', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22608638959', 'Película para Asus Zenfone 5Z - Hydrogel HD - Gshield', 'DESCRIÇÃOAumente a resistência com a película para o seu Asus Zenfone 5Z A Película de Hydrogel para Asus Zenfone 5Z, da Gshield, garante proteção extra para a tela do seu dispositivo. Produzida com a tecnologia hidro nano pet + material semelhante ao silicone, são ultra resistentes contra riscos e com revestimento oleofóbico, atenuando as marcas de digitais na tela do aparelho; a película se adapta às extremidades curvadas, cobrindo todo o visor. ESPECIFICAÇÕESMaterial: Hidro nano pet + TPU Soft Gel Marca: Gshield - ( Gorila Shiel d )Espessura: 0,19mm Proteção: Contra pequenos impactos e riscos à tela Grau de transparência: 97% High DefinitionCertificações: US MilitaryDimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais.', 54.97, 54.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-22120-nomnklpfckkv1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F22608638959', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43960186133', 'Escorredor de Louças E Pratos Plástico (61537/200) - Tramontina', 'O Escorredor de Louça Plástico (61537/200) - Tramontina, foi desenvolvido com grande capacidade de armazenamento, tornando-o ideal para auxiliar nas tarefas do seu dia a dia na cozinha. Produzido em plástico de alta resistência, este escorredor garante durabilidade e segurança para os seus itens de cozinha. Seu design é compacto e elegante, o que proporciona economia de espaço e o torna o complemento perfeito para a bancada da sua pia. Com estética criativa, ele drena a água com facilidade, através de seu espaço oco, perfeito para guardar tigelas, copos e até mesmo panelas pequenas. Descrição do Produto: • Alças laterais anatômicas. • Abertura para escoamento de água. • Robusto: feito em polipropileno. • Com porta talheres. • Capacidade para 9 pratos. Referência: 61537/200. Cód. de Fábrica: 61537/200. Marca: Tramontina.', 71.9, 67.59, NULL, 'Home & Living > Kitchenware > Kitchen Racks', 'https://cf.shopee.com.br/file/sg-11134201-7rdve-mcl2v25ilyur05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F43960186133', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
