INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23992653995', 'Violao Strinberg Forest Fs-3 C Tbs Classico Capa Acessorios', 'Violao Strinberg Forest FS-3 C TBS EL-AC Classico Descricao Violao Classico Nylon com visual diferenciado e boa sonoridade. Equipado com o pre-amplificador SE-50, com controles de frequencia e afinador. ACOMPANHA: -01 CAPA REFORCADA EM NYLON 600 -01 CABO DE 5 METROS -01 CORREIA -01 CAPOTRASTE -03 PALETAS Especificacoes: - Modelo: FS3C - Tipo: Violao Eletroacustico - Cor: Tobacco Sunburst (TBS) - Acabamento: Fosco - Formato do Corpo: Classico sem Cutaway - Encordoamento: Nylon - Tensao Normal - Numero de Cordas: 6 - Madeira de Braco: Nato - Madeira de Tampo: Sapele Laminado - Madeira da Lateral: Sapele Laminado - Madeira de Fundo: Sapele Laminado - Cavalete: Rosewood - Escala: Technical Wood - Tensor: Sim. Bilateral - Nut (Capo Traste): 51mm - Numero de Trastes: 19 - Marcacoes: N/A - Tarraxas: Douradas, Borboletas Madreperola - Escudo: N/A - Empunhadura / Mao: Destro - Pre: SE-50 - Captacao: Piezo - Alimentacao: Bateria 9V - Jack: P10 e XLR (Balanceada). - Controles do Pre - Volume, Grave, Medio, Agudo - Presence - Notch Filter - Phase - Afinador e check bateria.', 994.0, 994.0, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/sg-11134201-7rbly-lodz72d14ggwa2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F23992653995', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
