INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997669142', 'Pack com 6 - Sorox Limão 550mL', 'O peso líquido do conteúdo é de 550ml. O Hidrotônico Sorox sabor Limão é a bebida perfeita para manter o seu corpo hidratado após atividades físicas e exposição ao calor. Sorox possui os sais e minerais que o seu corpo necessita. Sorox contém 8 íons que ajudam a recuperar os minerais perdidos, seja por estar exposto a altas temperaturas ou por atividades físicas. [Sódio, Potássio, Cálcio, Citrato, Zinco, Cloreto, Lactato e Magnésio] Uma Super combinação do que o seu corpo precisa. Sorox é uma forma excepcional de recuperar liquidos e eletrólitos. Sorox proporciona uma hidratação sem açucar e deixa uma sensação fantástica em seu paladar, com diferentes sabores, revigora o corpo após uma atividade física, pois contém alto valor nutricional. Modo de Uso: Recomenda-se o consumo de 1 garrafa de Sorox (550 mL) diariamente.', 97.08, 69.99, NULL, 'Food & Beverages > Beverages > Energy & Isotonic Drinks', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj0070fpjklf91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1284050214%2F22997669142', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
