INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51659125539', 'Lovito Conjunto Shorts Listrados Casuais Feminino BRSHB815BRL845', '✅DESTAQUES -❤️Macio e Confortável ✅DESCRIÇÕES Estampa: Listrada Estilo: Casual Tamanho Plus: Não Composição: 100% Poliéster Tipo de Caimento: Regular Transparência: Não Elasticidade: Levemente Elástica Região de Origem: Brasil ✅O PACOTE INCLUI 1 Conjunto ✅INTRODUÇÃO À LOVITO A Lovito é uma marca emergente que acredita no poder feminino, comprometida em oferecer opções de roupas elegantes e acessíveis para diferentes estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, libertadora e fazer você se sentir bem. Afinal, o melhor acessório para qualquer look é a autoconfiança. ✅NOTAS DE COMPRA Compare suas medidas com nossa tabela disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, converse conosco e responderemos o mais rápido possível.😊', 99.9, 74.9, NULL, 'Women Clothes > Sets > Individual Sets', 'https://cf.shopee.com.br/file/br-11134207-820lr-mnzr4c4i3chw9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1632995122%2F51659125539', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
