INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23292195663', 'Cera Pasta Tradicional Com Carnaúba 200G Proauto', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação: Indicado para todos os tipos de pintura. Conteúdo de Embalagem: 1 Cera em Pasta 200G Código do Fabricante: 204 Código de Barras: 7896189221021 Especificações: Remove manchas, pequenos riscos e tinta oxidada Protege contra as ações do tempo (sol, chuva, maresia, e etc.) Modo de Usar: Lavar o veículo e secá-lo. Transferir uma quantidade suficiente da cera para outro recipiente e nunca retornar o produto usado para a embalagem original. Aplicar em pequenas áreas de cada vez com movimentos circulares, usando um pano ou algodão levemente umedecidos. Deixe secar por alguns minutos. Dê o brilho com outro pano seco e limpo. Recomenda-se usar a sombra Garantia 12 Meses', 19.41, 19.41, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Wax', 'https://cf.shopee.com.br/file/sg-11134201-8225l-mhthud9vk9hf27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F23292195663', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20798028285', 'Palheta Parabrisa Ford Fiesta 2005 2006 2007 2008 2009 2010 Bosch', 'Descrição JOGO DE PALHETA DIANTEIRA AEROFIT ORIGINAL BOSCH 01 - Palheta Bosch lado motorista 22" / 55M 01 - Palheta Bosch lado passageiro 18" / 45CM APLICAÇÃO: - FORD FIESTA 2005 - FORD FIESTA 2006 - FORD FIESTA 2007 - FORD FIESTA 2008 - FORD FIESTA 2009 - FORD FIESTA 2010 ENCAIXE : GANCHO Garanta máxima eficiência e segurança em todas as condições de estrada com as palhetas Bosch Aerofit. Produto original Bosch com nota fiscal inclusa. Características: Encaixe Gancho para instalação fácil e segura. Maior durabilidade e eficiência comprovadas. Nova embalagem moderna. Tratamento de grafite para limpeza suave. Estrutura robusta para estabilidade em todas as situações. Recursos Destacados: Tecnologia de ponta e inovação para uso com conexões especiais. Borracha aprimorada com Power Protection Plus, garantindo uma limpeza suave e silenciosa. Lâmina de aço Evodium pré-tensionada, oferecendo uma adaptação perfeita ao para-brisa. Produto novo, com aplicação compatível com peças originais. Construção robusta projetada para um desempenho duradouro, independentemente das condições climáticas. Processo de instalação simples e rápido para sua conveniência. Substituição Recomendada: Observe sinais de problemas no para-brisa e nas palhetas. Dicas de manutenção incluídas para prolongar a vida útil das palhetas. Importante: Substitua as palhetas pelo menos uma vez por ano. Em caso de dúvidas sobre a compatibilidade do seu veículo, pergunte no campo de perguntas do anúncio. Garanta uma visão clara e eficiente em qualquer condição com as Palhetas Bosch Aerofit. Compre já!', 76.77, 76.77, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rcep-m67949yv8pmo61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F372102753%2F20798028285', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19699605514', 'Palheta Limpador Parabrisa Original Bosch Renault Kwid 2017 A 2023', 'Palheta Limpador Parabrisa Original Bosch Renault Kwid 2017 A 2023 A alta performance ficou ainda melhor. Palhetas que garantem mais Eficiência, Segurança, Durabilidade e Qualidade. Se é BOSCH, pode confiar. Enxergue o que vem pela frente. Composto por: - 1 Palheta dianteira BOSCH Aerofit Original Medida: - Palheta motorista: 23" (57,5 cm) Compatível com: - Renault Kwid 2017 A 2023 Características: - Palheta BOSCH Aerofit Original - Instalação mais fácil e segura. - Maior durabilidade e eficiência comprovadas. - Sem partes metálicas expostas. Livre de desgastes de pintura e corrosão. - Spoiler aerodinâmico para ter uma distribuição uniforme de força, mantendo a varredura eficiente mesmo em altas velocidades. - Maior estabilidade em todas as situações de uso. - Funcionamento ultra suave, devido ao seu tratamento de grafite, para um movimento sem ruídos ou trepidações. - Nova embalagem moderna e atrativa. Perguntas Frequentes: Quando devo trocar as Palhetas do meu carro? - A troca deve ser realizada aos primeiros sinais de desgaste nas Palhetas. Isso porque o componente com desgaste tem a eficiência comprometida e atrapalha a visibilidade. Quais os sinais de desgaste da palheta? - Os sinais de uma Palheta com desgaste são: a Palheta não retira todo o excesso de água, faz barulho durante o funcionamento, risca o parabrisa do carro, lâmina de borracha torta, quebrada ou ressecada. Qual o prazo para a substituição das Palhetas? - Substitua as Palhetas pelo menos uma vez por ano. As Palhetas são originais? - Sim. Somos fornecedores autorizados BOSCH. Todos os produtos são originais e acompanham Nota Fiscal. Observação: - Em caso dúvidas sobre o modelo correto da Palheta para o seu carro, faça uma pergunta na parte inferior do anúncio. Temos uma equipe especializada para tirar as suas dúvidas. - O limpador de parabrisa é um acessório obrigatório por lei (artigo 230, XIX, do CTB). O não funcionamento perfeito ou mau uso do mesmo, é caracterizado como infração grave, com direito a multa e retenção do veículo. Mantenha a sua família segura. Compre Palhetas Originais BOSCH Aerofit.', 48.97, 48.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rcd2-m6mzr2q51uzla8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F372102753%2F19699605514', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
