INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21199200201', 'Base Dupla Aquecedor De Cera Quente Rollon Termocera', 'Base Dupla Aquecedor De Cera Quente Rollon TermoceraSeja um profissional de beleza ainda mais eficiente com a base dupla para aquecedor de cera roll-on da Mega Bell. Este aparelho foi desenvolvido para simplificar o processo de depilação com sistema roll-on, proporcionando mais praticidade e mobilidade durante o procedimento. Atributos do ProdutoMarca: Mega Bell Modelo: Base Dupla Aquecedor RollOn Mega Bell Pr Quantidade de Itens: 1 Kit: Não Características DestacadasA base dupla deste aquecedor de cera quente roll-on permite que você tenha sempre um aparelho aquecido e pronto para uso, agilizando o processo de depilação. Compatível com a maioria dos aparelhos roll-on do mercado, essa base de apoio bivolt garante versatilidade e praticidade em seu dia a dia. Especificações TécnicasVoltagem: Bivolt automático (127V/240V), 50 watts, 50-60 HZ Largura: 23,3cm Altura: 9cm Peso Aproximado: 800g A Mega Bell garante a qualidade e a eficiência deste aquecedor de cera, tornando o processo de depilação mais simples e rápido. Com a base dupla, você terá mais agilidade e praticidade em seu trabalho, proporcionando um serviço de excelência para seus clientes. &nbsp;', 227.21, 227.21, NULL, 'Beauty > Beauty Tools > Hair Removal Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rcew-ls7a9vqs6eaf6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1186779187%2F21199200201', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
