INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258267950', 'Kit de Rodas para Móveis – Suporte Antiderrapante, até 200kg, Fácil Instalação Multiuso', 'Kit de Rodas para Móveis OI-3002 - Suporte Ajustável até 200kg - Base Antiderrapante Facilite a movimentação de eletrodomésticos e móveis pesados com o Kit de Rodas para Móveis OI-3002! Ideal para quem busca praticidade e eficiência no dia a dia, esse suporte resistente suporta até 200kg, permitindo que você mova facilmente itens como geladeiras, fogões e máquinas de lavar sem esforço. Principais Características: Capacidade de carga: Suporta até 200kg, perfeito para móveis e eletrodomésticos pesados. Fácil instalação: Instale sem ferramentas complicadas, ideal para quem busca praticidade. Ajuste de largura independente: Ajuste a base conforme a necessidade do seu móvel ou eletrodoméstico. Base antiderrapante: Oferece estabilidade e segurança, evitando deslizamentos e protegendo contra danos. Facilidade na movimentação e limpeza: Torne a limpeza e a reorganização dos ambientes mais simples e rápidas. Benefícios: Evita danos como ferrugem e riscos, protegendo seus móveis e eletrodomésticos. Ajuste fácil para diferentes tamanhos de móveis e aparelhos. Ideal para facilitar a limpeza, movimentação e reorganização de ambientes como cozinhas, lavanderias e mais. Conteúdo da embalagem: 1 Par de Suportes Ajustáveis 1 Kit de Parafusos para Ajuste de Tamanho Melhore o conforto e a praticidade no seu lar com o Kit de Rodas para Móveis OI-3002. Ideal para quem deseja facilidade de movimentação e proteção para seus móveis e eletrodomésticos! Aproveite!', 54.99, 33.99, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zvt-mmq1nl6h0kcoa2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1333507062%2F58258267950', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597569176', 'Lápis novos para todos os povos', 'Quando ganha um caderno de desenho e uma caixa de lápis de cor, Raul nem imagina que também está ganhando do pai a oportunidade de mudar e transformar o mundo. O garoto desenha muitos povos nas páginas de seu valioso caderno, e os traços foram coloridos com tanta esperança e capricho que as pessoas de todos os povos parecem ter criado vida e passam a se tratar com mais respeito. Será que, depois de muito pensar, Raul descobriu o verdadeiro lápis cor de pele? Sera´ que esse esforçado desenhista é, de certa forma, responsável pela nova onda de respeito que está no ar e nas cores de todos os povos?', 57.37, 57.37, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rd3s-lvzd0069n6mgeb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23597569176', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
