INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398570881', 'Pneu Delinte Aro 20 225/40R20 Desert Storm 2 DS8 92W', 'O pneu DS8 Desert Storm oferece melhor controle e desempenho em pistas secas ou molhadas, permitindo que ele alcance altas velocidades e uma força de tração acima do comum. É o pneu ideal para quem quer unir a linha esportiva com a linha UHP (Ultra High Performance) Desenho único e agressivo, com sulcos longitudinais para escoamento eficiente, reduzindo as chances de aquaplanagem; Otimização do sulco para ampliar a força de tração. Presença de ombros estabilizadores melhoram o desempenho, aumentando a dirigibilidade em pistas molhadas; Estruturação especial dos blocos internos, projetados para oferecer a máxima aderência possível dos pneus com o solo. (KIT COM 4 UNIDADES)', 1452.48, 1452.48, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-8261l-mkwo3yevt2bk29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290433581%2F22398570881', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
