INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597758136', 'Cueca Boxer Zorba Com Abertura Em Algodão 848', 'PRODUTO ORIGINAL, ENVIADO COM NOTA FISCAL DESCRIÇÃO: Cueca Boxer Zorba com abertura, em algodão com elastano, possui elástico aparente personalizado. Bojo com abertura. Excelente ajuste ao corpo. Possui a tecnologia Go Tagless, sem etiquetas costuradas, que evita que a pele fique arranhada ou irritada. Possui elástico aparente personalizado. COMPOSIÇÃO: 95% Algodão e 5% Elastano. PAÍS DE ORIGEM: Brasil. INSTRUÇÕES DE LAVAGEM: Temperatura máxima de lavagem 30ºC; processo suave; não alvejar; não secar em tambor; secagem em varal por gotejamento a sombra; temperatura máxima da base do ferro a 110ºC sem vapor; não limpar a seco. INDICAÇÃO: Dia a dia. CONTÉM: 01 unidade. TABELA DE MEDIDAS: P – 38 ao 40 - Cintura entre 76 e 80 cm M – 42 ao 44 - Cintura entre 84 e 88 cm G – 46 ao 48 - Cintura entre 92 e 96 cm GG – 50 ao 52 - Cintura entre 100 e 104 cm Caso sua medida esteja no intervalo das medidas entre um tamanho e outro, considerar o tamanho maior.', 49.9, 37.9, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/sg-11134201-7rdwm-lzqj25u4wxza47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303874852%2F22597758136', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
