INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16292030564', 'Mini Controle Teclado Air Mouse Wireless 2.4 Ghz -pc,game', 'Controle remoto sem fio com teclado, com controle de volume, botão de atalho para acessar menu, setas direcionais e botão "ok" para selecionar as funções. Air Mouse é um controle remoto sem fio com teclado QWERTY que facilita a navegação em sites, navegue entre os menus com o mouse e utilize o teclado para fazer pesquisas mais rápido, esse produto é compatível com quase todos os sistemas atuais, navegue com facilidade sem precisar levantar do sofá. ATENÇÃO: Alguns modelos de Televisão não estão mais sendo compatíveis com o produto. Podendo funcionar parcialmente. Caso essa seja a sua situação, pedimos desculpas pelo transtorno. Se desejar, você pode abrir uma solicitação. Permanecemos à disposição para atendê-la(o). CARACTERÍSTICAS: Comunicação: 2.4 Ghz sem Fio Modelo de escrita: QWERTY Frequência: 2.00-2.483 Ghz Distância: 10m Compatível Com: Windows, Mac, MAC OS, Linux e Android. Dispositivos: PC, Notebook, Video Game, Tablet, Notebook, etc. Bateria de li-ion recarregável (Interna não removível). Sistema Plug and Play (Não precisa instalar, basta conectar e usar). Air Mouse com Tecnologia Anti-Vibração Teclado Com Bateria de Íons de Li-ion Recarregável 7 Cores em LED Opcionais (Fn+ Espaço) Cor: Preto. CONTEÚDO: 1x controle Air mouse 1x cabo de carregamento 1x receptor sem fio', 60.0, 35.97, NULL, 'Computers & Accessories > Keyboards & Mice > Keyboards', 'https://cf.shopee.com.br/file/sg-11134201-822wo-mia540xe2xhc0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F16292030564', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
