INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794678065', 'Máquina Secadora de Unhas 268W LED/UV Temporizador Base Removível Display Digital Cabine', 'O Secador de Unhas LED/UV ON-2103 oferece uma secagem rápida, segura e eficiente para esmaltes em gel, gel magnético e gel com glitter. Com luz azul de dupla fonte (365nm + 405nm), ele garante um endurecimento uniforme e duradouro das unhas, preservando o brilho e a resistência. Conta com base removível, sensor inteligente de acendimento instantâneo e temporizador múltiplo para maior praticidade no uso. Seu design moderno e compacto é ideal para uso profissional ou doméstico em manicures. ESPECIFICAÇÕES: - Tipo: Secador de Unhas LED/UV - Potência: 268W - Alimentação: 127V - 220V AC - Frequência: 60Hz - Dimensões: - Largura: 227 mm - Comprimento: 110 mm - Altura: 204 mm - Peso bruto: 520g - Luz: Dupla fonte (365nm + 405nm) - LEDs: 57 unidades com sensor inteligente - Vida útil: 50.000 horas - Funções: Temporizador múltiplo, base removível, acendimento automático - Aplicação: Gel magnético, gel para unhas, gel com glitter CONTEÚDO: - 01 Secador de Unhas LED/UV ON-2103', 104.9, 85.0, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-821d3-mgwif1uvg45n6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F22794678065', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
