INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47354994402', 'Verniz De Motor Filme De Proteção Para Motores Vonixx 1,5l', 'VERNIZ DE MOTOR VONIXX 1,5 LITROS VERNIZ DE MOTOR, protege, dá brilho e renova todas as superfícies existentes no cofre do motor, como partes metálicas, plásticas, superfícies pintadas e mangueiras de borracha. O produto forma um filme levemente lubrificado que penetra em locais difíceis e adere em todas as superfícies citadas. Verniz de motor é resistente a altas temperaturas e tem durabilidade de até seis meses. Também pode ser utilizado em chassi e caixas de rodas, proporcionado os mesmos benefícios de sua aplicação no motor. DILUIÇÃO Pronto uso. DURABILIDADE Até seis meses de proteção no motor. INFORMAÇÕES ADICIONAIS Verniz de Motor pode ser utilizado em chassis e caixas de rodas, proporcionando os mesmos benefícios de sua aplicação no motor. - DÁ BRILHO AO MOTOR - PROTEGE CONTRA RESSECAMENTO E OXIDAÇÃO - RENOVA AS SUPERFÍCIES NO COFRE DO MOTOR - DISPONÍVEL EM: 1,5L MODO DE USAR: 1. Certifica-se de que a superfície esteja limpa e seca; 2. Com auxílio de pistola pulverizadora ou pulverizador resistente à solventes; 3. Aplicar pequena névoa do produto até total cobertura de peça; 4. Aguardar secar por alguns minutos; 5. Caso opte por um acabamento mais fosco, remover o excesso com toalha de microfibra limpa e seca.', 99.62, 99.62, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-82619-mjpy2mu4k9afa5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1151751638%2F47354994402', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
