INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22018291285', 'Mandril Para Furadeira 1/2Pol. Aperto Rápido 2 - 13mm Para Brocas Bits Ponteiras Profissional', 'COMERCIAL VIPASA DISTRIBUIDORA. Mandril Para Furadeira 1/2Pol. Aperto Rápido 2 - 13mm Para Brocas Bits Ponteiras Profissional Mandril Para Furadeira 1/2Pol. Aperto Rápido 2 - 13mm Mandril Para Furadeira 1/2Pol. Aperto Rápido 2 - 13mm Descrição do Produto O Mandril de Aperto Rápido para Furadeira é feito de materiais de alta qualidade, e dispõe de um sistema de bloqueio automático que possibilita uma melhor aderência do mandril na furadeira. Seu mecanismo sem chave fornece instalação e fixação rápidas de brocas, é utilizado por diferentes profissionais que usam alguma furadeira em seu ambiente de trabalho. - Especificações Técnicas: :: Diâmetro da rosca: 1/2" :: Abertura: 2-13mm - Garantia: 3 meses Marca.: MTX *Imagens meramente ilustrativas *Todas as informações divulgadas são de responsabilidade do Fabricante/Fornecedor. COMERCIAL VIPASA DISTRIBUIDORA.', 49.99, 36.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lsmt0op5ird981', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F22018291285', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55505027793', 'Cunha Plástica para Cabo de Madeira Enxada Pá Pacote 12 Unidades Multiuso', 'Cunha Plástica para Cabo de Madeira – Enxada – Plastin Pacote com 12 Unidades Descrição do Produto A Cunha Plástica Plastin para Cabo de Madeira é indicada para a fixação segura de cabos em ferramentas manuais como enxadas, pás, foices, picaretas e similares. Fabricada em plástico de alta resistência, proporciona excelente travamento do cabo no olho da ferramenta, evitando folgas, deslocamentos e aumentando a segurança durante o uso. Seu formato foi desenvolvido para garantir encaixe firme e uniforme, distribuindo a pressão de maneira eficiente sem danificar o cabo de madeira. É uma solução prática, durável e resistente à umidade, não enferruja e não sofre oxidação, sendo ideal para uso profissional ou doméstico. O produto é comercializado em pacote com 12 unidades, oferecendo ótimo custo-benefício para reposição, oficinas, obras, agricultura e manutenção geral. Principais Características Produto: Cunha plástica para fixação de cabo Aplicação: Enxada e ferramentas com cabo de madeira Material: Plástico resistente de alta durabilidade Não oxida e não enferruja Fácil instalação Garante fixação firme e segura do cabo Marca: Plastin Embalagem: Pacote com 12 unidades Indicações de Uso Fixação de cabos de madeira em enxadas Fixação de cabos em pás, foices, picaretas e similares Uso agrícola, jardinagem, obras e manutenção geral Ideal para reposição e estoque Conteúdo da Embalagem 12 Cunhas Plásticas para Cabo de Madeira Observações Importantes Verifique a compatibilidade do tamanho da cunha com o cabo e a ferramenta. Produto indicado para uso em cabos de madeira. Cunha Plástica para Cabo de Enxada Pacote 12 Un Plastin Cunha Plástica Fixação Cabo Madeira Enxada 12 Un Cunha para Cabo de Enxada Plástica Plastin 12 Unidades cunha plástica, cunha para cabo, cunha para enxada, fixação de cabo, cunha cabo madeira, cunha ferramenta manual, cunha plastin cunha enxada, cunha agrícola, cunha reposição cabo, cunha ferramenta jardinagem, cunha para pá, cunha para foice, acessório para cabo de madeira', 16.99, 16.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8260v-mjrn8lfgwbuvcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F55505027793', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15790083112', 'Lampião A Querosene 24cm Lamparina Pequena Luminária Vermelho - Verde - Azul Cores Sortidas', 'COMERCIAL VIPASA DISTRIBUIDORA. Lampião A Querosene 24cm Lamparina Pequena Luminária Vermelho - Verde - Azul Cores Sortidas Produto muito Prático e Funcional pode ser usado em Ambiente Externo em Pergolado, Sítio, Camping, Pesca e outras utilidades. Podendo também ser adicionado Óleo de Citronela a Querosene para proporcionar Aroma ao Ambiente e servindo também de Repelente Natural. . Fabricado com Material de Qualidade . Durável . Composição FERRO e VIDRO . Gancho Resistente para mantê-lo pendurado. O Lampião a Querosene 24cm (Lamparina Pequena Luminária) é uma peça decorativa e funcional que pode ser utilizada para várias finalidades: Iluminação de Emergência: É útil em locais onde há falta de energia elétrica, proporcionando luz em situações emergenciais. Decoração: Seu design rústico e suas cores vibrantes (vermelho, verde, azul) tornam o lampião uma excelente peça decorativa para ambientes internos ou externos, como casas de campo, áreas de lazer, varandas e eventos temáticos. Camping e Atividades ao Ar Livre: Ideal para acampamentos, pescarias ou outras atividades ao ar livre, onde uma fonte de luz portátil é necessária. Ambiente Nostálgico: Cria uma atmosfera acolhedora e nostálgica, lembrando épocas em que o querosene era uma fonte de iluminação comum. Como funciona: É abastecido com querosene ou outro combustível similar. Possui um pavio que, ao ser aceso, gera luz através da combustão do combustível. COMERCIAL VIPASA DISTRIBUIDORA.', 64.99, 56.99, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-22110-amrjsbbb1ljvaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F15790083112', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
