INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19703162174', 'Pegador com Trava M 22cm - Oikos', 'Atire a primeira pedra quem nunca arranhou uma panela! Esse é o pegador com trava da OIKOS, com suas pontas de silicone ele escorrega pela panela toda sem deixar nenhum arranhão! O cabo em estrutura de inox não enferruja, protege contra o calor do fogão e ainda combate as mãos escorregadias. Sua trava também serve como furo passante, assim você pode pendurá-lo na parede. Disponível em três tamanhos, esses pegadores te ajudam a virar seus grelhados direto na assadeira ou só pegar a última rodela de cenoura mesmo.', 70.9, 47.9, NULL, 'Home & Living > Kitchenware > Spatulas & Cooking Tweezers', 'https://cf.shopee.com.br/file/sg-11134201-8262t-mldb3gpbiqyp6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F19703162174', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499567993', 'Faixa Elástica Pilates Elastiband Sveltus Multi 10kg', 'Faixa Elástica Pilates Elastiband Sveltus Multi 10kg COM CARGA, COMPOSTA DE ALÇAS - Para fácil fixação no local ou no corpo do usuário que mantém as mãos sempre livres. Para exercícios de membros superiores, inferiores e cor. Trabalha simultaneamente os principais grupos musculares, medindo e regulando a intensidade da carga durante os exercícios. Promove alongamento em todos os músculos. - Cada modelo corresponde a um peso, garantindo a execução do exercício adequado ao objetivo e ao nível de desafio. - É fabricada com material inodoro e que garante sua alta durabilidade, mantendo a elasticidade mesmo quando utilizada em água de piscina ou do mar e não se deteriorando no atrito com superfícies ásperas ou com o solado de calçados esportivos. - Pode ser utilizada por pessoas de todos os níveis de habilidade e faixa etária, individualmente ou em grupo. - A distancia entre as alças gradua a dificuldade dos exercícios. A ELASTIBAND É UMA ACADEMIA QUE CABE ATÉ MESMO NO SEU BOLSO ! - LEVE-A SEMPRE CONSIGO PARA CONTINUIDADE DE SUA ATIVIDADE FÍSICA E DO ALONGAMENTO EM CASA, EM VIAGEM OU NOS INTERVALOS DE TRABALHO. MANTENHA-SE SEMPRE COM SAUDE E EM FORMA ! As faixas elásticas já estão presentes na rotina da fisioterapia, em fitness e nos esportes, nos exercícios funcionais e de reabilitação, e no treinamento de força, porém são conhecidas pela fragilidade do material que se deteriora após curto período de uso e pelo odor desagradável que lhes é característico. O material de fabricação das ELASTIBANDs trouxe a solução para essa deficiência, além de INOVAR, com as diferentes tensões de cada modelo: a carga dos exercícios é precisa, garantindo os resultados. Contém 1 faixa de 10 kg de resistência com 8 alças variando entre 11cm e 16,5 cm. Acompanha manual com exercícios. Cor: Verde Medidas: comprimento 110cm X largura 4cm Composição: 39% elastodieno e 26% polyamida - Não contem látex Manutenção: Pode ser lavada à mão com água fria ou na temperatura máxima de 30° , não utilize a maquina de lavar que poderá deteriorá-la. Conteúdo da embalagem 1 unidade da Faixa Elástica Pilates Elastiband Sveltus Multi 10kg Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 159.0, 159.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Yoga & Pilates', 'https://cf.shopee.com.br/file/sg-11134201-7rfi6-m3dj0a29viirfb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429392805%2F19499567993', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
