INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397911057', 'Kit Cueiro Minasrey Loupiot Capadócia - 03 Unidades', 'Kit Cueiro Minasrey Loupiot Capadócia - 03 Unidades O kit cueiro Minasrey da linha Loupiot Capadócia é confeccionado em tecido flanelado, super macia. Seu modelo pode ser usado de diversas maneiras, ajuda a esquentar ainda mais o cobertorzinho, servindo como uma segunda mantinha, além disso, o cueiro também auxilia no alívio das cólicas, que tanto incomodam os pequenos até cerca de três meses. O Cueiro é indispensável no enxoval, pois pode ser usada para forrar berço, carrinho, moisés e onde mais o bebê for deitar, além de possuir estampa fofa e manter o bebê quentinho. Informações Adicionais: Tamanho: Único Cores: Azul Referência: 355704 Medidas: 50cm x 80cm Marca: Minasrey', 35.2, 35.2, NULL, 'Mom & Baby > Diapering & Potty > Cloth Diapers & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rdy5-m0yrlzjuakzr85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F22397911057', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
