INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693204739', 'Kit 3 Blusa Manga Curta Infantil Menina 100% Algodão Lisa Basica', 'Kit de 3 Blusas para Meninas - Conforto e Estilo Adicione conforto e estilo ao guarda-roupa da sua pequena com nosso Kit de 3 Blusas para Meninas! Perfeito para qualquer ocasião, este kit é uma escolha prática e encantadora. ✅ Inclui 3 blusas: Confeccionadas em 100% algodão, garantindo maciez e conforto para a pele delicada das meninas. ✅ Design encantador: Nossas blusas apresentam designs variados e cores vibrantes, ideais para qualquer estação do ano. ✅ Versatilidade: As blusas são perfeitas para usar no dia a dia, seja para passeios, escola ou momentos de lazer em casa. Tamanhos Disponíveis: Tamanho 2: Veste 1 ano Tamanho 4: Veste 3 anos Tamanho 6: Veste 4/5 anos Tamanho 8: Veste 6/7 anos Tamanho 10: Veste 8/9 anos Os tamanhos podem variar de acordo com o biotipo/tamanho de cada criança. 👉 IMPORTANTE! Consulte a tabela de medidas nas imagens para garantir o tamanho ideal. IMPORTANTE! ⚠️ Enviaremos modelos variados conforme disponibilidade em estoque, mas todas as peças são cuidadosamente selecionadas para garantir qualidade e estilo. ⚠️ Na compra de 1 kit, você receberá modelos diferentes e variados, sem repetições. Ao adquirir 2 ou mais kits, pode haver a possibilidade de repetir algumas cores.', 75.0, 39.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Tops', 'https://cf.shopee.com.br/file/br-11134207-820lv-mnkg6ed7xl34c1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341167297%2F22693204739', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
