INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598053003', 'Gel de Barbear Gillette Fusion ProGlide 2 em 1 Hidratante 200ml', 'GEL DE BARBEAR GILLETTE FUSION PROGLIDE HIDRATANTE Gillette ProGlide Hidratante, apresenta manteiga de karité e glicerina na composição que ajuda a manter a pele hidratada durante o barbear. Recomenda', 54.99, 54.99, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/sg-11134201-823p3-mohbk7wl6tjd03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23598053003', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097068034', 'Kit 2 Sabonete em Barra Dove Delicious Care Karité Leve Mais Por Menos com 6 Unidades de 90g cada', 'Karite e Baunilha Dove Sabonete em Barra 90g Com 1/4 de creme hidratante e agentes de limpeza suaves, Dove ajuda a proteger a hidratação natural da pele. Dove não resseca a pele como sabonetes comuns. Tecnologia de limpeza e manutenção da hidratação com suavidade para sua pele. Deliciosa fragrância de manteiga de karité e baunilha. Deixa a pele macia, bem cuidada e com aspecto saudável. Não é um sabonete comum, é um sabonete que ajuda na hidratação da pele. Dove não é um simples sabonete em barra comum. É um sabonete de beleza feito com tecnologia Syndet que vai além da limpeza, nutrindo a pele conforme remove a sujeira do dia a dia. O Sabonete Dove Delicious Care Karité e Baunilha faz uma espuma cremosa e deixa a sua pele com uma sensação renovada. Acreditamos que o banho pode ser uma oportunidade para você tirar um tempo só para você. É por isso que desenvolvemos o Sabonete Dove Delicious Care Karité e Baunilha, um sabonete que traz a você nossos agentes de limpeza suaves e 1/4 de creme hidratante, além de um perfume delicado e relaxante. Os benefícios da manteiga de karité para a pele são conhecidos há muitos anos: sua concentração de vitaminas e ácidos graxos tem propriedades hidratantes. Sua fórmula nutre e hidrata a pele enquanto limpa, deixando-a com uma sensação macia e bem cuidada. Para uma melhor experiência no banho, sugerimos o seguinte modo de uso: primeiro, molhe as mãos e passe o Sabonete Dove Delicious Care Karité e Baunilha entre elas até formar uma espuma. Em seguida, massageie a espuma pelo seu corpo e, por último, enxágue com água morna. O Sabonete Dove Delicious Care Karité e Baunilha é dermatologicamente recomendado. Você pode ser fã do Sabonete Dove Delicious Care Karité e Baunilha, mas com tantas opções, por que não experimentar todos? Afinal, temos um sabonete para cada momento.', 53.98, 53.98, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-823rj-mok21agyes5ebf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23097068034', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
