INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598891056', 'Kit 4 Esmalte Risqué Nova Cor Cremoso Cor Nudeu Tempo 8ml', 'Esmalte Risqué Cremoso – Nudeu Tempo Apresente-se ao mundo com unhas impecáveis usando o Esmalte Risqué Cremoso na delicada cor Nudeu Tempo. Este esmalte é a escolha perfeita para quem busca um tom neutro que combina com qualquer ocasião, adicionando um toque de sofisticação ao seu visual. Com sua fórmula cremosa, o esmalte Risqué garante uma aplicação suave e uniforme, proporcionando uma cobertura intensa em cada camada. Além disso, sua secagem rápida e longa duração fazem com que suas unhas permaneçam bonitas por muito mais tempo. O Nudeu Tempo é ideal para o dia a dia e também para eventos especiais, sempre garantindo um acabamento elegante e refinado. O frasco de 8ml é prático e ideal para ter sempre à mão. Experimente o Esmalte Risqué Cremoso e descubra como é fácil ficar deslumbrante com unhas bem cuidadas. Realce sua beleza com a linha de esmaltes Risqué – a escolha que você merece!', 27.96, 27.96, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-825ar-mqxnvp3bcfeudc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23598891056', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
