INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293557329', 'Kit 2 Tintura Creme Nutrisse Garnier Aveia 60 Kit', 'TINTURA CREME NUTRISSE GARNIER AVEIA 60 Cabelos nutridos, melhor cor. Cores vivas, radiantes e longa duração. Nutrisse Creme 60 tem NOVA FÓRMULA, agora com um resultado de cor muito mais intenso. Além disso, seu novo creme de tratamento Blindagem Nutritiva, fixa a cor profundamente e por mais tempo. Sua textura creme é de fácil aplicação e não escorre. Experimente e surpreenda-se. 100% cobertura dos fios brancos. Resultados comprovados: • Formula revolucionária antiressecamento. • Cor profunda e vibrante por mais tempo. • 100% de cobertura dos fios brancos. • Cabelos macios e brilhantes. Esta embalagem contém: • 1 Aplicador de revelador 67,5ml. • 1 Tubo de máscara colorante 45g. • 1 Cápsula de concentrada nutritiva 4,5 ml. • 1 Sachê de tratamento blindagem 20 ml. • 1 Par de luvas e 1 folheto explicativo', 66.78, 66.78, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-823pe-mon7uddk5csr0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23293557329', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
