INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23692778221', 'Caixa Amplificada Bluetooth Mondial Connect Lights Plus CM-700 - Bivolt', 'A Mondial é uma das marcas de eletrodomésticos preferidas do país. E com muita tecnologia e estilo, promete fazer da sua festa um verdadeiro sucesso! A Caixa de som Amplificada Multiuso Connect Lights Plus possui 700W RMS de potência com alto-falante de 15 polegadas. Tem ainda conexão Bluetooth, entradas USB, cartão SD, auxiliar, de microfone e guitarra, além de rádio FM e bateria recarregável bivolt. Sua bateria interna recarregável bivolt permite que você leve o som para onde quiser e uma entrada 12V DC para conectar em baterias externas, como no carro, por exemplo. Já com a conexão bluetooth, você pode colocar a música do seu celular direto no som sem precisar usar um monte de fios. Além disso, você pode ligar Pendrives, MP3 e MP4 players, cartões de memória SD, fones, além de microfones, guitarras e a tecnologia TWS (True Wireless Stereo), que permite conectar duas caixas CM-700 via Bluetooth e amplificar ainda mais o seu som. Com o display digital, é mais fácil ver o que está tocando e ainda sintonizar a Rádio FM digitalmente. Aproveite as flash lights, luzes coloridas que piscam e ofereça muito mais animação para sua festa!', 835.99, 749.9, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/sg-11134201-822zs-mibre6b2i1vs0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F23692778221', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
