INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23896493013', 'Óculos De Sol Flexível Com Estojo E Lenço 14210 - Buba', 'DESCRIÇÃO DO PRODUTO: Os olhos do bebê são sensíveis aos raios uv e é necessário protegê-los com o filtro solar. Os óculos de sol flexíveis da buba são confortáveis, leves, resistentes e se ajustam perfeitamente ao rosto do pequeno. São produzidos sem bpa e as lentes protegem os olhos dos raios uva e uvb, são ideais para proteger os olhinhos delicados do bebê. São Confortáveis, leves e resistentes, se ajustam perfeitamente ao rosto da criança. CARACTERÍSTICAS TÉCNICAS: Conteúdo da Embalagem: Óculos de sol e armação flexível. Dimensões Aproximadas do Produto: 10cm x 3cm x 10cm (Altura x Largura x Comprimento/Profundidade). Dimensões Aproximadas da Embalagem: 15cm x 3cm x 6cm (Altura x Largura x Comprimento/Profundidade). Material/Composição: Armação 100% Elastômero Termoplástico, Lentes e estojo 100% Policarbonato, botão do estojo 100% Ferro e lenço 100% microfibra. Idade Mínima Recomendada: A partir de 03 anos. Participantes: 01 pessoa. Marca: BUBA Referência: 14210 Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. Produto lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 62.49, 54.99, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Eyewear', 'https://cf.shopee.com.br/file/sg-11134201-7qveo-lk011qyyb78r2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F23896493013', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798235945', 'Pote de Vidro Laura Incolor 370ml', 'Ter uma cozinha organizada e limpinha é o sonho de qualquer dono de casa. Potes de vidro estão cada vez mais conquistando espaço nas bancadas e armários. Eles permitem que tenhamos boa visibilidade dos alimentos e possuem tampa, permitindo guardar o alimento por mais tempo e dando um toque decorativo à sua cozinha!', 16.99, 16.99, NULL, 'Home & Living > Dinnerware > Others', 'https://cf.shopee.com.br/file/sg-11134201-82597-mqz2qcihetxo29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F22798235945', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
