INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23799164143', 'Meia Social Meianyl 6002-001', 'Características: Meia social clássica masculina Confeccionada em microfibra leve, de toque suave. Punho canelado confere melhor ajuste. Outros Detalhes: Fabricada por LUPO S/A. Cano: Longo. Composição: 85% Poliamida no mínimo.', 36.9, 36.9, NULL, 'Men Clothes > Socks', 'https://cf.shopee.com.br/file/sg-11134201-821d4-mgwg1x830zrc89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401430924%2F23799164143', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21297425509', 'Filtro Óleo Vw New Beetle 1998 a 2015 - 161834 - WO370', 'Filtro Óleo Vw New Beetle 1998 a 2015 161834 WO370 MOTOR 2.0 Basicamente, os filtros lubrificantes devem atender às funções de reter todos contaminantes que possam causar danos ao perfeito funcionamento do motor, mantendo as características de estrutura do óleo, uniformidade de circulação e eficiência no período de uso pelo motor. O Filtro do Óleo retém os contaminantes contidos no sistema de lubrificação, principalmente os abrasivos (metais) , provenientes do atrito das partes móveis do motor que permanecem em suspensão no óleo lubrificante.', 27.52, 27.52, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbm7-llwicswr847u24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21297425509', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210139918', 'Refrigerante Coca-Cola', 'O sabor clássico e inconfundível que você já conhece, perfeito para compartilhar com amigos e familiares em qualquer ocasião. Refrescante e saborosa, a Coca-Cola Original é ideal para acompanhar suas refeições e momentos especiais. Disponível em prática embalagem PET de 2L.', 12.79, 9.99, NULL, 'Food & Beverages > Beverages > Carbonated Drinks & Tonics', 'https://cf.shopee.com.br/file/sg-11134201-8259k-mr0bx9us8xl278', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554792%2F58210139918', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499032835', 'Filtro Gasolina COURIER 2007/2012 - 43275 - FCI1650', 'Filtro Gasolina COURIER 2007/2012 (Van / L / LX) - Motor 1.6 8v Flex - (Mecânico) (Plástico) O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 32.17, 32.17, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbme-lmxgm2whh4fd26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F19499032835', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260138078', 'Cerveja Heineken Barril 5L', 'O barril Heineken proporciona uma experiência única para você e seus amigos. Não pode ir a um bar? Então leve o bar até você. O barril Heineken conta com 5 litros da mais icônica cerveja Puro Malte. Heineken é uma cerveja lager Puro Malte, refrescante e de cor amarelo-dourado, produzida com ingredientes 100% naturais: água, malte e lúpulo. Durante o processo de fermentação da Heineken, a exclusiva Levedura A é responsável pelo sabor característico e bem equilibrado, com notas frutadas sutis. A cerveja é fabricada em tanques horizontais para mais sabor e consistência. É por isso que nenhuma outra cerveja tem o gosto de Heineken. Preparado para servir a cerveja perfeita? Seja em uma festa, churrasco ou para assistir um jogo de futebol, você pode servir seus convidados o copo perfeito de cerveja gelada!', 132.99, 132.99, NULL, 'Food & Beverages > Alcoholic Beverages > Beer & Cider', 'https://cf.shopee.com.br/file/sg-11134201-82586-mqnekp2sc07fb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554792%2F58260138078', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15847355412', 'Whey Protein 6 Six Protein Advanced c/ ZMA 900g - Massa muscular e Disposição - Bodybuilders', '1. Mix de Proteínas Poderoso: Albumina, Whey Protein, Soy Protein, Proteína Hidrolisada da Carne e Isolada de Soja - um timaço que ajuda no ganho de massa magra e na definição dos músculos. Resultados garantidos! 💪🏋️‍♀️ 2. Inovação Total: A Six Protein mandou bem na mistura de proteínas animais e vegetais, criando um suplemento com mais aminoácidos do que uma whey protein comum. Absorção rápida e recuperação imediata, é tudo o que você precisa! 🌈✨ 3. Waxy Maize - o Carboidrato dos Sonhos: Zero picos de insulina, zero gordurinhas indesejáveis! O Waxy Maize é o carboidrato perfeito para manter, recuperar e saciar, fazendo seus objetivos chegarem mais rápido e de forma eficaz. 🍚🔥 4. Proteínas Estrelas: Albumina: Recuperação pós-treino e aumento de massa muscular. Whey Protein: Rápida absorção, anabolismo muscular e redução de carboidratos e gorduras. Proteína Hidrolisada da Carne: Rico em aminoácidos, sem gorduras e lactose. O pacote completo! 5. Dose Certa para o Sucesso: 40g de Six Protein Advanced com ZMA é o ideal pós-treino. Recuperação completa e síntese protéica muscular a todo vapor! 🚴‍♂️🏋️‍♂️ 6. Momento Perfeito para o Shake: Após o treino é o auge! Seus músculos vão agradecer por receberem um banho de aminoácidos. Shake com água gelada, e pronto, tá na hora de ser o rei da recuperação! 🥤❄️', 64.9, 64.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lrj0p9oez5tna6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F667636637%2F15847355412', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43279683707', 'Kit 2 Cadeiras de Jantar com Assento Estofado Multimóveis CR50258', 'Leve mais charme e personalidade para sua sala de jantar com o Kit 2 Cadeiras de Jantar com Assento Estofado Multimóveis CR50258. Combinando texturas que são tendência na decoração, essas cadeiras unem o conforto do estofado em Bouclé com a leveza e elegância do encosto em tela. O resultado é um design moderno e sofisticado, ideal para quem busca criar um ambiente acolhedor, estiloso e cheio de personalidade para os momentos à mesa. Diferenciais: - Estrutura em MDF/MDP/madeira maciça: maior resistência e estabilidade para o uso diário. - Acabamento em pintura UV/PU: facilidade na limpeza do móvel. - Pés em MDF de 25mm com sapatas de proteção: garantem maior firmeza na estrutura e ajudam a evitar o contato direto com o chão, protegendo o piso. - Assento com espuma de densidade D20: proporciona mais conforto durante o uso, tornando as refeições ainda mais agradáveis. - Revestimento em tecido Bouclé: toque macio que proporciona mais conforto e sofisticação ao ambiente. - Encosto em tela: detalhe que traz leveza ao design da cadeira e acrescenta um toque elegante e atemporal à decoração do ambiente. - Peso máximo suportado de até 110kg por cadeira: segurança e confiabilidade no uso. - Estilo sofisticado: ideal para compor salas de jantar com elegância e personalidade. Conteúdo da Embalagem: 2 (duas) Cadeiras Manual de Montagem Kit Ferragem Dimensões do Produto Montado (por unidade): Altura: 92cm | Largura: 46cm | Profundidade: 40cm *Você pode consultar as medidas detalhadas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 699.99, 599.99, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-81zwi-mmiz6uyha1oj97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F43279683707', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19699196593', 'Guarda-Roupas Casal 100% MDF Severo 8 Portas 4 Gavetas Multimóveis', 'Dimensões do produto montado: Altura: 217cm Largura: 242cm Profundidade: 47cm *Você pode consultar as medidas detalhadas na imagem técnica do produto. O Guarda-Roupas Casal MDF 8 Portas 4 Gavetas Multimóveis CR35200 é produzido em MDF 12/15mm com acabamento em pintura UV, garantindo durabilidade e resistência. Conta com 8 portas com puxadores em MDF, 4 gavetas com corrediças metálicas (mais leveza no manuseio), prateleiras internas espaçosas e cabideiros em madeira revestidos, possuindo amplo espaço interno para organizar suas roupas, acessórios e, até mesmo, calçados, e deixando o quarto sempre em ordem. Com design moderno e elegante, este guarda-roupas combina perfeitamente com qualquer estilo de decoração, proporcionando um toque sofisticado ao ambiente. Conteúdo da Embalagem: 1 (um) Guarda-Roupas Manual de Montagem Kit Ferragem *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 1979.99, 1719.99, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-7rcbv-lreuikdaos7j73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F19699196593', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19464573696', 'Armário de Cozinha Completa de Canto com Rodapé Veneza Multimóveis MP2098.964 Branco/Preto', 'A Cozinha Completa de Canto com Rodapé Veneza Multimóveis MP2098 com Armário e Balcão tem um excelente custo benefício e um amplo espaço interno. Produzida em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade e resistência, possui corrediças metálicas (mais leveza no manuseio), rodapés, que deixam o ambiente mais estiloso, puxadores em ABS e tampo em MDP 15mm com pintura de alta resistência. Os módulos de canto podem ser montados dos dois lados (esquerdo ou direito), conforme a sua preferência. Esta cozinha conta, ainda, com balcão com tampo removível (compatível com pia de 120 cm), com 1 gaveta e 2 portas. Os módulos são individuais e você pode montar da maneira que se adaptar melhor ao seu ambiente. Para deixar sua cozinha mais bonita e organizada, possui vidro reflecta, espaço para forno e microondas e compartimento especial para utensílios mais altos. Conteúdo da Embalagem: 1 (um) armário para forno e microondas 62cm 1 (um) armário aéreo de canto 90cm 1 (um) armário aéreo com portas de vidro 120cm 1 (um) balcão com tampo de canto 90cm 1 (um) balcão com tampo 120cm 1 (um) kit com rodapés Dimensões do produto montado: Altura: 203cm | Largura: 152 x 172cm | Profundidade: 32cm (aéreos) - 53cm (balcão com tampo e paneleiro) *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 2859.9, 1999.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7qvf0-li0fqqitmmrx7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F19464573696', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12526440642', 'COQUETELEIRA 600ml - Bodybuilders', '⚡Procurando a companheira perfeita para seus shakes de proteína, smoothies saudáveis e bebidas energéticas? Apresentamos a Coqueteleira BODYBUILDERS de 600ml, a sua aliada na busca por uma vida mais saudável e ativa! ➡️Características Principais: ⚡Capacidade Ideal: Com uma capacidade generosa de 600ml, esta coqueteleira é perfeita para misturar suas bebidas favoritas sem derramar uma gota. Ela possui marcações de volume para facilitar a medição dos ingredientes. ⚡Design Prático: A Coqueteleira BODYBUILDERS conta com uma tela para facilitar a mistura dos suplementos e tem um design ideal para encaixar no console do carro, oferecendo máxima praticidade para você. Seu design à prova de vazamentos evita bagunças indesejadas. ⚡Materiais de Qualidade: Feita com plástico de alta qualidade e livre de BPA, a coqueteleira é segura para a saúde e fácil de limpar. Além disso, é resistente a odores e manchas, garantindo que suas bebidas sempre tenham um sabor fresco. ⚡Estilo Moderno: Disponível na preta e um design moderno, a coqueteleira BODYBUILDERS combina estilo com funcionalidade! ⚡Versatilidade: Esta coqueteleira não é apenas para shakes de proteína; você pode usá-la para fazer smoothies, sucos, bebidas energéticas, ou até mesmo misturar suplementos nutricionais. Versátil e prática, é a escolha perfeita para um estilo de vida saudável. ➡️A Coqueteleira BODYBUILDERS de 600ml é a parceira perfeita para alcançar seus objetivos de saúde e fitness. Não perca mais tempo misturando suas bebidas manualmente. Faça sua escolha e leve para casa a coqueteleira que vai revolucionar sua jornada de nutrição e bem-estar! ⚡Peça a sua Coqueteleira BODYBUILDERS de 600ml hoje mesmo e comece a desfrutar de bebidas deliciosas e nutritivas como nunca antes! Seu corpo e paladar vão agradecer! (O modelo/cor da coqueteleira pode variar de acordo com a disponibilidade em estoque.)', 19.9, 19.9, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mavm0vvarzzt67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F555509944%2F12526440642', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259470106', 'SuperCoffee 3.0 Língua de Gato', 'Mais do que um pré-treino e mais do que um café, o SuperCoffee é uma bebida energética e um suplemento alimentar com benefícios para o corpo, a mente e o bem-estar diário. Reunimos tudo que acreditávamos ser necessário, em uma fórmula única, para proporcionar energia inteligente, potente e que não oscila e maior performance cognitiva, para quem deseja bem-estar e alta performance. O SuperCoffee Língua de Gato é uma edição especial, resultado da parceria entre a Caffeine Army e a Kopenhagen, que traz o sabor clássico do chocolate Língua de Gato com os benefícios funcionais do SuperCoffee. Rico em nutrientes que promovem energia limpa e duradoura, ideal para quem busca manter o foco e a disposição ao longo do dia.', 219.99, 219.99, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/sg-11134201-8258n-mqnel13mtfy99b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554958%2F58259470106', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19850770228', 'Fluído Para Freios Dot 3 (500 Ml) Radnaq', 'Atacado 12 unidades Fluido para Freio Dot 3 Radnaq 500 ml Fluído Para Freios DOT 3 (500 ml)O Fluído para freios DOT 3 Radnaq foi especialmente desenvolvido para o sistema hidráulico de freios de veículos. Proporciona segurança nos momentos de frenagem. O produto atende as Normas NBR 9292 Tipo 3, SAE-J 1703 e FM/SS nº 116 DOT3, com ponto de ebulição acima de 205 ºC.Embalagem: 500 ml=======================================================================Clique no botão "Comprar agora" para garantir Atacado 12 unidades de Fluido Para Freio Dot 3 Radnaq 500 Ml pelo melhor preço!', 21.27, 21.27, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-22100-qz228upti4iv07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F19850770228', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892104561', 'Jogo Criando Histórias - Grow 4279', 'JOGO CRIANDO HISTÓRIAS 4279 Nome da marca: Grow Gênero: Narração de histórias Idioma: Português Com o objetivo de desenvolver a fluidez na fala e a imaginacao, Criando Historias traz uma atividade divertida que vai estimular a criatividade das criancas! Elas devem contar historias usando as quantidades de cada tipo de cartela indicada pela carta selecionada, envolvendo quatro diferentes categorias: personagens, objetos, lugares e acoes.', 59.99, 59.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98p-ll522f5d4h1ne2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F947344701%2F23892104561', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259710374', 'Ruffles Cebola e Salsa Batata Ondulada', 'Ruffles é a batata que une todo mundo no pacote há mais de 30 anos. Com sabor de cebola e salsa, feita de batata de verdade e com muita crocância, é perfeita para qualquer momento. Experimente a explosão de sabor a cada mordida!', 15.79, 15.79, NULL, 'Food & Beverages > Snacks > Chips & Crisps', 'https://cf.shopee.com.br/file/sg-11134201-825aq-mqneldo66rrjf4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555116%2F58259710374', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21950045784', 'Rodabrisa Gel "Citrus" 60g - Rodabrill', 'Rodabrisa Aroma Gel - CitrusO Rodabrisa Aroma Gel foi desenvolvido com tecnologia de alta performance em aromatização. Seu novo formato impede o vazamento, tornando o produto mais seguro e prático.Contém uma exclusiva e marcante fragrância que proporciona um ambiente agradável no interior do seu carro.Clique e veja outras fragrâncias: **FRETE POR CONTA DO COMPRADOR**', 12.64, 12.64, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-22090-7yyy21btuzhv4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F21950045784', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298121712', 'Disco Freio Toyota Hilux 2006 a 2015 - 1102435 - HF512', 'Disco Freio Toyota Hilux 2006 a 2015 1102435 HF512 SW4 - 3.0 (ARO 16) - DIANTEIRO - VENTILADO - SEM CUBO - (6 FUROS) (DIAMETRO 319MM - DIAMETRO DO FURO CENTRAL 108MM) O disco gira tendo em ambos os lados as pastilhas de freio. Para isso, há a necessidade de haver uma folga entre eles. Quando o pedal de freio é acionado e as pastilhas entram em contato com o disco, comprimindo-o pela força de atrito, causando a diminuição da rotação roda. - Disco Ventilado - são utilizados em veículos que exijam maior eficiência nos freios, onde a temperatura de frenagem também é maior. - Disco Sólido - são usados normalmente em veículos que exijam menos eficiência no freio.', 296.1, 296.1, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd41-lwsltgruhomr39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22298121712', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21398007563', 'Filtro Ar Cabine Gm Astra 2003 a 2012 - 1353330 - AKX35264F', 'Filtro Ar Cabine Gm Astra 2003 a 2012 1353330 AKX35264F (Advantage / Confort / Elegance / Elite / Sport / CD / GLS) - 2.0 8V Flex Power - (Automático / Mecânico) - (Sem carvão) Os filtros do ar para cabine são produzidos com fibras carregadas eletrostaticamente. Este filtros possuem camadas protegidas de um lado por um pré-filtro para reter partículas maiores. Do lado oposto possui uma camada de proteção a danos ao filtro.A função do meio filtrante é remover a maior quantidade possível de contaminantes do sistema do ar, oferecendo o mínimo de restrição ao fluxo de ar.', 31.47, 31.47, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7ravn-maovd42bhbww84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21398007563', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16470813296', 'Apoio de Braço Hb20 Hb20s E Hb20x Ano 2013 Até 2024 C/ Porta Objeto', 'Apoio de Braço Encosto, Descanso de Braço Hb20 Hb20s Hb20x 2013 Até 2024. O apoio de braço é um item automotivo que proporciona um conforto único ao motorista, é um acessório indispensável para viagens longas ou trânsitos intensos na cidade, deixa o interior do veiculo com uma aparência luxuosa e elegante, oferecendo um espaçoso porta objetos onde o(a) motorista pode armazenar itens como: carteira, celular, caneta, moedas, batons/maquiagens, entre outro objetos que normalmente ficam soltos pelo veículo. O Apoio de Braço NAT possui uma instalação simples e intuitiva, o motorista consegue realiza-la em sua própria residência, não sendo necessários furos ou colas para fixação. O produto é encaixado no console central do veículo e é confeccionado em plástico ABS de alta resistência com sua estrutura em aço carbono. Informações: * Para o Modelo Hb20 Hb20s Hb20x 2013 Até 2024. * Produto Nacional. * Braço articulado que permite flexibilidade na Regulagem. * Acabamento Sofisticado. * Acabamento Interno em Santoprene , evitando que objetos deslizem e façam barulho. * Instalação simples, rápida e intuitiva. * Não precisa realizar furos ou uso de colas, basta apenas encaixar no console central. * Revestimento em matéria ecológico de alta qualidade. * Juntas Articuladas. * Espaço Interno dividido em dois compartimentos e porta canetas. * Base em aço de carbono de alta qualidade e resistência. Veículos Compatíveis: * Modelo: Hb20 * Ano: 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023 e 2024. Dados Técnicos: * Peso: 2,0 kg. * Altura: 31 cm. * Comprimento: 30 cm. * Largura: 12 cm. Cores Disponíveis: * Preto Com Linha Preta. * Cinza Com Linha Cinza. * Grafite Com Linha Grafite. * Preto Com Lina Cinza. Conteúdo * 01 Apoio de braço. Garantia De Fabrica 3 meses * Imagens meramente ilustrativas. Atenção: Para compras realizadas em nome de Pessoa Jurídica/CNPJ, não serão faturadas, no momento não estamos gerando nota para CNPJ, caso tenha interesse em efetuar compras com o CNPJ entre em contato com a fábrica. Por favor solicitamos que compre como pessoa física/CPF para que seus pedidos possam seguir conforme o programado e prazo passado. Sobre a Marca: A Indústria NAT tem orgulho de ser uma empresa nacional, com sua sede em São Paulo, que está há mais de 20 anos construindo uma história de sucesso no âmbito do desenvolvimento de peças automotivas que acompanham e solucionam as necessidades de consumo do mercado, com o mais alto padrão de qualidade, proporcionando o melhor custo-benefício aos consumidores e sempre buscando ser referência em sua atuação. Seus produtos são produzidos em território nacional e estão presentes em toda América Latina.', 229.9, 179.33, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Cup Holder and Organizers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m285dtl3syxia5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F660182224%2F16470813296', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20297667580', 'Agulha Carburador Fiat Prêmio 1985 a 1990 - 104534 - 71751', 'Agulha Carburador Fiat Prêmio 1985 a 1990 104534 71751 MOTOR 1.3/1.5 ÁLC CARBURADOR WEBER 460 DMTI (175)', 26.96, 26.96, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd4q-lugmzvuxwsqj1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20297667580', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18398661965', 'Tampa Do Filtro De Ar Condicionado Clio Symbol CES2104', 'FILTRO DE AR CONDICIONADO CLIO SYMBOL ADAPTAÇÃO COM TAMPA NESTE KIT vão 3 PARAFUSOS 1 FILTRO 1 TAMPA Qual a importância de trocar o filtro de ar condicionado? A necessidade de trocar o filtro não só existe como é de extrema importância. Afinal, o ar que você respira dentro do carro passa por ali e, quanto mais sujo ou velho ele estiver, pior será a qualidade do ar no interior do carro. O filtro tem a função de reter poeira, fuligem e eliminar qualquer tipo de impureza do ar.', 39.99, 39.99, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lujo97xvngio6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1021060335%2F18398661965', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251990485', 'Vestido infantil menina colorblock Brandili -Rosa', 'Deixe sua pequena ainda mais charmosa com o vestido infantil da Brandili. Confeccionado em meia malha, ele apresenta uma modelagem colorblock que combina cores vibrantes de forma moderna. O decote quadrado e as mangas com babado trazem delicadeza, enquanto as costas cruzadas adicionam um toque especial. As pregas na saia criam um efeito rodado encantador, perfeito para looks estilosos e confortáveis. Ideal para qualquer ocasião, esse vestido é uma escolha certeira para o guarda-roupa da sua menina.', 109.99, 109.99, NULL, 'Baby & Kids Fashion > Girl Clothes > Dresses', 'https://cf.shopee.com.br/file/br-11134207-820l9-mqyzdo7m8cn885', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1587066956%2F58251990485', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251990878', 'Vestido infantil menina de flores Brandili -Rosa', 'Encante sua pequena com este vestido infantil da Brandili, confeccionado em meia malha com estampa delicada de flores. As mangas curtas e a gola redonda trazem um toque de frescor, enquanto as pregas na saia garantem um efeito rodado adorável. Ideal para o dia a dia, este modelo oferece conforto e estilo, perfeito para brincar e se divertir. Combine com sandálias e um chapéu para um look encantador que vai fazer sucesso em qualquer ocasião.', 64.99, 64.99, NULL, 'Baby & Kids Fashion > Girl Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-8262r-mksc7grxedc368', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1587066956%2F58251990878', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5057453698', 'Adesivo De Parede Decorativo Good Vibes Only', 'Adesivo Decorativo de Parede para Sala Quarto Caligrafia Escrita Frase Good Vibes Only Boas Vibrações Apenas Positividade 55x45 cm Os Adesivos de Parede da ArteDecor são produzidos com material de alta qualidade, recortados eletronicamente. São várias cores à sua escolha, possuem durabilidade estimada de 7 anos em ambiente interno. Podem ser lavados com água e sabão neutro. Fáceis de instalar, você mesmo pode aplicar. Segue anexo ao produto o manual de aplicação. Podem ser aplicados em superfícies lisas sem texturas ou irregularidades, ideais para aplicação em paredes, azulejos, vidros, móveis, pisos, portas, geladeiras, espelhos ou onde sua imaginação permitir. Se as medidas anunciadas não forem as ideais, confeccionamos no tamanho necessário. Contate-nos através do campo de perguntas.', 24.9, 19.9, NULL, 'Home & Living > Decoration > Wallpapers & Wall Stickers', 'https://cf.shopee.com.br/file/550ad155722db38759514832d99aab96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322399178%2F5057453698', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197626840', 'Mangueira Radiador Fiat Uno 1985 a 2001 - 1349097 - 908256', 'Mangueira Radiador Fiat Uno 1985 a 2001 1349097 908256 Superior Radiador MTR 1.5 8V - (Ø:33mm) (Medida: 15cmx24cm) O liquido entra no radiador pela "mangueira superior", em geral conectada na parte de cima do radiador. A medida que o liquido desce, ele passa por canais no radiador resfriados por meio de passagem do ar pelas aletas de refrigeração entre os canais. Depois ser resfriado, o liquido sai do radiador pela "mangueira inferior". Em geral, há uma mola dentro dessa mangueira para evitar que ela quebre quando a bomba de agua puxa o liquido do radiador.', 32.26, 32.26, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-823rh-moydnfbx3klddf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23197626840', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997835741', 'Conector Fluxo D Água Vw Bora 2000 a 2010 - 841033 - 087223', 'Conector Fluxo D Água Vw Bora 2000 a 2010 841033 087223 2.0 - (Sem Ar)', 46.81, 46.81, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd6n-luimjegbh62m57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23997835741', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799247399', 'Sensor Map Pressão Fiat Palio 1996 a 2007 - 506044 - 1707', 'Sensor Map Pressão Fiat Palio 1996 a 2007 506044 1707 (Weekend) - Motor 1.0/1.3/1.4/1.5/1.6 8v 1.3/1.6 16v - Gasolina/Flex - (4 Vias) O Sensor de Pressão Absoluta (MAP) informa à unidade de comando (UCE) a pressão absoluta medida dentro do coletor de admissão nos diversos regimes de funcionamento do motor. O valor obtido é somado à informação da temperatura de ar.Com esses dados, o sistema identifica a massa de ar que está sendo admitida, calcula o avanço da ignição e o tempo de abertura do bico injetor, buscando sempre a ideal relação ar/combustível.', 154.39, 154.39, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd4k-luiaz8hbs0od6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18799247399', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098252183', 'Scarpin Feminino Bico Fino Salto Bloco Confortável com Fivela Sapato Social 18400', 'NOVIDADE NA LOJA! O Scarpin Feminino combina sofisticação e conforto para mulheres que não abrem mão de um look elegante. Com bico fino e salto bloco, ele oferece estabilidade e estilo ao mesmo tempo. O acabamento em verniz adiciona um toque de brilho e sofisticação, enquanto a fivela ajustável garante um ajuste perfeito ao pé. Ideal para o dia a dia, trabalho ou ocasiões especiais, esse modelo se destaca pelo conforto e versatilidade. • Salto bloco confortável • Material em verniz sofisticado • Bico fino elegante • Modelo de fivela em alta • Ideal para diversas ocasiões ••••••••••• TABELA DE MEDIDAS PALMILHA ••••••••••• Tamanho 34 -----> 23,2 cm Tamanho 35 -----> 24,0 cm Tamanho 36 -----> 24,5 cm Tamanho 37 -----> 25,0 cm Tamanho 38 -----> 25,8 cm Tamanho 39 -----> 26,4 cm Tamanho 40 -----> 27,0 cm ••••••••••• ESPECIFICAÇÕES DO PRODUTO ••••••••••• • Disponível nas cores: Preto, Off e Marsala • Material Interno: Forro Cacharrel Macio e Forro Sintético • Material Externo: Sintético Verniz Texturizado • Palmilha: Confortável e revestida em napa sintética com aplique da logo • Solado: PVC resistente e de qualidade • Altura do solado: 6cm • Fabricada com materiais de alta qualidade, esta sapatilha garante conforto durante todo o dia com elegância e estilo. • Direto da Fábrica. • Produto Original e Pronta Entrega. • Cada par é entregue em sua caixa individual, cuidadosamente embalado em um envelope plástico resistente. • Consulte nossa tabela de medidas antes da compra, para garantir o ajuste perfeito. •••••••••••••••••••••••••••••••••••••••••••••••••••••••• Bem-vindo à Lóris Shoes Oficial • Somos comprometidos com a excelência, nossos calçados são confeccionados com materiais premium de qualidade e acabamento primoroso. • Valorizamos a satisfação do cliente e buscamos sempre oferecer praticidade, envio rápido, qualidade e preços justos. • Assim como cada par de nossos sapatos é único, cada cliente é especial, e é por isso que buscamos oferecer um atendimento personalizado que você merece. • Queremos proporcionar a você a melhor experiência de compra. Entre no mundo da elegância e conforto com a Lóris Shoes Oficial. Compre agora o seu par perfeito e dê passos de confiança em grande estilo.', 149.8, 72.73, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/br-11134207-81ztg-mkwctij3yj2842', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F367507085%2F22098252183', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3167121009', 'Papel De Parede Auto Colante Nuvem Infantil Quarto', 'TAMANHO DO ROLO: Altura: 3 Metros Largura: 40 centímetros ATENÇÃO: Pedidos em datas diferentes ou separados, possuem tons de cor diferentes, compre tudo em uma única vez com a quantidade exata para sua parede. Caso tenha dúvidas sobre quantas unidades comprar, fale com nosso atendente no campo de perguntas, ficaremos felizes em ajudar. Prazo de postagem: 1 dia após a aprovação do pagamento. Os produtos podem apresentar diferença de até 15% nas tonalidades de uma compra para outra. Por isso é importante certificar-se de que a quantidade de rolos é suficiente para concluir o trabalho. Antes de aplicar abra os papéis em uma superfície plana, verifique a emenda do produto e alinhamento do mesmo. Fabricamos os adesivos com uma sobreposição de 1 cm. No momento da aplicação, um rolo deve sobrepor o outro 1 cm assim dando um encaixe perfeito no seu ambiente. Ideal para sua sala, quarto e sua cozinha. Produzido em adesivo PVC vinílico, auto colante, de fácil manuseio, e pode ser aplicado por você mesmo. QUANTAS UNIDADES DEVO COMPRAR?: - Em paredes com até 3 metros de altura: divida a largura da parede por 0,40. Arredonde o resultado para cima e será a quantidade de rolos necessários. VEJA UM EXEMPLO DE CÁLCULO: Em uma parede com 2,40 metros de largura: 2,40 / 0,40 = 6,00 Arredonde o resultado para cima e será a quantidade de rolos necessários. Para essa parede seria necessário 6 rolos. VANTAGENS: - Aplicação fácil e sem sujeira, pois não precisa de cola. - Não precisa contratar mão de obra profissional para aplicar. - Renove seus ambientes de forma rápida e prática. CARACTERÍSTICAS: - Pode ser limpo com pano úmido e sabão neutro. - Material liso, não possui textura ou relevo. - Antimofo, não possui cheiro e não propaga fogo. - Durabilidade média de 5 anos em ambiente interno. - Produzido em vinil adesivo antirreflexo, fosco, sem brilho, próprio para decoração. - Impressão digital em alta resolução de imagem e cores vivas. - Os rolos se encaixam lateralmente, dando continuidade ao desenho. - Espessura: 0,10mm (mais firme e resistente, facilita o manuseio e aplicação). - Produto de fabricação própria. ONDE POSSO APLICAR: - Pode se aplicar em qualquer superfície lisa, basta apenas que a parede que for receber não seja pintada com tinta magnética ou acetinada e não possua relevos ou algum tipo de porosidade. - Pode ser aplicado também em madeiras, mdf, vidros, metais, gesso, etc. - Não aplicar em superfícies úmidas, porosas ou com relevo. OBSERVAÇÃO: O tom da cor do papel de parede poderá variar em até 15% de acordo com a calibração de cores do seu monitor ou tela. Podem haver diferenças entre as fotos mostradas nos anúncios e o resultado da sua aplicação. Isso acontece porque a iluminação do ambiente da foto pode ser diferente da sua, já que existem diferentes tipos: lâmpada led, incandescente, fluorescente, luz solar direta ou indireta, dia ou noite, etc.', 54.9, 32.9, NULL, 'Home & Living > Decoration > Wallpapers & Wall Stickers', 'https://cf.shopee.com.br/file/5767972edffd5a2846925db633a572df', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322399178%2F3167121009', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4957448628', 'Papel De Parede Azulejo Mármore Branco Rose E Preto', 'TAMANHO DO ROLO: Altura: 3,00 Metros Largura: 50 centímetros ATENÇÃO: Pedidos em datas diferentes ou separados, possuem tons de cor diferentes, compre tudo em uma única vez com a quantidade exata para sua parede. Caso tenha dúvidas sobre quantas unidades comprar, fale com nosso atendente no campo de perguntas, ficaremos felizes em ajudar. Prazo de postagem: 1 dia após a aprovação do pagamento. Os produtos podem apresentar diferença de até 15% nas tonalidades de uma compra para outra. Por isso é importante certificar-se de que a quantidade de rolos é suficiente para concluir o trabalho. Antes de aplicar abra os papéis em uma superfície plana, verifique a emenda do produto e alinhamento do mesmo. Fabricamos os adesivos com uma sobreposição de 1 cm. No momento da aplicação, um rolo deve sobrepor o outro 1 cm assim dando um encaixe perfeito no seu ambiente. Ideal para sua sala, quarto e sua cozinha. Produzido em adesivo PVC vinílico, auto colante, de fácil manuseio, e pode ser aplicado por você mesmo. QUANTAS UNIDADES DEVO COMPRAR?: - Em paredes com até 3,00 metros de altura: divida a largura da parede por 0,50. Arredonde o resultado para cima e será a quantidade de rolos necessários. VEJA UM EXEMPLO DE CÁLCULO: Em uma parede com 2,40 metros de largura: 2,40 / 0,50 = 4,80 Arredonde o resultado para cima e será a quantidade de rolos necessários. Para essa parede seria necessário 5 rolos. VANTAGENS: - Aplicação fácil e sem sujeira, pois não precisa de cola. - Não precisa contratar mão de obra profissional para aplicar. - Renove seus ambientes de forma rápida e prática. CARACTERÍSTICAS: - Pode ser limpo com pano úmido e sabão neutro. - Material liso, não possui textura ou relevo. - Antimofo, não possui cheiro e não propaga fogo. - Durabilidade média de 5 anos em ambiente interno. - Produzido em vinil adesivo antirreflexo, fosco, sem brilho, próprio para decoração. - Impressão digital em alta resolução de imagem e cores vivas. - Os rolos se encaixam lateralmente, dando continuidade ao desenho. - Espessura: 0,10mm (mais firme e resistente, facilita o manuseio e aplicação). - Produto de fabricação própria. ONDE POSSO APLICAR: - Pode se aplicar em qualquer superfície lisa, basta apenas que a parede que for receber não seja pintada com tinta magnética ou acetinada e não possua relevos ou algum tipo de porosidade. - Pode ser aplicado também em madeiras, mdf, vidros, metais, gesso, etc. - Não aplicar em superfícies úmidas, porosas ou com relevo. OBSERVAÇÃO: O tom da cor do papel de parede poderá variar em até 15% de acordo com a calibração de cores do seu monitor ou tela. Podem haver diferenças entre as fotos mostradas nos anúncios e o resultado da sua aplicação. Isso acontece porque a iluminação do ambiente da foto pode ser diferente da sua, já que existem diferentes tipos: lâmpada led, incandescente, fluorescente, luz solar direta ou indireta, dia ou noite, etc.', 54.9, 32.9, NULL, 'Home & Living > Decoration > Wallpapers & Wall Stickers', 'https://cf.shopee.com.br/file/d0d53677e415e8ea372829034a1b7703', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322399178%2F4957448628', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497475422', 'Rotor Distribuidor Gm Caravan 1969 a 1984 - 106565 - 21558', 'Rotor Distribuidor Gm Caravan 1969 a 1984 106565 21558 TODOS COM DISTRIBUIDOR DELCO REMY (IGNIÇÃO PLATINADO) O rotor é um dispositivo do sistema de ignição que tem por finalidade, distribuir as centelhas de alta tensão para cada um dos pólos da tampa do distribuidor. Alguns rotores possuem uma resistência entre seu contato central e sua extremidade. Essa resistência serve para atenuar as interferências eletromagnéticas provocadas pela alta tensão do sistema.', 24.28, 24.28, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rd6v-lui9udeiitmyfb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23497475422', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693116214', 'Mesa de Madeira Adriana com Vidro Nature/Off White - Henn', 'Dimensões: - Altura: 80,00 cm - Largura: 180,00 cm - Profundidade: 90,00 cm - Peso: 67,000 kg Descrição: O(a) Mesa de Madeira Adriana com Vidro Nature/Off White - Henn é produzido em MDF e MDP na escala de brilho Fosco, e possui um grau de dificuldade de montagem: Médio.Seu revestimento/acabamento é: Texturizada e Pintura UV. Infelizmente a Loja não oferece serviço de montagem, deixamos essa informação bem clara em todas as nossas páginas de produto. Onde especificamos que os móveis chegarão desmontados, e que a montagem fica por conta do cliente. Como não oferecemos esse serviço não embutimos o mesmo no preço dos produtos, ou seja, maior economia para você! Todos os nossos móveis também acompanham o manual de montagem, e caso você queira, pode realizar a montagem você mesmo, sempre especificamos os graus de montagem dos produtos. Nos casos de grau baixo e médio, com pouco ou nenhum conhecimento, você mesmo pode efetuar a montagem, e fazer essa economia. Apenas nos graus de montagem alto, recomendamos a contratação de um montador com experiência, visto que são montagens mais complicadas. A montagem é feita com Parafusos, cavilhas e Minifix.. Este móvel é indicado para que seja utilizado no(a) Sala de Jantar, dando um toque especial no cômodo de sua casa. Para que você mantenha seu produto sempre em ótimo estado, recomendamos que use apenas um pano seco ou levemente umedecido, sem o uso de quaisquer produtos abrasivos. A Loja garante aos clientes, 90 dias de garantia nos produtos, porém, recomendamos que entre em contato com o fornecedor/marca do produto, pois o mesmo(a), pode garantir um prazo maior de garantia. Lembrando ainda que: quaisquer objetos decorativos que aparecem nas imagens, não acompanham o produto. Características: - Espessura da Estrutura: "Tampo: MDF 25mm Estrutura: MDP 25mm/15mm/MDP 12mm MDF 15mm" - Possui Gavetas?: Não - Possui Portas?: Não - Possui Vidro?: Sim - Vidro Temperado?: Não - Possui Espelho?: Não - Possui Prateleiras?: Não - Possui Puxadores?: Não - Possui Ripamento?: Não - Linha ou Coleção: Adriana - Montagem Invertida?: Não Pode ser Montado Invertido - É frágil?: Não - Possui Nicho?: Não - Material da Estrutura: MDF e MDP - Escala de Brilho: Fosco - Possui Rodízios?: Não - Possui Pés?: Não - Acompanha: 1 Mesa e Manual de Montagem - Acompanha Manual de Montagem: Sim - Como os Móveis Chegarão na Minha Casa: Desmontado em caixas, acompanhado de todas as peças, ferragens e manuais para montagem. - Grau de Dificuldade da Montagem: Médio - Necessita de Montagem: Sim - Sistema de Montagem: Parafusos, cavilhas e Minifix. - Acompanha Cadeiras: Não - Acompanha Tampo: Sim - Formato da Mesa: Retangular - Material do Tampo: Vidro/MDF - Peso Suportado no Tampo: 40 Kg - Quantidade de Lugares: 6 - Garantia (dias): 90 - Indicação de Uso: Sala de Jantar - Observação: Objetos decorativos que aparecem nas imagens, não acompanham o produto. - Recomendação de Manutenção: Utilizar pano levemente umedecido, seguido de pano seco. Não utilizar quaisquer produtos abrasivos. - Revestimento /Acabamento: Texturizada e Pintura UV', 1373.84, 1275.98, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-7rd4y-lx16re831xlyae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F580791382%2F22693116214', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
