INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17691744696', 'Rolo com Panos Lava E Seca 50 Peças - Simplo', '"Conheça o Rolo de panos lava e seca 50 peças da Simplo. Práticos, reutilizáveis e com alto poder de absorção, os panos são ideais para limpar e secar todas as superfícies lisas. Possuem toque de papel, secam rápido, não soltam fiapos, evitam germes e bactérias e não retém mau cheiro! São 70% Celulose e 30% PP. Antes de guardar, lave em água corrente e aperte para secar. Leve funcionalidade e modernidade para sua casa! Basta molhar o pano e esfregar na área desejada. Depois de usar, é só enxaguar em água corrente e deixar secar. Ideal para limpar e secar todas as superfícies lisas. - Panos picotados a cada 21 cm - Vai no porto rolos da cozinha - Reutilizável - Não retém mau cheiro - Evita germes e bactérias - Não solta fiapos - Seca rápido - Alto poder de absorção. Antes de guardar, lave em água corrente e aperte para secar."', 75.9, 51.9, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/sg-11134201-82614-mlfeaubmvy1006', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F17691744696', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
