INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093514065', 'Colflex Cúrcuma 30 comprimidos', 'Colflex Curcuma possui colágeno tipo II não desnaturado associado ao extrato de rizoma de curcuma longa e vitamina C. O colágeno tipo II não desnaturado auxilia na manutenção da função articular. A vitamina C é um antioxidante que auxilia na proteção dos danos causados pelos radicais livres. Este produto não deve ser consumido por gestantes, lactantes, crianças, pessoas com doenças hepáticas, biliares ou com úlceras gástricas. Pessoas com enfermidades e/ou sob o uso de medicamentos, consulte seu médico.', 324.5, 199.9, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-82618-mm6uwvwkxqf73b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1392693402%2F23093514065', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
