INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599070940', 'Kit 3 Shampoo Dove Baby Hidratação Glicerinada 400ml', 'Shampoo Baby Dove Hidratação Glicerinada 400ml • Hipoalergênico. • pH neutro para a pele do recém-nascido. • Sem lágrimas, corantes artificiais, parabenos, ftalatos, sulfatos. • Shampoo de glicerina. • Com nutrientes naturalmente encontrados na pele do bebê. • Ajuda a manter os cabelos dos bebês macios e visivelmente saudáveis. Nosso Shampoo de Glicerina Baby Dove é hipoalergênico e vai além da suavidade ao ajudar a manter a hidratação e os nutrientes essenciais ao couro cabeludo desde o primeiro banho, mantendo os cabelos do bebê macios e visivelmente saudáveis. Comprovadamente minimiza os riscos de alergia com um perfume desenvolvido para a delicada pele do bebê. Criado com pH neutro e nutrientes naturalmente encontrados na pele do bebê, esse shampoo, cuida do delicado couro cabeludo do seu bebê e deixa com sensação e aparência saudáveis desde seu primeiro uso, por isso, além de limpar delicadamente, ajuda a hidratar o couro cabeludo e os fios de cabelos, mantendo macios e bem cuidados. Aproveite toda hora do banho com essa cuidadosa fórmula hipoalergênica, suave e sem lágrimas. Com um perfume delicado esse shampoo para bebês deixa os cabelos do seu pequeno saudáveis, esse shampoo para bebês ajuda a repor a hidratação e nutrientes essenciais. Após lavar os cabelos do seu bebê, experimente aplicar o Condicionador Baby Dove após o shampoo, para ajudar a manter os fios dos cabelos macios e fáceis de pentear. Testado por oftalmologista, dermatologista e pediatra. Modo de uso: Aplique uma pequena quantidade de produto nas mãos, massageie o couro cabeludo e o cabelo úmido e enxágue.', 72.57, 72.57, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/sg-11134201-823rp-mok479r7xqmn92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F21599070940', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
