INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22091534867', 'Carrinho Unicórnio Mágico - Monte Líbano', 'Carrinho Unicórnio Mágico - Monte LíbanoDeixe a diversão tomar conta com o Carrinho Unicórnio Mágico da Monte Líbano! O Carrinho Unicórnio Mágico da Monte Líbano é o brinquedo perfeito para proporcionar uma aventura mágica para as crianças a partir de 3 anos. Com um design encantador de unicórnio, ele é ideal para estimular a imaginação e criatividade dos pequenos de forma lúdica e divertida. Diferenciais:Design encantador de unicórnio; Indicado para crianças a partir de 3 anos; Selo Inmetro de segurança; Produto de qualidade da marca Monte Líbano. Mais sobre o Produto:O Carrinho Unicórnio Mágico é um brinquedo que estimula a coordenação motora e o desenvolvimento cognitivo das crianças, além de promover horas de diversão e entretenimento. Dicas de Uso:Deixe a imaginação fluir e incentive a criança a criar histórias e aventuras mágicas com seu Carrinho Unicórnio. Ideal para brincadeiras individuais ou em grupo, este carrinho vai conquistar os corações das crianças e proporcionar momentos de muita alegria. Ficha Técnica:Marca: Monte Líbano Idade Recomendada: A partir de 3 anos Selo Inmetro: 004081/2021 Categoria: Carrinhos Material: Plástico resistente Agora, garanta o Carrinho Unicórnio Mágico da Monte Líbano e proporcione diversão e magia para a criançada!', 100.04, 100.04, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7qve3-li1qgbedbhjnb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F22091534867', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
