INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3773328538', 'Par Palheta Limpador Parabrisa Renault Megane e Scenic', 'ACOMPANHA: 02 PALHETAS DIANTEIRAS APLICAÇÃO: RENAULT MEGANE e SCENIC ANO 2000 ATÉ 2011 INFORMAÇÕES TÉCNICAS MEDIDAS DIANTEIRAS: 24 POLEGADAS - 600 MM - ENCAIXE GANCHO 16 POLEGADAS - 400 MM - ENCAIXE GANCHO Essencial para os dias de chuva, a palheta do seu automóvel deve estar em boas condições para limpar perfeitamente seu para-brisa, ajudando a ter uma visibilidade melhor e assim evitando acidentes. Obs: É recomendável a troca de palhetas do seu automóvel a cada 6 meses. - MELHORA A LIMPEZA E PROPORCIONA UMA MELHOR VISIBILIDADE EM DIAS CHUVOSOS - FEITA DE SILICONE NÃO ENFERRUJA E NÃO RISCA SEU VIDRO - SÃO FLEXÍVEIS - NÃO CAUSA BARULHO E TEM MAIOR DURABILIDADE QUE AS DA CONCORRÊNCIA - FÁCIL APLICAÇÃO/INSTALAÇÃO - MELHOR QUALIDADE - SATISFAÇÃO GARANTIDA', 34.9, 23.99, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0okupfx6ge919', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318894435%2F3773328538', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255400944', 'Suporte Porta Retrato Coração retro para foto Polaroid Cartão Presente decoração', '( ATENÇÃO NÃO ACOMPANHA FOTO, ANUNCIO É REFERENTE AO SUPORTE DE FOTOS ) Deixe suas memórias ainda mais especiais com este suporte em formato de coração retro pixel ❤️ - Ideal para : FOTOS CARTÕES MENUS LEMBRANÇAS ANIVERSARIO ESCRITORIO CASAMENTO CHÁ DE BEBÊ Compatível com fotos no estilo Polaroid, Instax e similares, este porta-retrato é perfeito para quem busca charme e funcionalidade em eventos, festas ou na decoração do dia a dia. Use em casamentos, aniversários, chás de bebê, formaturas, ou simplesmente para decorar sua casa, escritório ou ambiente comercial. A base tem design moderno, discreto e combina com qualquer estilo de decoração. Cada peça é feita com material biodegradável proveniente de fontes renováveis, sendo uma escolha sustentável e consciente. Medidas: 1,2 cm de largura × 4 cm de comprimento × 3,5 cm de altura Material:PLASTICO Estilo moderno e discreto para compor sua decoração Cor VERMELHA ENVIO RAPIDO !', 19.99, 12.99, NULL, 'Home & Living > Decoration > Photo Frames & Wall Decoration', 'https://cf.shopee.com.br/file/br-11134207-81zth-mkvdbnt8a51cac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318894435%2F58255400944', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
