INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14449116796', 'Protetor solar para-brisa quebra sol luxcar dobrável', 'Somos a Go! Mec Auto Peças, estamos no ramo de autopeças para veículos nacionais e importados há quase duas décadas, nosso estoque conta com uma variedade de 45000 itens. Todos os nossos produtos são novos, originais e com garantia._x000D_ _x000D_ Para-Sol_x000D_ 1 unidade_x000D_ O Para-Sol Luxcar é confeccionado com materiais de alta qualidade, foi desenvolvido para proteger o interior do seu carro, bloqueando até 90% dos raios solares. Possui superfície refletiva e tamanho universal, adaptável na maioria dos carros nacionais e importados._x000D_ _x000D_ Vantagens:_x000D_ • Produto antitérmico_x000D_ • Bloqueia os raios solares em até 90%._x000D_ • Protege o interior do veículo._x000D_ • Fácil de guardar, dobrável._x000D_ _x000D_ Modo de usar:_x000D_ 1. Desenrole os elásticos, desdobre e localize as ventosas que estão dentro das dobras do para-sol._x000D_ 2. Encaixe a base das ventosas aos furos nos cantos do para-sol._x000D_ 3. Fixe as ventosas na parte superior do seu para-brisa, de forma que o seu para-sol fique bem esticado._x000D_ _x000D_ Validade Indeterminada', 39.0, 39.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Sun Shade', 'https://cf.shopee.com.br/file/cb2885e20a38703e369ece46d55ac7ba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549478150%2F14449116796', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
