INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499326194', 'Armário Roupeiro Aço 16 Portas Guarda Volume Trinco', 'Armário Roupeiro Aço 16 Portas Academia Guarda Volume Trinco Roupeiro de Aço EA716 O Armário Roupeiro de Aço 16 Portas Vestiário Academia Guarda-Volumes com trinco para cadeados é perfeito para alojamentos, escritórios, almoxarifados, laboratórios, hospitais, farmácias, depósitos, academias, supermercados, vestiários, e diversos outros ambientes. O Armário Roupeiro De Aço 16 Portas Vestiário Academia Guarda-Volumes foi desenvolvido com aço de alta qualidade, garantindo maior robustez máxima de resistência à estrutura da peça, tornando seu tempo de vida útil mais elevado. Sua pintura eletrostática em tinta epóxi, proporciona ainda mais proteção a ela. Perfeita para a organização do seu ambiente. Ele é composto por 16 portas que cabem todos os modelos de capacetes e outros pertences. Super resistente, suporta até 30Kg bem distribuídos por compartimento. Possui pés niveladores para um perfeito acabamento e evitando assim riscos no piso. Porta com trinco para cadeado que permanece fechada mesmo que esteja sem o cadeado no momento - diferente do pitão tradicional que precisa ser amarrado para evitar que fique batendo - perfeito acabamento e praticidade Características do Produto - Quantidade de portas: 16 - Chapa das prateleiras: 26 (0,45mm) - Dimensões (ALP/cm): 198 x 140 x 40 - Pintura: Eletrostática / Epóxi - Peso suportado: 30Kg por compartimento Conteúdo da Embalagem - 16 Portas - 12 Prateleiras - 02 Bases - 02 Tetos - 04 Fundos - 04 Laterais - 04 Travas - 02 Divisórias - 08 Pés niveladores + sapatas - 02 Kit de acessórios completo - 02 Manuais de Montagem Garantias - Garantia de 03 meses de fábrica contra defeitos de fabricação - Garantia extra de +03 meses da loja contra eventuais defeitos de fabricação Importante: Este produto é entregue desmontado, junto ao manual de instruções e todos os acessórios necessários para seu perfeito encaixe e uso. Indicamos que você contrate um profissional especializado para sua montagem; Certifique-se de que todas as características do produto atendem sua necessidade antes de efetuar a compra, desta forma garantimos que você irá adquirir um excelente artigo que possa usufruir; Lembre-se de que as imagens do anúncio são ilustrativas, podendo suas cores ter variações em razão do monitor ou da luz. O Armário Roupeiro De Aço 16 Portas Vestiário Academia é fabricado pela Elite Aço, indústria de móveis de aço e tubular presente no mercado há mais de duas décadas, oferecendo produtos inovadores de alta qualidade e estilo para atender as necessidades de seus clientes.', 1323.2, 1323.2, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-82617-mk9yhwmv4hdw7b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23499326194', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
