INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993251499', 'Zuru Smashers Horror House Verde C/ Acessórios F01736 - Fun', 'DESCRIÇÃO DO PRODUTO: Smashers Mega Horror House tem mais de 35 surpresas dentro, você é corajoso o suficiente para encontrar todas elas? Aperte olho do caixão para ouvir luzes e sons assustadores! Cave e disseque, pegue sua pá e coragem é hora de desenterrar e dissecar seus monstros para trazê-los à vida! Descubra as peças do Smashers Monster em areia e slime para uma brincadeira tátil divertida! CARACTERÍSTICAS TÉCNICAS: Conteúdo da Embalagem: 01 Caixão Desmontável / 01 Monstro Desmontável / 01 Capa para Tumbas / 01 Osso da Mão / 01 Pá / 01 Pacote de Areia / 01 Pacote de Slime / 01 Múmia / 03 Pequenos Monstros / 02 Acessórios Surpresa / 01 Card de Colecionador / 01 Guia com Instruções. Dimensões Aproximadas do Produto: 27cm x 15cm (Altura x Largura x Comprimento/Profundidade) Dimensões Aproximadas da Embalagem: 10cm x 17cm x 32cm (Altura x Largura x Comprimento/Profundidade) Material/Composição: Plástico / Slime / Areias Magicas Idade Mínima Recomendada: A partir de Participantes: A partir de 1 pessoa Alimentação: Não se aplica Marca: Fun Divirta-se Referência: F0173-6A Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. Produto lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 146.65, 129.49, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7rdwh-lzovw1tmome2d7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F22993251499', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202897770', 'Ventilador de Coluna Mondial 6 Pás Super Turbo 40cm VSP-40C 140W', 'Apresentamos o ventilador de coluna Super Power VSP-40C, com um diâmetro de 40 cm e hélice de 6 pás, proporcionando um ambiente mais fresco e confortável. Sua coluna ajustável, com altura variando entre 1,19 e 1,50 metros, permite regular a altura do vento conforme sua necessidade. Além disso, o sistema de ventilação da Mondial opera com baixo nível de ruído, garantindo a tranquilidade ideal para uma noite de sono reparadora. Características: 3 Velocidades 6 Pás 40cm de diâmetro Regulagem de 1,19 a 1,50 metros Sistema oscilante contínuo Inclinação vertical regulável Grade frontal removível Alça de transporte Porta fio Dimensões: Altura: 143 cm Largura: 47,5 cm Profundidade: 47,5 cm Peso: 5,30 kg Garantia do fornecedor de 3 meses', 249.9, 160.2, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-8262e-mj7cubjt7l6r82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F58202897770', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
