INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598516190', 'Organizador Braçadeira Cabo Ugreen Pc e Instrumentos 2 Metro', 'Organizador Braçadeira de Cabo Ugreen para Pc e Instrumentos Forte Adesão e Durabilidade 2 Metros de Comprimento / No Brasil O organizador de cabos Ugreen 40354 foi desenvolvido para apresentar forte adesão, sendo que é ideal para organização de diferentes tipos de cabos; Ou seja, o organizador de fios da Ugreen é perfeito para manter todos os cabos do seu escritório no lugar certo e com firmeza; Evite com que os fios dêem nós ou embaracem, isso sem falar que esta braçadeira foi criada para, caso haja necessidade, ser cortado com facilidade; Marca: Ugreen cor do produto: Preto Referência do modelo: 40354 Comprimento do produto: 2 metros Dimensões: 2 x 9,5 x 15 cm Peso: 0,024 Itens inclusos 1x Organizador Braçadeira de Cabos Garantia: 90 dias', 35.0, 35.0, NULL, 'Computers & Accessories > Peripherals & Accessories > USB Hubs & Card Readers', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9yrx1z7mbll1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163157664%2F23598516190', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16483284875', 'Motor Partida Arranque Honda Cg Titan Fan Xlr Nxr Bros 125 150 Cbx Nx Xr 150 200 Original Magnetron', 'PREÇO REFERENTE A UMA UNIDADE DE MOTOR DE ARRANQUE CÓDIGO: 90205520 MARCA: MAGNETRON ______________________________________________ APLICAÇÕES: • HONDA XR 200 R | 1994 ATE 2002 CG 125 TITAN ES | 2000 ATE 2004 CG 125 TITAN KSE | 2002 ATE 2004 NXR 125 BROS ESN | 2003 ATE 2005 NX 150 | 1989 ATE 1992 NX 200 | 1993 ATE 2001 XLR 125 | 1996 ATE 2002 XLR 125 ES | 2000 ATE 2002 NXR 150 BROS ESD | 2003 ATE 2005 CBX 150 AERO | 1989 ATE 1992 CBX 200 STRADA | 1994 ATE 2002 _____________________________________________ OBSERVAÇÕES IMPORTANTES: * Produto com garantia de 3 meses. * Produto novo na caixa. * Produto em estoque e com envio em imediato. * Recomendamos que os produtos sejam instalados por profissionais especializados FUNÇÃO: O motor de partida tem a função de dar início à partida da motocicleta, substituindo o pedal de partida. ATENÇÃO SE... O motor de partida não aciona ou gira muito devagar; • Você ouve um estalo quando o motor de partida funciona; • Aparecem ruídos estranhos ao ligar o motor de partida; • O motor de partida aciona, mas o motor a combustão não. Se você notar que existe alguns dos problemas listados acima no sistema de partida, a primeira dica é não sair trocando peças antes de consultar um especialista, durante a manutenção. E escolher peças de qualidade. Assim o serviço será bem executado você poderá rodar tranquilo por muito tempo.', 234.0, 180.14, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lwfsqh0dmvg5d1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F843202413%2F16483284875', NULL, NULL, '2026-07-28T02:11:31.708458+