INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997502416', 'Pneu Moto Michelin Aro 17 Sirac 110/90-17 60P TT - Traseiro', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. O pneu Michelin Sirac é ideal para utilização tanto em asfalto, quanto no off-road (70% estrada/30% off road). Oferece ótimo desempenho, com segurança em curvas e frenagens, em diversos tipos de terrenos. Possui carcaça reforçada, mais resistente a choques, deformações e furos, tornando-se um pneu durável e altamente confiável. Aplicação: Honda NXR 150 Bros, Honda NXR 160 Bros, Falcon, XT660, XT600. Sobre a marca Michelin A marca Michelin foi fundada em 1889 em Clermont-Ferrand, França e com o passar dos anos tornou-se uma referência em pneus. Produz atualmente pneus para carros, motos, suvs, caminhonetes e muito mais. Os pneus Michelin se consagraram no mercado graças à excelente aderência, durabilidade e conforto. Hoje são utilizados como pneu original de fábrica por diversas montadoras de automóveis, desde carros compactos até superesportivos de alta potência, que precisam de toda a tecnologia dos pneus Michelin para obter os melhores resultados nas pistas.', 575.88, 529.81, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd62-lvd6gi5l4ve0b6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F22997502416', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093572129', 'Jogo 4 Pneus Continental Aro 15 ContiPowerContact 185/65R15 92T XL', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores.Desenvolvido para equipar carros compactos e médios, o pneu Continental ContiPowerContact oferece qualidade de sobra para o uso diário, seja urbano ou rodoviário, com muita segurança e conforto. Possui banda de rodagem assimétrica e composto da 4ª geração de sílica, que em conjunto fazem com que o pneu tenha ampla área de contato com a pista, porém com desgaste reduzido, devido à baixa resistência ao rolamento, o que também ajuda no consumo de combustível, resultando em menor emissão de CO2 e aumento da vida útil do pneu. Sobre a marca Continental A marca Continental foi fundada em Hanover, na Alemanha em 1871. Os pneus Continental são referência mundial em desempenho e qualidade, equipando os mais modernos e sofisticados carros. São usados como pneu original de fábrica em marcas como BMW, Mercedes e Porsche, tanto com pneus comuns quanto em pneus RunFlat. Seja em pneus para carros de passeio, carros esportivos, utilitários, a Continental oferece inovações e a garantia de segurança total nos trajetos realizados.', 2380.45, 2190.02, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rfi5-m32b9f701vk684', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F22093572129', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
