INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393171377', 'PERFUME MASCULINO PIACENZA PROFUMO - PRIMACIAL PERFUME AROMÁTICO', 'Perfume Piacenza Profumo Masculino Perfume Masculino Aromático Aquático | Intensidade e Sofisticação Uma fragrância masculina elegante, intensa e extremamente sofisticada. O Piacenza Profumo combina a frescura das notas aquáticas com um toque aromático refinado e um fundo profundo e marcante, criando um perfume moderno e irresistível. Inspirado em uma das fragrâncias mais icônicas da perfumaria masculina, ele transmite poder, maturidade e confiança, sendo perfeito para homens que querem se destacar com presença e elegância em qualquer ocasião. Pirâmide Olfativa: Topo: Notas aquáticas, bergamota e acordes frescos Coração: Notas aromáticas e especiarias suaves Fundo: Incenso, patchouli e notas amadeiradas profundas Quando Usar: 🌤️ Dia: Muito bom – fresco, porém sofisticado 🌙 Noite: Excelente – intenso e elegante 🌊 Clima: Ideal para temperaturas amenas e noites 📦 Detalhes do Produto ✔ Perfume masculino aromático aquático ✔ Fragrância sofisticada e marcante ✔ Fixação moderada a alta ✔ Excelente para ocasiões especiais e uso noturno ✔ Versátil para quem busca elegância no dia a dia 💡 Dica de uso: Aplique nos pontos de pulsação como pescoço e pulsos para melhor projeção. Para maior intensidade, utilize também na roupa ou reaplique ao longo do dia.', 89.0, 76.0, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lz7yn2u3nxgle5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295467768%2F22393171377', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399305319', 'PERFUME FEMININO ANTIFRAGIL POUR FEMME 50ML - PRIMACIAL PERFUME FLORAL', 'Perfume Antifrágil Pour Femme 50ml Perfume Feminino Floral Moderno | Delicadeza, Elegância e Versatilidade Uma fragrância feminina leve, elegante e extremamente versátil. O Antifrágil Pour Femme combina notas florais delicadas com um toque suave adocicado e um fundo confortável, criando um aroma moderno, limpo e envolvente. Pensado para a mulher contemporânea, ele transmite feminilidade, leveza e sofisticação na medida certa. Um perfume fácil de agradar, perfeito para ser assinatura e acompanhar todos os momentos do dia. Pirâmide Olfativa: Topo: Notas frescas e frutadas suaves Coração: Flores delicadas e femininas Fundo: Almíscar, âmbar e notas amadeiradas leves Quando Usar: 🌤️ Dia: Excelente – leve, fresco e elegante 🌙 Noite: Muito bom – suave e confortável 🌸 Clima: Ideal para dias amenos e quentes 📦 Detalhes do Produto ✔ Conteúdo: 50ml ✔ Perfume feminino floral moderno ✔ Fragrância leve, versátil e sofisticada ✔ Fixação moderada ✔ Ideal para uso diário e trabalho ✔ Ótima opção como perfume assinatura 💡 Dica de uso: Aplique após o banho em áreas como pescoço e pulsos. Reaplique ao longo do dia para manter a fragrância sempre presente de forma leve e agradável.', 149.0, 139.0, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m86ddzpxglwx6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295467768%2F18399305319', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194978733', 'Deo Parfum Natura Una Senses 75ml', 'Perfumação com a força dos elementos da natureza. Natura Una Senses te convida a sentir na pele a potência do encontro entre terra e fogo. Esse Deo Parfum possui fragrância adocicada intensa e é perfeito para ocasiões especiais. Fragrância:Una Senses combina a potência da tuberosa com tons quentes da terracota. A fragrância ganha mais força com as notas sensuais e amadeiradas de cashmeran, benjoin e extrato de vanila. O toque final vem do cumaru, ingrediente da biodiversidade brasileira COMO USAR: Aplique nos pontos de maior circulação sanguínea, como pulsos, pescoço e atrás das orelhas, para uma perfumação duradoura e intensa. Use após o banho ou sempre que desejar renovar o aroma ao longo do dia.', 319.9, 319.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-820lv-mnk662zbqqkgc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1785523344%2F22194978733', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199475372', 'Desodorante Colônia Sr N Masculino 100 ml', 'Sr N Natura: um clássico atemporalO Sr N Natura é uma fragrância clássica produzida desde 1979 para o homem que valoriza o tempo. Para isso, conta com uma combinação atemporal das madeiras de patchouli e vetiver em contraste com o frescor cítrico do limão e lavanda.Aromático amadeiradoUma fragrância que combina notas frescas e aromáticas com a profundidade das madeiras, criando uma experiência olfativa clássica e atemporal.GOLTA OLFATIVA:Notas de topo: limão, bergamota, lima, grapefruit, gálbano, folhas de cassis.Notas de corpo: flor de laranjeira, cardamomo, lavanda, artemísia.Notas de fundo: vetiver, madeiras transparentes, musk, baunilha, óleo essencial de patchouli, cedro.Ocasião: dia-a-diaDICAS DE USO:Todo mundo tem um jeito único de se perfumar, mas se você deseja aproveitar todo o potencial da fragrância, aplique em áreas como o punho, pescoço e atrás das orelhas.', 175.05, 175.05, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-820o8-mnk66fehb56s14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1785523344%2F22199475372', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211445430', 'Batom Líquido Cristal Natura Una 8ml', 'Una sua luz própria com o brilho mais fascinante! O novo batom de Una traz o inédito efeito cristal, produzido por uma exclusiva composição de pigmentos perolados multidimensionais que irradiam um brilho único e sofisticado. Pode ser usado como batom, sombra ou iluminador! O melhor do brilho multidimensional e da hidratação em seus lábios. • fórmula com pérolas radiantes de alta pigmentação • pigmentos de efeitos multidimensionais: brilho intenso e tonalidades marcantes para o acabamento cristal de alta performance. • Ativos da biodiversidade brasileira: possui manteiga de cacau, que apresenta um poder surpreendente de hidratação. • Tecnologia de partículas: pigmentos de efeitos multidimensionais de alta performance, que trazem o brilho intenso e tonalidades marcantes para o novo acabamento cristal CARACTERISTICAS: dermatologicamente testado produto vegano DICAS DE USO: Aplique o batom sobre os lábios, espere secar.', 64.9, 49.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-823pq-mopv2zgj5tlb4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1785523344%2F58211445430', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200624650', 'Pista de Carrinho Com Looping Radical em 360 Luz Divertido Infantil - Castela', 'Pista de Carrinho com Looping - Castela Prepare-se para uma experiência emocionante com a Pista de Carrinho com Looping da Castela! Ideal para crianças que adoram ação, velocidade e desafios, essa pista inovadora transforma qualquer brincadeira em uma aventura eletrizante, mesmo no escuro. Características: Looping radical: Design dinâmico para emocionantes manobras de alta velocidade. Pista flexível e personalizável: Permite criar diferentes percursos e desafios. Inclui carrinho: Pronto para começar a brincadeira imediatamente. Fácil de montar: Ideal para crianças explorarem a criatividade enquanto montam a pista. Material seguro e durável: Fabricado com plástico de alta qualidade para horas de diversão. CARACTERÍSTICAS TÉCNICAS: Material/Composição: Plástico Idade Mínima Recomendada: A partir de 3 anos Participantes: A partir de 1 pessoa Marca: Castela Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. Produto lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 177.99, 156.99, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-821eo-mh1xypzxgkcrea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F58200624650', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
