INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297969026', 'Kit 2 Displays de Mini Chocolate Linea Sabor Cookies’n Cream e Ao Leite Zero Lactose 15 unidades de 13g', 'Linea Chocolate é sem adição de açúcares. Adoçado com sucralose e maltitol e com a manteiga de cacau como o 1º ingrediente, resulta em um chocolate macio e cremoso. Sabor indescritível que derrete na boca! 1 Kit Composto por: - 1 display de Mini Chocolate Linea Cookies''n Cream 15 Unidades de 13g cada - 1 display de Mini Chocolate Linea Ao Leite Zero Lactose 15 Unidades de 13g cada INGREDIENTES COOKIES''N CREAM manteiga de cacau, leite em pó integral, gotas de cookies sem adição de açúcares sabor chocolate, soro de leite desmineralizado, gordura vegetal, fibra de milho solúvel, colágeno, edulcorantes: maltitol e sucralose, umectante: polidextrose, emulsificantes: lecitina de soja e poliglicerol polirricinoleato e aromatizante. ALÉRGICOS: CONTÉM DERIVADOS DE LEITE, SOJA E TRIGO. PODE CONTER: CENTEIO, CEVADA, AVEIA, AMENDOIM, AMÊNDOA, AVELÃS, CASTANHA-DE-CAJU, CASTANHA-DO-PARÁ, MACADÂMIAS, NOZES, PISTACHES, CASTANHAS E GERGELIM. CONTÉM LACTOSE. CONTÉM GLÚTEN. INGREDIENTES CHOCOLATE AO LEITE ZERO LACTOSE manteiga de cacau, leite em pó integral zero lactose, massa de cacau, edulcorante maltitol, emulsificantes: lecitina de soja e poliglicerol polirricinoleato e aromatizante. ALÉRGICOS: CONTÉM DERIVADOS DE LEITE E SOJA. NÃO CONTÉM GLÚTEN', 181.18, 144.94, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-7rdwy-m1ehrchyttp39a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1365822827%2F23297969026', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493678118', 'Boneco Colecionável 6,5cm Sonic Prime - Dr. Don''t', 'Prepare-se para uma aventura interdimensional com as Bonecos colecionáveis de 6,5 cm da série Sonic Prime da Netflix! Junte-se ao Sonic e seus amigos em uma jornada emocionante através de dimensões paralelas para salvar o universo! Cada Boneco apresenta detalhes incríveis e cores vibrantes que capturam toda a energia dos personagens favoritos da série. E o melhor? São 10 personagens incríveis para conhecer! Desde o Sonic até seus amigos e vilões mais icônicos, a diversão é garantida. Traga a magia da série para sua coleção de brinquedos hoje mesmo e mergulhe em aventuras sem fim com Sonic Prime!', 59.99, 59.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7rbnb-m5n12wjzzkif8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F23493678118', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12682732059', 'Veiculo Cold Road Frozen Rc 3 Func - Roxo', 'Veiculo de rádio controle da Frozen com 3 funções de comando. Utiliza 2 pilhas AA no veículo e 2 pilhas AA no controle. Pilhas AA não inclusas.', 98.99, 79.99, NULL, 'Hobbies & Collections > Toys & Games > Remote Control Toys & Accessories', 'https://cf.shopee.com.br/file/f882a868b81e37368ca2aec538d5a9fa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F12682732059', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48761393202', 'Kit Completo de Cuidados LAIKOU Sakura – Hidratação Clareadora & Proteção UV para Rosto e Lábios', '✅ Sakura SerumSérum leve e de rápida absorção que ilumina a pele opaca, aumenta o viço e mantém a tez fresca e radiante o dia todo. ✅ Protetor Solar Sakura FPS50Fórmula leve e não oleosa com proteção FPS 50 PA+++ que protege a pele dos raios UV prejudiciais, evitando danos solares sem entupir os poros nem deixar resíduos brancos. ✅ Creme para Olhos SakuraCreme para os olhos com aplicador roll-on que massageia suavemente a área sob os olhos, reduz a aparência de cansaço e mantém a pele hidratada e iluminada. ✅ Máscara de Lama SakuraMáscara purificante de lama que desobstrui os poros, remove impurezas e controla o excesso de oleosidade, deixando a pele limpa, suave e renovada. ✅ Creme Essência SakuraCreme rico, porém leve, que proporciona hidratação prolongada, fortalece a barreira da pele e mantém a pele macia e nutrida. ✅ Bálsamo Labial SakuraBálsamo labial nutritivo que acalma lábios secos e rachados, mantendo a hidratação e deixando os lábios macios, com uma delicada fragrância de Sakura. ✅ Sabonete de Limpeza SakuraSabonete de limpeza suave com infusão de Sakura que cria uma espuma delicada para remover sujeira e impurezas do dia a dia. Deixa a pele fresca, limpa e delicadamente perfumada, sem ressecar. ✨ Bônus: Acessórios de Beleza & Sacola de Presente: Faixa de cabeça rosa fofa para manter o cabelo afastado durante a rotina Sacola de presente rosa linda, perfeita para presentear ou guardar 💡 Formulado com extrato suave de Sakura e ingredientes nutritivos, este kit é indicado para a maioria dos tipos de pele. Simplifica sua rotina diária enquanto proporciona hidratação visível, iluminação e proteção. 🎁 Este adorável kit Sakura é um presente atencioso para aniversários, datas comemorativas ou simplesmente para mostrar que você se importa. Também é um mimo maravilhoso para você adicionar um toque de luxo à sua rotina de cuidados com a pele.', 139.1, 69.85, NULL, 'Beauty > Beauty Sets & Packages', 'https://cf.shopee.com.br/file/sg-11134201-823rk-mp7ygve0whe696', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F48761393202', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793005838', 'Pneu Continental Aro 13 ContiEcoContact 3 165/70R13 79T', 'Marca: CONTINENTAL Modelo: CONTIECOCONTACT 3 Medida: 165/70R13 Largura: 165 Perfil: 70 Tamanho de Aro: 13 Índice de peso: 79 - 437 kg Índice de velocidade: T - 190 km/h Tipo de Veiculo: CARRO Tipo de terreno: HT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: Assimétrico UTGQ: 240AA Adesão à àgua: C Eficiência energética: F Ruído externo: 71 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores.O pneu Continental ContiEcoContact 3 é ideal para equipar carros compactos e oferecer excelente durabilidade, aderência e estabilidade. Sua banda de rodagem é assimétrica e a área externa garante melhor estabilidade, enquanto a interna faz com que a água seja eliminada, permitindo a realização de frenagens em curtos espaços, tanto em pista seca quanto em pista molhada. É um pneu durável e com vida útil elevada, aumentando assim, o tempo entre as trocas de pneus, o que representa economia. Sobre a marca Continental A marca Continental foi fundada em Hanover, na Alemanha em 1871. Os pneus Continental são referência mundial em desempenho e qualidade, equipando os mais modernos e sofisticados carros. São usados como pneu original de fábrica em marcas como BMW, Mercedes e Porsche, tanto com pneus comuns quanto em pneus RunFlat. Seja em pneus para carros de passeio, carros esportivos, utilitários, a Continental oferece inovações e a garantia de segurança total nos trajetos realizados.', 466.25, 428.95, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdvz-lxl8xui7w8uiaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23793005838', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29691402720', 'Boneco Funko Pop! & Buddy Os Simpsons - Krusty e Sr. Tenny', 'Leve para sua coleção a diversão e o humor de Springfield com o Boneco Funko Pop! Krusty e Sr. Tenny! Esta dupla icônica traz Krusty, o palhaço favorito da TV, acompanhado de seu fiel assistente, Sr. Tenny, em figuras detalhadas e cheias de personalidade. Com aproximadamente 12 centímetros (Krusty) e 4 centímetros (Sr. Tenny) de altura, esse conjunto é perfeito para fãs da série e colecionadores que querem adicionar um toque especial e divertido da família mais amada da televisão à sua prateleira. Não deixe essa dupla clássica fora da sua coleção de The Simpsons!', 149.99, 149.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-824jf-mehnpgcoe03lbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F29691402720', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297518096', 'Pneu Barum by Continental Aro 17 Bravuris 4X4 265/65R17 112T', 'Marca: BARUM Modelo: BRAVURIS 4X4 Medida: 265/65R17 Largura: 265 Perfil: 65 Tamanho de Aro: 17 Índice de peso: 112 - 1120 kg, 112 Índice de velocidade: T - 190 km/h, T Tipo de Veiculo: SUV Tipo de terreno: HT RunFlat: N/A Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: Simétrico UTGQ: N/A Adesão à àgua: C Eficiência energética: E Ruído externo: 72 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Pneu ideal para quem utiliza as vias asfaltadas durante a semana e aos finais de semana se aventura a pegar estradas de terra à bordo de um SUV, o Bravuris 4X4 oferece curta distância de frenagem em piso seco e molhado. A sua grande quantidade de ranhuras abertas na banda de rodagem facilita a expulsão da água e evita aquaplanagem, garantindo total segurança aos passageiros. Sobre a marca Barum A marca Barum nascida na Europa a partir da união das marcas Checoslováquia Bata, Rubena e Mitas, a Barum iniciou sua produção em 1966, em Otrokovice, na República Checa. Em 1993, a marca passa a fazer parte do Grupo Continental e, em 2014, se torna conhecida mundialmente. Qualidade aliada à custo-benefício é a principal característica dos produtos da Barum.', 888.44, 817.37, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdvg-lxlj87i8nwbqad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F22297518096', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497893183', 'Chocolate Culinário Ao Leite Linea 250g', 'Linea Chocolate Culinário Ao Leite é fácil de derreter, ideal para raspas, recheios e coberturas. Com muito sabor, sem adição de açúcares, é adoçado com sucralose e maltitol. Baixo em sódio, não contém glúten. O chocolate para quem gosta de preparar suas receitas com facilidade! INGREDIENTES manteiga de cacau, maltodextrina, leite em pó integral, massa de cacau, gordura vegetal, soro de leite desmineralizado, edulcorantes: maltitol e sucralose, emulsificantes: lecitina de soja e poliglicerol polirricinoleato e aromatizante. ALÉRGICOS: CONTÉM DERIVADOS DE LEITE E SOJA. CONTÉM LACTOSE. NÃO CONTÉM GLÚTEN.', 64.79, 61.55, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-7rdyj-m0uy6ek9311g66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1365822827%2F23497893183', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41700892991', 'Boneco Funko Pop! DC Comics Superman: Legacy - Louis Lane', 'A repórter mais famosa do Planeta Diário chega à sua coleção com o Boneco Funko Pop! Lois Lane! Pronta para buscar a próxima grande notícia, Lois aparece com seu visual clássico do universo Superman. Com aproximadamente 10 centímetros de altura, essa figura de vinil é perfeita para fãs da DC Comics e colecionadores que acompanham a saga do Homem de Aço!', 164.99, 164.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7rfgi-m9rjiwczje3a7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F41700892991', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
