INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16659162465', 'Kit 2 Óculos De Proteção Contra Raio Laser E Luz Pulsátil T3', 'Comprando até 12h30, enviaremos seu pedido no mesmo dia (em dias úteis). Receba seu produto rápido. Temos garantia de 3 meses e tiramos todas as dúvidas necessárias no chat. Pontos importantes: Proteja seus olhos com o Kit 2 Óculos de Proteção Contra Raio Laser e Luz Pulsátil T3. Óculos de segurança com lente de proteção em policarbonato, tratamento UV e antirrisco. Hastes flexíveis e telescópicas com 4 ajustes de comprimento para maior conforto. Parafusos de aço inoxidável garantem durabilidade. Produto original com CA - Certificado de Aprovação do MTE - Ministério do Trabalho. Especificações: CA: 28018 (validade até 2025) Norma Técnica: ANSI/ISEA.Z.87.1/2015 Conteúdo da Embalagem: 02 Óculos de Proteção com Lente Verde e Haste Ajustável Aplicação: Tratamentos cosméticos Procedimentos a laser, LEDs Remoção de tatuagem Clareamento dos dentes Conservação e Higienização: Manter em local seco, arejado e protegido da luz solar. Limpar com água corrente e sabão neutro. Secar com pano macio, evitando o uso de produtos químicos. Observação: Não utilizar papel para secar os óculos para não riscar as lentes. Tags e palavras-chave para SEO: Óculos de proteção, Raio Laser, Luz Pulsátil, Segurança Ocular, Kit 2 unidades, ENVIO RÁPIDO.', 16.58, 14.93, NULL, 'Home & Living > Tools & Home Improvement > Protective Gloves, Goggles & Masks', 'https://cf.shopee.com.br/file/br-11134201-820lt-motofy253tadef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290883399%2F16659162465', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
